-- GENERATO da contenuti/ con npm run contenuti: non modificare a mano.
-- 617 domande, 100 nel nucleo gratuito.
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q1', 'Which sentence is correct?', '["Is your sister ever lived abroad?","Has your sister ever lived abroad?","Does your sister ever lived abroad?","Have your sister ever lived abroad?"]', NULL, 1, 'Per le esperienze di vita (senza dire quando) si usa il Present Perfect: have/has + participio passato. Con ''your sister'' l''ausiliare è ''has'' e il verbo resta al participio (''lived''). ''Is'' e ''does'' non si usano per costruire questo tempo, e ''have'' non concorda con il soggetto singolare.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q2', 'Choose the correct question: ''_____ a bank in this street?''', '["Is there","There is","Are there","Is it"]', NULL, 0, 'Per chiedere se qualcosa esiste si inverte ''there is'' in ''Is there...?''. ''A bank'' è singolare, quindi non va bene ''Are there''. ''There is'' è la forma affermativa e ''Is it'' non esprime esistenza.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q3', 'Which sentence is correct?', '["Did your brother won the match last night?","Was your brother win the match last night?","Does your brother won the match last night?","Did your brother win the match last night?"]', NULL, 3, 'Nelle domande al Past Simple l''ausiliare ''did'' porta già il passato: il verbo resta alla forma base (''win'', non ''won''). ''Was'' e ''does'' non si combinano con questo verbo e con ''last night'' serve il passato.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q4', 'Choose the correct translation for ''Agosto è il mese più caldo dell''anno.''', '["August is the most hot month of the year.","August is the hotter month of the year.","August is the hottest month of the year.","August is more hot month of the year."]', NULL, 2, '''Hot'' è un aggettivo corto: il superlativo si fa con ''the + -est'' e la consonante finale si raddoppia (''hottest''). ''Most hot'' si usa solo con aggettivi lunghi, ''hotter'' è il comparativo (si usa con ''than'').', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q5', 'Choose the correct translation for ''Abbiamo comprato questa casa nel 2018.''', '["We have bought this house in 2018.","We bought this house in 2018.","We buyed this house in 2018.","We are buying this house in 2018."]', NULL, 1, 'Con un anno preciso nel passato (''in 2018'') si usa il Past Simple, non il Present Perfect. ''Buy'' è irregolare: il passato è ''bought'', non ''buyed''. ''Are buying'' è un presente.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q6', 'Which sentence compares the two bags correctly?', '["The red bag is more expensive than the blue one.","The red bag is more expensive that the blue one.","The red bag is expensiver than the blue one.","The red bag is the most expensive than the blue one."]', NULL, 0, '''Expensive'' è un aggettivo lungo: il comparativo si fa con ''more + aggettivo'' e il secondo termine si introduce con ''than''. ''That'' non è il termine di paragone, ''-er'' va solo con aggettivi corti e ''the most'' è un superlativo, che non si usa con ''than''.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q7', 'Complete the sentence: ''_____ did Anna buy that jacket?'' - ''Last Saturday.''', '["Where","Who","When","Why"]', NULL, 2, 'La risposta ''Last Saturday'' indica un momento, quindi la domanda va introdotta da ''When''. ''Where'' chiederebbe un luogo, ''Who'' una persona e ''Why'' un motivo.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q8', 'Choose the correct translation for ''Quanti libri ci sono sullo scaffale?''', '["How much books are there on the shelf?","How many books is there on the shelf?","How many book are there on the shelf?","How many books are there on the shelf?"]', NULL, 3, '''Libri'' si può contare, quindi si usa ''How many'' (non ''much'', che è per i nomi non numerabili) seguito dal plurale (''books'') e dal verbo al plurale (''are there''). ''Is there'' e ''book'' al singolare sono errori di concordanza.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q9', 'Choose the correct translation for ''Il film comincerà tra un''ora.''', '["The film will start between an hour.","The film will start in an hour.","The film will start at an hour.","The film will start for an hour."]', NULL, 1, 'Per dire ''tra'' un certo tempo da adesso si usa ''in'' + durata (''in an hour''). ''Between'' richiede due punti (between two and three), ''at'' va con l''orario preciso e ''for'' indica quanto dura qualcosa.', 'prepositions-time', 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q10', 'Choose the correct translation for ''Posso usare il tuo telefono, per favore?''', '["Can I use your phone, please?","Can I to use your phone, please?","Do I can use your phone, please?","Can I using your phone, please?"]', NULL, 0, 'Per chiedere il permesso si usa ''Can I + verbo base''. I verbi modali non vogliono ''to'' dopo di sé, non usano ''do'' nelle domande e non si usano con la forma in -ing.', 'modals-ability-permission', 'Traduzione', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q11', 'Choose the correct translation for ''Laura vive a Napoli con i suoi genitori.''', '["Laura live in Naples with her parents.","Laura living in Naples with her parents.","Laura lives in Naples with her parents.","Laura lives in Naples with she parents."]', NULL, 2, 'Con il soggetto alla terza persona singolare (Laura = she) il Present Simple vuole la -s (''lives''). Senza verbo coniugato (''living'') la frase non regge, e davanti a un nome serve l''aggettivo possessivo ''her'', non il pronome ''she''.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q12', 'Choose the correct sentence to describe what is happening now.', '["Be quiet! The baby is sleep.","Be quiet! The baby sleep.","Be quiet! The baby sleeped.","Be quiet! The baby is sleeping."]', NULL, 3, 'Per un''azione che sta succedendo adesso si usa il Present Continuous: ''is'' + verbo in -ing (''is sleeping''). Le altre forme sono errate: manca il -ing, manca la -s della terza persona, e ''sleeped'' non esiste (''sleep'' è irregolare).', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q13', 'Choose the correct question:', '["Is there any rice in the cupboard?","Are there any rice in the cupboard?","Is there a rice in the cupboard?","Is there any rices in the cupboard?"]', NULL, 0, '''Rice'' (riso) è un nome non numerabile: si usa ''Is there'' (non ''Are there''), senza ''a'' e senza plurale. Nelle domande si usa ''any''.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q14', 'Choose the correct translation for ''Da quanto tempo abiti a Milano?''', '["How long do you live in Milan?","How long have you lived in Milan?","How long you have lived in Milan?","How long did you lived in Milan?"]', NULL, 1, 'Per chiedere da quanto dura una situazione ancora vera si usa ''How long have you + participio passato''. Il presente semplice non regge questa costruzione, nella domanda l''ausiliare va prima del soggetto e dopo ''did'' il verbo non va al passato.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q15', 'Choose the correct translation for ''Mia nonna sa suonare il pianoforte.''', '["My grandmother can plays the piano.","My grandmother can to play the piano.","My grandmother knows play the piano.","My grandmother can play the piano."]', NULL, 3, '''Can'' è un verbo modale: non prende la -s della terza persona e il verbo che segue è alla forma base, senza ''to''. ''Knows play'' è sbagliato: ''know'' vuole ''how to'' (''knows how to play'').', 'modals-ability-permission', 'Traduzione', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q16', 'Choose the correct translation for ''Cosa ha mangiato Marco ieri sera?''', '["What did Marco ate last night?","What Marco ate last night?","What did Marco eat last night?","What does Marco ate last night?"]', NULL, 2, 'Nelle domande al Past Simple l''ordine è parola interrogativa + ''did'' + soggetto + verbo base (''eat''). Dopo ''did'' il verbo non si mette al passato, senza ''did'' la domanda non è formata e ''does'' è un presente.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q17', 'Choose the grammatically correct sentence:', '["We have eaten pizza last Friday night.","We ate pizza last Friday night.","We eaten pizza last Friday night.","We eat pizza last Friday night."]', NULL, 1, 'Con ''last Friday night'', un momento concluso nel passato, serve il Past Simple (''ate''). Il Present Perfect non si usa con indicazioni di tempo concluse, ''eaten'' da solo è un participio senza ausiliare e ''eat'' è un presente.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q18', 'Complete the sentence: ''In my building there are many students who _____ to university by bike.''', '["go","goes","going","to go"]', NULL, 0, 'Nella frase relativa il verbo si accorda con l''antecedente: ''students'' è plurale, quindi ''who go''. ''Goes'' è singolare e ''going'' e ''to go'' non sono forme coniugate.', 'relative-clauses', 'Grammatica', 'A2', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q19', 'Complete the sentence: ''My sister _____ her driving test in 2019.''', '["pass","has passed","passed","is passing"]', NULL, 2, 'Con un anno preciso nel passato (''in 2019'') si usa il Past Simple: ''passed''. Il Present Perfect (''has passed'') non ammette un anno concluso e le altre forme sono al presente.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q20', 'Complete the sentence: ''My umbrella is broken, so I need a new _____.''', '["ones","it","a one","one"]', NULL, 3, 'Per non ripetere un nome singolare già detto si usa ''one'': ''a new one'' = ''a new umbrella''. ''Ones'' è plurale, ''it'' indicherebbe proprio l''ombrello rotto e ''a one'' dopo ''new'' è sbagliato perché l''articolo c''è già.', 'object-pronouns', 'Grammatica', 'A2', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q21', 'Complete the sentence: ''The windows are open and I can hear music. Someone _____ at home.''', '["must to be","must be","must is","must being"]', NULL, 1, 'Per una deduzione quasi certa si usa ''must + verbo base'': ''must be at home''. Dopo un modale non si mette ''to'', né il verbo coniugato (''is''), né la forma in -ing.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q22', 'Complete the sentence: ''My sister has lived in Turin _____ she started university.''', '["for","during","since","while"]', NULL, 2, '''Since'' indica il punto di partenza di una situazione che dura ancora, anche seguito da una frase (''since she started''). ''For'' vuole una durata (for three years), ''during'' un nome e ''while'' non si usa con il Present Perfect in questo senso.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q23', 'Complete the sentence: ''What time _____ the concert begin tomorrow?''', '["is","does","do","has"]', NULL, 1, 'Per un evento programmato (orario di un concerto) si usa il Present Simple, che nelle domande vuole ''do/does''. ''The concert'' è terza persona singolare, quindi ''does''. Con ''is'' o ''has'' il verbo ''begin'' non starebbe in piedi.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q24', 'Complete the sentence: ''When my uncle was young, he _____ run a marathon in under three hours, but now he can''t.''', '["could","can","is able to","could to"]', NULL, 0, 'Per un''abilità generale nel passato si usa ''could'' + verbo base. ''Can'' e ''is able to'' sono presenti e non vanno con ''when he was young''; dopo un modale non si mette ''to'' (''could to'' è errato).', 'modals-ability-permission', 'Grammatica', 'B1', 'Modals of Ability and Permission', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q25', 'Combine the sentences correctly: ''I called Laura yesterday evening. She was cooking dinner.''', '["I called Laura yesterday evening while she cooks dinner.","I called Laura yesterday evening during she was cooking dinner.","I called Laura yesterday evening while was cooking dinner.","I called Laura yesterday evening while she was cooking dinner."]', NULL, 3, '''While'' introduce l''azione in corso nel passato e vuole soggetto + Past Continuous (''she was cooking''). ''Cooks'' è un presente che non si accorda con il passato, ''during'' regge solo un nome e senza soggetto (''while was cooking'') la frase è incompleta.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q26', 'Complete the sentence: ''My sister always does her homework very _____.''', '["careful","carefully","carefulness","care"]', NULL, 1, 'Per descrivere come si fa un''azione serve un avverbio, che di solito si forma con -ly: ''carefully''. ''Careful'' è un aggettivo, ''carefulness'' e ''care'' sono nomi.', 'adverbs-manner', 'Grammatica', 'B1', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q27', 'Complete the sentence: ''Our teacher wants _____ to finish the project by Friday.''', '["we","our","us","ours"]', NULL, 2, 'Dopo ''want'' si usa il pronome complemento + infinito con ''to'': ''wants us to finish''. ''We'' è un pronome soggetto, ''our'' è un aggettivo possessivo e ''ours'' un pronome possessivo: nessuno dei tre può stare qui.', 'object-pronouns', 'Grammatica', 'A2', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q28', 'Complete the sentence: ''I need to buy _____ apples for the cake.''', '["a","much","an","some"]', NULL, 3, '''Apples'' è plurale e numerabile, quindi va bene ''some''. ''A'' e ''an'' vogliono un nome singolare e ''much'' un nome non numerabile.', 'quantifiers', 'Grammatica', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q29', 'Complete the sentence: ''We _____ a great film at the cinema last night.''', '["saw","see","seen","have seen"]', NULL, 0, 'Con ''last night'' si usa il Past Simple. ''See'' è irregolare: il passato è ''saw'', mentre ''seen'' è il participio (serve un ausiliare). Il Present Perfect non va con un tempo concluso.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q30', 'Complete the sentence: ''The exam _____ at nine o''clock tomorrow, so don''t be late.''', '["start","will starts","starts","starting"]', NULL, 2, 'Per un orario fissato (l''inizio di un esame) in inglese si usa il Present Simple anche se si parla del futuro, con la -s per ''it'' (''starts''). ''Start'' manca della -s, ''will starts'' è sbagliato perché dopo ''will'' non c''è -s e ''starting'' non è coniugato.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q31', 'Choose the correct negative sentence:', '["There isn''t no sugar in my coffee.","There isn''t any sugar in my coffee.","There aren''t any sugar in my coffee.","There is any sugar in my coffee."]', NULL, 1, '''Sugar'' non è numerabile, quindi ''there isn''t'', non ''aren''t''. Nelle frasi negative si usa ''any'' (''isn''t any''); ''isn''t no'' è una doppia negazione e ''any'' non si usa in una frase affermativa.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q32', 'Complete the sentence: ''How long _____ your brother lived in London?''', '["has","have","did","is"]', NULL, 0, 'Il Present Perfect si forma con have/has + participio passato. ''Your brother'' è terza persona singolare, quindi ''has''. ''Have'' non concorda con il soggetto, ''did'' vorrebbe il verbo base e ''is'' non si usa qui.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q33', 'Complete the sentence: ''Listen! Someone _____ at the door.''', '["knocks","knock","knocked","is knocking"]', NULL, 3, '''Listen!'' indica che l''azione è in corso adesso: Present Continuous, ''is knocking''. Il presente semplice (''knocks'') descrive abitudini, ''knock'' manca della -s e ''knocked'' è un passato.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q34', 'Complete the sentence: ''Who _____ the window in the kitchen?''', '["did broke","breaked","broke","has broke"]', NULL, 2, 'Quando ''who'' è il soggetto della domanda non si usa ''did'': il verbo va direttamente al passato (''Who broke...?''). ''Break'' è irregolare, quindi ''breaked'' non esiste; ''did broke'' e ''has broke'' sono forme errate.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q35', 'Choose the correct translation for ''Questa è la città più bella che io abbia mai visitato.''', '["This is the more beautiful city I have ever visited.","This is the most beautiful city I have ever visited.","This is the beautifullest city I have ever visited.","This is the most beautifully city I have ever visited."]', NULL, 1, '''Beautiful'' è un aggettivo lungo: il superlativo si fa con ''the most + aggettivo''. ''More'' è un comparativo, ''-est'' non si aggiunge ad aggettivi lunghi e ''beautifully'' è un avverbio, non può stare davanti a un nome.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q36', 'Choose the correct translation for ''Mio fratello gioca a calcio ogni sabato.''', '["My brother plays football every Saturday.","My brother play football every Saturday.","My brother is play football every Saturday.","My brother plays to football every Saturday."]', NULL, 0, 'Un''abitudine (ogni sabato) si esprime con il Present Simple, e alla terza persona singolare il verbo prende la -s (''plays''). Con gli sport si dice ''play football'', senza preposizione, e non si mescola ''is'' con il verbo base.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q37', 'Complete the sentence: ''What time _____ the film finish last night?''', '["do","have","did","was"]', NULL, 2, 'Per una domanda su un momento passato si usa l''ausiliare ''did'' seguito dal verbo base. ''Do'' è presente, ''have'' vorrebbe il participio e ''was'' non si combina con ''finish''.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q38', 'Complete the sentence: ''Excuse me, where is your friend _____? Is he Spanish?''', '["of","from","by","at"]', NULL, 1, 'Per chiedere la provenienza si usa la preposizione ''from'' (''Where is he from?''). ''Of'', ''by'' e ''at'' non hanno questo significato.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q39', 'Complete the sentence: ''The shop has been closed _____ last Tuesday.''', '["for","since","from","until"]', NULL, 1, 'Con il Present Perfect e un punto preciso nel tempo (''last Tuesday'') si usa ''since''. ''For'' vuole una durata (for three days), ''from'' non regge il Present Perfect in questo modo e ''until'' indica un limite finale.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q40', 'Choose the correct translation for ''Ieri non ho studiato per l''esame.''', '["I didn''t study for the exam yesterday.","I didn''t studied for the exam yesterday.","I wasn''t study for the exam yesterday.","I don''t studied for the exam yesterday."]', NULL, 0, 'La negazione del Past Simple si fa con ''didn''t'' + verbo base: ''I didn''t study''. Il passato lo porta già ''didn''t'', quindi ''studied'' è un errore; ''wasn''t'' e ''don''t'' non sono corretti qui.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q41', 'Complete the sentence: ''The last ferry to the island _____ at 11 p.m., so we mustn''t miss it.''', '["leaving","leave","left","leaves"]', NULL, 3, 'Per un orario ufficiale (l''ultimo traghetto) si usa il Present Simple, con la -s per la terza persona (''leaves''). ''Leave'' manca della -s, ''left'' è un passato e ''leaving'' non è coniugato.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q42', 'Complete the sentence: ''He is the kindest teacher I have _____ met.''', '["never","always","ever","still"]', NULL, 2, 'Dopo un superlativo con il Present Perfect si usa ''ever'' (''il più gentile che abbia mai incontrato''). ''Never'' contraddice il senso, ''always'' e ''still'' non hanno senso con ''met''.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q43', 'Complete the sentence: ''Our team _____ the national cup in 2016.''', '["won","wins","has won","was winning"]', NULL, 0, 'Con un anno preciso nel passato serve il Past Simple: ''won''. ''Wins'' è un presente, ''has won'' non si usa con un anno concluso e ''was winning'' indicherebbe un''azione in corso.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q44', 'Choose the correct translation for ''Hai già conosciuto il nuovo professore?''', '["Did you already met the new professor?","Have you already met the new professor?","Have you already meet the new professor?","Are you already meeting the new professor?"]', NULL, 1, 'Per un''esperienza senza tempo preciso si usa il Present Perfect: ''Have you already met...?'' con il participio ''met''. Dopo ''did'' il verbo andrebbe alla forma base, ''meet'' non è un participio e ''are you meeting'' parla di un incontro in corso.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q45', 'Choose the correct translation for ''Lavoro qui da tre anni.''', '["I have worked here for three years.","I work here since three years.","I have worked here since three years.","I am working here for three years."]', NULL, 0, 'Una situazione iniziata nel passato e ancora in corso si esprime con il Present Perfect. Con una durata (tre anni) si usa ''for'', mentre ''since'' vuole un punto di partenza. In italiano si dice ''lavoro'', ma in inglese il presente semplice non va con ''for/since''.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q46', 'Choose the correct translation for ''Mi piace la macchina di Paolo.''', '["I like Paolo car.","I like the car''s Paolo.","I like Paolo''s car.","I''m like Paolo''s car."]', NULL, 2, 'Il possesso si esprime con nome + ''s (''Paolo''s car''), senza articolo davanti. Senza ''s manca il possessivo, l''ordine inverso è sbagliato e ''I''m like'' non significa ''mi piace'' (si dice ''I like'').', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q47', 'Complete the sentence: ''In my town _____ are three cinemas.''', '["It","This","That","There"]', NULL, 3, 'Per dire che qualcosa esiste si usa ''there is/there are''. ''It'', ''this'' e ''that'' non introducono un''esistenza e non vanno con ''are'' in questa frase.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q48', 'Complete the sentence: ''My parents _____ dinner in the kitchen at the moment.''', '["are cooking","cook","cooking","cooks"]', NULL, 0, '''At the moment'' indica un''azione in corso adesso, quindi Present Continuous: ''are'' + verbo in -ing. ''Cook'' e ''cooks'' sono presenti semplici (abitudini) e ''cooking'' da solo non ha l''ausiliare.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q49', 'Choose the correct sentence:', '["If the weather will be nice tomorrow, we go to the beach.","If the weather is nice tomorrow, we would go to the beach.","If the weather is nice tomorrow, we will go to the beach.","If the weather be nice tomorrow, we will go to the beach."]', NULL, 2, 'Il primo condizionale si forma con ''if + Present Simple'' e ''will + verbo base'' nella principale. Nella frase con ''if'' non si mette ''will'', ''would'' appartiene al secondo condizionale e ''be'' senza ''is'' non è corretto.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q50', 'Complete the sentence: ''She _____ learning Chinese since she was twelve.''', '["is","has been","was","had been"]', NULL, 1, '''Since'' con un punto di partenza nel passato e un''azione ancora in corso richiede il Present Perfect Continuous: ''has been learning''. ''Is'' e ''was'' non reggono ''since'', e ''had been'' si usa solo se c''è un altro momento passato di riferimento.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q51', 'Complete the sentence: ''What _____ for dinner last night?''', '["did you cook","you cooked","did you cooked","are you cooking"]', NULL, 0, 'Nelle domande al Past Simple si usa ''did + soggetto + verbo base'': ''What did you cook...?''. Senza ''did'' la domanda non è formata, dopo ''did'' il verbo non va al passato e ''are you cooking'' è un presente.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q52', 'Choose the correct sentence for comparing two phones:', '["This phone is more much cheaper than that one.","This phone is very cheaper than that one.","This phone is much cheaper as that one.","This phone is much cheaper than that one."]', NULL, 3, 'Per rafforzare un comparativo si mette ''much'' davanti (''much cheaper'') e il secondo termine si introduce con ''than''. ''Very'' non si usa con i comparativi, ''more much'' è nell''ordine sbagliato e ''as'' non va con il comparativo.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q53', 'Complete the sentence: ''Anna is ill. She _____ in bed since Sunday.''', '["was","is","has been","had been"]', NULL, 2, '''Since Sunday'' collega il passato al presente, quindi serve il Present Perfect: ''has been''. ''Was'' e ''is'' non vanno con ''since'' e ''had been'' ha bisogno di un altro momento passato di riferimento.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q54', 'Complete the sentence: ''The Moon _____ around the Earth every 27 days.''', '["go","goes","went","is going"]', NULL, 1, 'Per un fatto che è sempre vero si usa il Present Simple, con la -s alla terza persona singolare: ''the Moon goes''. ''Go'' manca della -s, ''went'' è un passato e ''is going'' descrive un''azione in corso, non un fatto ripetuto ''ogni 27 giorni''.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q55', 'Complete the sentence: ''Where is Paolo?'' - ''He has _____ to the supermarket. He''ll be back in ten minutes.''', '["been","go","went","gone"]', NULL, 3, '''Has gone to'' significa che è andato e non è ancora tornato; ''has been to'' vuol dire che c''è stato ed è tornato. Qui Paolo non c''è ancora, quindi ''gone''. ''Go'' e ''went'' non sono participi passati.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q56', 'Complete the sentence: ''Are they _____ the match on TV?''', '["watching","watch","watched","watches"]', NULL, 0, 'L''ausiliare ''are'' introduce il Present Continuous, che vuole la forma in -ing: ''Are they watching...?''. Le altre forme non vanno dopo ''are''.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q57', 'Choose the correct translation for ''Hai mai suonato la chitarra?''', '["Did you ever played the guitar?","Are you ever played the guitar?","Have you ever played the guitar?","Have you never played the guitar?"]', NULL, 2, 'Per chiedere di un''esperienza di vita si usa il Present Perfect con ''ever'': ''Have you ever played...?''. ''Did you ever played'' ha il verbo al passato dopo ''did'', ''are'' non forma questo tempo e ''never'' significa ''non... mai'', non ''mai'' in una domanda.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q58', 'Complete the sentence: ''The plane _____ just landed.''', '["have","has","is","did"]', NULL, 1, '''Just'' si usa tipicamente con il Present Perfect: ''has just landed''. ''The plane'' è singolare, quindi ''has'' e non ''have''; ''is'' e ''did'' non si combinano con il participio ''landed'' in questo modo.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q59', 'Choose the correct translation for ''Marta non ha ancora risposto alla mia email.''', '["Marta hasn''t answered my email yet.","Marta haven''t answered my email yet.","Marta doesn''t answer my email yet.","Marta hasn''t answer my email yet."]', NULL, 0, 'Per qualcosa di atteso che non è ancora successo si usa il Present Perfect negativo con ''yet'': ''hasn''t answered''. Con ''Marta'' serve ''hasn''t'' (non ''haven''t''), il verbo deve essere al participio, e il presente semplice non esprime ''non ancora''.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q60', 'Complete the sentence: ''_____ your parents ever visited Scotland?''', '["Has","Did","Are","Have"]', NULL, 3, 'Il Present Perfect si forma con have/has + participio. ''Your parents'' è plurale, quindi ''Have''. ''Has'' non concorda, ''did'' vorrebbe il verbo base e ''are'' non forma questo tempo.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q61', 'Translate ''Lui vive qui da dieci anni.''', '["He has lived here for ten years.","He is living here since ten years.","He lived here since ten years.","He have lived here for ten years."]', NULL, 0, 'Se un''azione iniziata nel passato continua ancora oggi ("vive qui da dieci anni") si usa il Present Perfect, non il presente. Dopo "da" con un periodo di tempo (dieci anni) in inglese si usa ''for''; ''since'' vuole un punto di partenza preciso. ''He have'' è sbagliato perché con ''he'' serve ''has''.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q62', 'Translate ''Ci sono molte macchine per strada oggi.''', '["There are many cars on the street today.","They are many cars on the street today.","There is many cars on the street today.","There have many cars on the street today."]', NULL, 0, 'Per dire che qualcosa esiste o è presente, con un nome plurale (many cars) si usa ''There are''. ''They are'' significa "loro sono" e non traduce "ci sono"; ''There is'' e ''There have'' non vanno con il plurale.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q63', 'Complete the sentence: ''_____ any milk in the fridge?''', '["Is there","Are there","There is","There are"]', NULL, 0, '''Milk'' è un nome non numerabile, quindi singolare: la domanda si fa con ''Is there''. Nella domanda l''ordine si inverte (Is there...?), per cui ''There is'' e ''There are'' sono forme affermative e non vanno qui.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q64', 'Translate ''Non c''è nessun problema.''', '["There is no problem.","There isn''t no problem.","There are no problem.","There have no problem."]', NULL, 0, '"Non c''è nessun problema" si dice ''There is no problem'': ''no'' contiene già la negazione, quindi non si aggiunge ''isn''t'' (doppia negazione). ''There are'' non va con ''problem'', che è singolare, e ''there have'' non esiste: "c''è/ci sono" si traduce con ''there is/are''.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q65', 'Complete the sentence: ''_____ some apples on the table.''', '["There are","There is","They are","It is"]', NULL, 0, '''Some apples'' è plurale, quindi si dice ''There are some apples''. ''There is'' è per il singolare, mentre ''They are'' e ''It is'' non servono a dire che qualcosa si trova da qualche parte.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q66', 'Translate ''C''è un cane nel giardino?''', '["Is there a dog in the garden?","Are there a dog in the garden?","There is a dog in the garden?","Does there a dog in the garden?"]', NULL, 0, 'La domanda con "c''è" si forma invertendo: ''Is there a dog...?''. ''Are there'' è plurale e non va con ''a dog'', ''There is...?'' non inverte, e ''Does there'' non esiste perché ''there is'' non usa ''do''.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q67', 'Complete the sentence: ''I _____ to the cinema yesterday.''', '["went","go","am going","have gone"]', NULL, 0, '''Yesterday'' indica un momento finito nel passato, quindi serve il Past Simple: ''went'' (passato irregolare di ''go''). ''Go'' e ''am going'' sono presenti, e il Present Perfect (''have gone'') non si usa con un tempo preciso come ''yesterday''.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q68', 'Translate ''Non hanno studiato per l''esame.''', '["They didn''t study for the exam.","They don''t studied for the exam.","They wasn''t study for the exam.","They haven''t study for the exam."]', NULL, 0, 'La negazione del Past Simple si forma con ''didn''t'' + verbo base (study), senza -ed: ''They didn''t study''. In ''don''t studied'' e ''haven''t study'' il verbo o l''ausiliare sono sbagliati, e ''wasn''t'' non si usa con ''they''.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q69', 'Complete the sentence: ''_____ you see the football match last night?''', '["Did","Do","Have","Were"]', NULL, 0, 'Nelle domande al Past Simple l''ausiliare è ''Did'' e il verbo resta alla forma base (Did you see...?). ''Do'' è presente, ''Have'' vorrebbe il participio passato (seen) e ''Were'' non si usa con ''see''.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q70', 'Translate ''Lei ha comprato un nuovo telefono la settimana scorsa.''', '["She bought a new phone last week.","She buys a new phone last week.","She buyed a new phone last week.","She have bought a new phone last week."]', NULL, 0, '''Last week'' indica un momento passato concluso, quindi si usa il Past Simple; ''buy'' è irregolare e fa ''bought'' (''buyed'' non esiste). ''Buys'' è un presente e ''have bought'' (Present Perfect) non si usa con ''last week''.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q71', 'Complete the sentence: ''We _____ very tired after the trip.''', '["were","was","did be","have been"]', NULL, 0, 'Il Past Simple di ''to be'' con ''we'' è ''were'' (was è solo per I/he/she/it). ''Did be'' non esiste, perché ''be'' non usa ''did'' qui, e ''have been'' non è un passato semplice.', 'past-simple', 'Grammatica', 'A2', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q72', 'Translate ''Quando sei arrivato?''', '["When did you arrive?","When you arrived?","When do you arrive?","When have you arrived?"]', NULL, 0, 'Nelle domande con una parola interrogativa al Past Simple: parola interrogativa + did + soggetto + verbo base (When did you arrive?). Senza ''did'' la frase è sbagliata, e ''do'' o ''have'' non corrispondono al passato semplice.', 'past-simple', 'Traduzione', 'A2', 'Past Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q73', 'Complete the sentence: ''Please be quiet, I _____.''', '["am working","work","working","am work"]', NULL, 0, '"Please be quiet" indica che l''azione si sta svolgendo ora, quindi serve il Present Continuous: am/is/are + verbo in -ing (I am working). ''Working'' da solo manca di ''am'', ''work'' è il presente semplice e ''am work'' non è una forma corretta.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q74', 'Translate ''Cosa stanno facendo?''', '["What are they doing?","What do they do?","What they are doing?","What are they do?"]', NULL, 0, 'La domanda nel Present Continuous è: parola interrogativa + are/is + soggetto + verbo in -ing (What are they doing?). ''What do they do?'' chiede cosa fanno di solito (professione o abitudine), mentre gli altri due ordinano male la frase o usano ''do'' senza -ing.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q75', 'Complete the sentence: ''She _____ to music at the moment.''', '["is listening","listens","listening","listen"]', NULL, 0, '''At the moment'' indica un''azione in corso ora: serve il Present Continuous, ''She is listening''. ''Listens'' è per le abitudini, mentre ''listening'' senza ''is'' e ''listen'' senza -s non sono frasi corrette.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q76', 'Translate ''Non sto leggendo un libro, sto guardando la TV.''', '["I''m not reading a book, I''m watching TV.","I don''t read a book, I watch TV.","I''m not read a book, I''m watch TV.","I not reading a book, I watching TV."]', NULL, 0, 'Per due azioni in corso adesso si usa il Present Continuous: ''I''m not reading, I''m watching''. Il presente semplice (''I don''t read'') esprime un''abitudine; ''not read'' e ''I not reading'' mancano dell''ausiliare corretto.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q77', 'Complete the sentence: ''_____ it raining outside?''', '["Is","Does","Are","Do"]', NULL, 0, 'Il Present Continuous si forma con ''to be'' + -ing (it is raining), quindi la domanda comincia con ''Is it raining...?''. Con ''it'' non vanno ''Does'' e ''Do'' (che vorrebbero il verbo base), né ''Are'' (che va con you/we/they).', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q78', 'Complete the sentence: ''If you study hard, you _____ the exam.''', '["will pass","will passing","would pass","passed"]', NULL, 0, 'Nel First Conditional (condizione reale e possibile) si usa if + presente semplice nella frase con ''if'' e ''will'' + verbo base nella principale: ''you will pass''. ''Would pass'' è per situazioni ipotetiche, ''passed'' è un passato e ''will passing'' è sbagliato perché dopo ''will'' serve il verbo base.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q79', 'Translate ''Se piove, non andremo in spiaggia.''', '["If it rains, we won''t go to the beach.","If it will rain, we don''t go to the beach.","If it rain, we won''t go to the beach.","If it rains, we didn''t go to the beach."]', NULL, 0, 'Nel First Conditional il verbo dopo ''if'' è al presente (it rains) e la principale ha ''will'' (we won''t go). ''If it will rain'' è sbagliato perché dopo ''if'' non si usa ''will'', ''it rain'' manca della -s e ''didn''t'' è un passato.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q80', 'Complete the sentence: ''I will call you if I _____ any news.''', '["hear","will hear","heard","hearing"]', NULL, 0, 'Dopo ''if'' si usa il presente semplice anche se si parla del futuro: ''if I hear''. ''Will hear'' dopo ''if'' è un errore tipico, mentre ''heard'' e ''hearing'' non sono le forme richieste.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q81', 'Translate ''Cosa farai se perdi il treno?''', '["What will you do if you miss the train?","What do you do if you will miss the train?","What would you do if you miss the train?","What will you do if you missed the train?"]', NULL, 0, 'La domanda del First Conditional ha ''will'' nella principale e il presente semplice dopo ''if'': ''What will you do if you miss the train?''. ''Would'' e ''missed'' appartengono a un''ipotesi irreale, e dopo ''if'' non va ''will miss''.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q82', 'Complete the sentence: ''If she _____ invite me, I won''t go to the party.''', '["doesn''t","don''t","won''t","didn''t"]', NULL, 0, 'Con ''she'' (terza persona singolare) la negazione del presente semplice si fa con ''doesn''t'': ''If she doesn''t invite me''. ''Don''t'' va con I/you/we/they, ''won''t'' non si usa dopo ''if'' in questo caso e ''didn''t'' è un passato.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q83', 'Translate ''Se non ti sbrighi, faremo tardi.''', '["If you don''t hurry, we will be late.","If you won''t hurry, we are late.","If you aren''t hurry, we will be late.","If you don''t hurry, we would be late."]', NULL, 0, 'Nel First Conditional: if + presente (anche negativo, ''don''t hurry'') e ''will'' nella principale (we will be late). ''Won''t hurry'' dopo ''if'' è sbagliato, ''aren''t hurry'' mescola ''to be'' e un verbo, e ''would be'' appartiene all''ipotesi irreale.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q84', 'Complete the sentence: ''Russia is the _____ country in the world.''', '["largest","larger","most large","more large"]', NULL, 0, 'Il superlativo degli aggettivi corti si forma con ''the'' + -est: ''the largest''. ''Larger'' è un comparativo (serve ''than''), mentre ''most large'' e ''more large'' non si usano con un aggettivo corto.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q85', 'Translate ''L''inglese è più facile del cinese.''', '["English is easier than Chinese.","English is more easy than Chinese.","English is easiest than Chinese.","English is much easy than Chinese."]', NULL, 0, 'Il comparativo di maggioranza di ''easy'' è ''easier'' (la -y diventa -ier), seguito da ''than''. ''More easy'' non si usa con un aggettivo corto, ''easiest'' è il superlativo e ''much easy'' non è un comparativo.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q86', 'Complete the sentence: ''This book is _____ interesting than the last one.''', '["more","most","much","very"]', NULL, 0, 'Con gli aggettivi lunghi (interesting) il comparativo si forma con ''more'' + aggettivo + ''than''. ''Most'' è il superlativo, ''much'' e ''very'' non formano un comparativo e non possono stare prima di ''interesting than''.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q87', 'Translate ''È il film peggiore che abbia mai visto.''', '["It''s the worst movie I''ve ever seen.","It''s the worse movie I''ve ever seen.","It''s the baddest movie I''ve ever seen.","It''s the most bad movie I''ve ever seen."]', NULL, 0, '''Bad'' ha il comparativo e il superlativo irregolari: ''worse'' e ''the worst''. ''The worse'' è un comparativo, mentre ''baddest'' e ''most bad'' non esistono in inglese standard.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q88', 'Complete the sentence: ''My brother is much _____ than me.''', '["taller","tall","tallest","more tall"]', NULL, 0, 'Dopo ''much'' serve un comparativo, e il comparativo di ''tall'' è ''taller'' (+ than). ''Tall'' è la forma base, ''tallest'' è il superlativo e ''more tall'' non si usa con un aggettivo corto.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q89', 'Translate ''Questa è la città più costosa d''Europa.''', '["This is the most expensive city in Europe.","This is the more expensive city in Europe.","This is the expensivest city in Europe.","This is most expensive city in Europe."]', NULL, 0, 'Con un aggettivo lungo (expensive) il superlativo si forma con ''the most'': ''the most expensive city''. ''The more'' è un comparativo, ''expensivest'' non esiste e senza ''the'' la frase è incompleta.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q90', 'Complete the sentence: ''I have been studying English _____ three years.''', '["for","since","from","during"]', NULL, 0, 'Con un periodo di tempo (three years) si usa ''for''; ''since'' vuole invece un punto di partenza (since 2020). ''From'' e ''during'' non si usano così con un''azione che dura fino ad ora.', 'prepositions-time', 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q91', 'Translate ''Lavora in quella banca dal 2015.''', '["He has worked in that bank since 2015.","He works in that bank from 2015.","He worked in that bank since 2015.","He has worked in that bank for 2015."]', NULL, 0, '"Dal 2015" indica un punto di partenza preciso, quindi si usa ''since'' con il Present Perfect: ''has worked ... since 2015''. ''From 2015'' con il presente è scorretto, ''worked'' al passato indica un lavoro finito e ''for 2015'' è sbagliato perché 2015 non è una durata.', 'prepositions-time', 'Traduzione', 'B1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q92', 'Complete the sentence: ''She hasn''t eaten anything _____ yesterday morning.''', '["since","for","from","until"]', NULL, 0, '''Yesterday morning'' è un momento preciso nel passato, cioè un punto di partenza: si usa ''since'' con il Present Perfect (hasn''t eaten). ''For'' vuole invece una durata (for two days), e ''from'' e ''until'' non vanno bene qui.', 'prepositions-time', 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q93', 'Translate ''Stiamo aspettando da due ore.''', '["We have been waiting for two hours.","We are waiting since two hours.","We have been waiting since two hours.","We wait for two hours."]', NULL, 0, '"Due ore" è una durata, quindi si usa ''for'': ''We have been waiting for two hours''. ''Since two hours'' è un errore tipico, perché ''since'' vuole un punto di partenza (since 8 o''clock). Il presente semplice ''We wait'' non esprime "da due ore".', 'prepositions-time', 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q94', 'Complete the sentence: ''I haven''t seen him _____ a long time.''', '["for","since","during","from"]', NULL, 0, '''A long time'' è una durata, quindi si usa ''for'' (I haven''t seen him for a long time). ''Since'' richiederebbe un punto di partenza (since Monday), mentre ''during'' e ''from'' non si usano in questa frase.', 'prepositions-time', 'Grammatica', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q95', 'Complete the sentence: ''He usually _____ up at 7 AM.''', '["wakes","wake","is waking","waked"]', NULL, 0, '''Usually'' indica un''abitudine, quindi si usa il presente semplice; con ''he'' il verbo prende la -s: ''wakes''. ''Wake'' non ha la -s, ''is waking'' è un''azione in corso e ''waked'' non è un passato corretto.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q96', 'Translate ''I miei genitori non vivono a Londra.''', '["My parents don''t live in London.","My parents doesn''t live in London.","My parents aren''t live in London.","My parents not live in London."]', NULL, 0, 'Con un soggetto plurale (my parents) la negazione del presente semplice è ''don''t'' + verbo base. ''Doesn''t'' è solo per he/she/it, ''aren''t live'' mescola ''to be'' e un verbo, e ''not live'' manca dell''ausiliare.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q97', 'Complete the sentence: ''_____ she like chocolate?''', '["Does","Do","Is","Has"]', NULL, 0, 'Nelle domande al presente semplice con he/she/it l''ausiliare è ''Does'' e il verbo resta alla forma base (Does she like...?). ''Do'' va con I/you/we/they, ''Is'' e ''Has'' non si usano con ''like'' in questo modo.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q98', 'Translate ''Il treno parte alle 8 in punto.''', '["The train leaves at 8 o''clock.","The train leaving at 8 o''clock.","The train leave at 8 o''clock.","The train left at 8 o''clock."]', NULL, 0, 'Gli orari e i programmi fissi (come quelli dei treni) si esprimono con il presente semplice: ''The train leaves at 8''. ''Leave'' manca della -s, ''left'' è un passato e ''leaving'' da solo non è una frase corretta senza ''is''.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q99', 'Complete the sentence: ''Water _____ at 100 degrees Celsius.''', '["boils","boil","is boiling","boiled"]', NULL, 0, 'Le verità generali si esprimono con il presente semplice, e con un soggetto singolare (''water'') il verbo prende la -s: ''boils''. ''Boil'' manca della -s, ''is boiling'' indica un''azione in corso e ''boiled'' è un passato.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q100', 'Complete the sentence: ''This is my _____ car.'' (The car belongs to my friend)', '["friend''s","friends''","friend","friends"]', NULL, 0, 'Per un solo possessore si aggiunge ''s al nome singolare: ''my friend''s car'' (la macchina di un amico). ''Friends'''' indicherebbe più amici, mentre ''friend'' e ''friends'' senza apostrofo non esprimono il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q101', 'Translate ''Dov''è il computer di Marco?''', '["Where is Marco''s computer?","Where is the Marco''s computer?","Where is Marcos'' computer?","Where is Marco computer?"]', NULL, 0, 'Per le persone l''inglese usa il genitivo sassone (''s): ''Marco''s computer''. Con ''s non si mette l''articolo (''the Marco''s'' è sbagliato), ''Marcos'''' è scritto male e ''Marco computer'' manca del ''s.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q102', 'Complete the sentence: ''Those are my _____ toys.'' (The toys belong to my dogs)', '["dogs''","dog''s","dogs","dog"]', 'of dogs', 0, 'I possessori sono più cani (plurale regolare in -s), quindi si aggiunge solo l''apostrofo: ''dogs''''. ''Dog''s'' indica un solo cane, e ''dogs'' e ''dog'' senza apostrofo non esprimono il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q103', 'Translate ''La borsa di Sarah è rossa.''', '["Sarah''s bag is red.","The Sarah''s bag is red.","Sarahs bag is red.","Sarah'' bag is red."]', NULL, 0, 'Per esprimere possesso con una persona si usa ''s dopo il nome: ''Sarah''s bag''. Con ''s non si mette l''articolo (''the Sarah''s'' è sbagliato), ''Sarahs'' non ha l''apostrofo e ''Sarah'''' è scritto male per un nome singolare.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q104', 'Complete the sentence: ''We went to my _____ house yesterday.'' (The house belongs to my parents)', '["parents''","parent''s","parents","parent"]', 'parents''s', 0, '''Parents'' è un plurale regolare in -s, quindi il possesso si forma con il solo apostrofo finale: ''my parents'' house''. ''Parent''s'' indicherebbe un solo genitore, mentre ''parents'' e ''parent'' senza apostrofo non esprimono il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q105', 'Complete the sentence: ''How _____ milk is left?''', '["much","many","a lot of","any"]', 'lot', 0, '''Milk'' è non numerabile, quindi nelle domande sulla quantità si usa ''How much''. ''How many'' è per i nomi numerabili plurali, mentre ''a lot of'' e ''any'' non completano ''How ... milk''.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q106', 'Translate ''Non ho molti amici.''', '["I don''t have many friends.","I don''t have much friends.","I don''t have a lot friends.","I don''t have many friend."]', 'I don''t have a many friends.', 0, '''Friends'' è numerabile plurale, e nelle frasi negative per "molti" si usa ''many'': ''I don''t have many friends''. ''Much'' si usa con i nomi non numerabili, ''a lot friends'' manca di ''of'', e dopo ''many'' il nome resta al plurale (''friend'' è sbagliato).', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q107', 'Complete the sentence: ''There are _____ people at the concert.''', '["a lot of","much","a lot","many of"]', NULL, 0, 'Nelle frasi affermative per una grande quantità si usa ''a lot of'' + nome: ''a lot of people''. ''Much'' non si usa così in una frase affermativa e con ''people'', ''a lot'' senza ''of'' e ''many of'' non funzionano davanti a un nome.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q108', 'Translate ''Quanto zucchero vuoi nel caffè?''', '["How much sugar do you want in your coffee?","How many sugar do you want in your coffee?","How much of sugar do you want in your coffee?","What much sugar do you want in your coffee?"]', NULL, 0, '''Sugar'' è non numerabile, quindi "quanto" si dice ''How much'' e il nome segue direttamente. ''How many'' è per i numerabili, ''much of sugar'' non è corretto e ''What much'' non esiste.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q109', 'Complete the sentence: ''She has very _____ free time these days.''', '["little","few","a few","many"]', NULL, 0, '''Time'' è non numerabile, quindi "poco" si dice ''little'': ''very little free time''. ''Few'' e ''a few'' si usano solo con nomi numerabili plurali, e ''many'' non va con un nome non numerabile.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q110', 'Translate ''Ci sono troppe macchine in questa città.''', '["There are too many cars in this city.","There is too much cars in this city.","There are too much cars in this city.","There are too many of cars in this city."]', 'There are too many car in this city.', 0, '''Cars'' è numerabile plurale, quindi "troppe" si dice ''too many''. ''Too much'' si usa con i nomi non numerabili, e ''There is'' non va con un plurale. ''Too many of cars'' è sbagliato: ''of'' si mette solo davanti a un articolo o a un pronome (''too many of the cars'').', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q111', 'Complete the sentence: ''Where _____ you born?''', '["were","was","are","did"]', 'have', 0, '"Dove sei nato?" si dice ''Where were you born?'', perché ''be born'' si usa al passato e con ''you'' il passato di ''to be'' è ''were''. ''Was'' è per I/he/she/it, ''are'' è un presente e ''did'' non si usa con ''born''.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q112', 'Translate ''Da dove viene tuo fratello?''', '["Where does your brother come from?","Where do your brother come from?","Where is your brother come from?","Where does your brother comes from?"]', 'Where comes your brother from?', 0, 'Con ''your brother'' (terza persona singolare) la domanda al presente semplice usa ''does'' e il verbo base: ''Where does your brother come from?''. ''Do'' va con il plurale, ''is ... come'' mescola due verbi e ''comes'' dopo ''does'' non è corretto (la -s è già in ''does'').', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q113', 'Complete the sentence: ''_____ country are you from?''', '["Which","Whose","Where","How"]', NULL, 0, '''Which'' si usa con un nome che segue (''Which country'') per scegliere tra più possibilità. ''Where'' e ''How'' non possono essere seguiti direttamente da ''country'', e ''Whose'' chiede di chi è qualcosa.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q114', 'Translate ''Loro sono spagnoli?''', '["Are they Spanish?","Are they Spain?","Do they Spanish?","Is they Spanish?"]', 'Are they from Spanish?', 0, 'Con il verbo ''to be'' la domanda si fa invertendo: ''Are they Spanish?''. ''Spain'' è il paese, mentre ''Spanish'' è l''aggettivo di nazionalità. ''Do they Spanish'' non ha un verbo adatto e ''Is they'' non concorda.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q115', 'Complete the sentence: ''_____ is the capital of Italy?''', '["What","When","How","Who"]', NULL, 0, 'Per chiedere un''informazione come "qual è la capitale" si usa ''What is...?''. ''When'' chiede un momento, ''Who'' una persona e ''How'' un modo o una condizione: nessuno dei tre chiede il nome di una città.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q116', 'Translate ''Di dov''è Maria?''', '["Where is Maria from?","Where does Maria from?","Where is from Maria?","Where Maria is from?"]', NULL, 0, 'Per chiedere la provenienza la forma standard è ''Where is Maria from?'', con la preposizione in fondo. ''Where does Maria from'' ha ''does'' ma manca un verbo, ''Where is from Maria'' ha l''ordine delle parole sbagliato e ''Where Maria is from'' non ha l''inversione della domanda.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q117', 'Translate ''Questo è il libro più lungo che abbia mai letto.''', '["This is the longest book I have ever read.","This is the most long book I have ever read.","This is the longer book I have ever read.","This is longest book I have ever read."]', 'This is the most longest book I have ever read.', 0, 'Il superlativo di un aggettivo corto (long) è ''the longest''. ''Most long'' non si usa con un aggettivo corto, ''longer'' è un comparativo e senza ''the'' il superlativo è scorretto.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q118', 'Complete: ''My car is _____ than yours.''', '["faster","more fast","fastest","the fastest"]', 'fast', 0, 'Dopo ''than'' si usa un comparativo, e il comparativo di ''fast'' è ''faster''. ''More fast'' non si usa con un aggettivo corto, mentre ''fastest'' e ''the fastest'' sono superlativi e non vanno con ''than''.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q119', 'Translate ''Oggi è molto più caldo di ieri.''', '["Today is much hotter than yesterday.","Today is much more hot than yesterday.","Today is very hotter than yesterday.","Today is hotter that yesterday."]', 'Today is much more hotter than yesterday.', 0, 'Il comparativo di ''hot'' è ''hotter'' (si raddoppia la t) e si usa con ''than''. ''Much'' rafforza il comparativo; ''much more hot'' non è corretto con un aggettivo corto, ''very hotter'' è sbagliato perché ''very'' non va con i comparativi, e ''that'' al posto di ''than'' è un errore.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q120', 'Complete: ''She is the _____ student in the class.''', '["best","better","most good","goodest"]', 'most best', 0, '''Good'' ha il comparativo e il superlativo irregolari: ''better'' e ''the best''. ''Better'' è un comparativo, mentre ''most good'' e ''goodest'' non esistono.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q121', 'Translate ''Sua sorella è meno socievole di lui.''', '["His sister is less outgoing than him.","His sister is least outgoing than him.","His sister is not outgoing than him.","His sister is minor outgoing than him."]', 'His sister is lesser outgoing than him.', 0, 'Per il comparativo di minoranza si usa ''less'' + aggettivo + ''than'': ''less outgoing than him''. ''Least'' è il superlativo, ''not outgoing than'' non è una struttura comparativa e ''minor'' non si usa così in inglese.', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q122', 'Complete: ''This exercise is _____ difficult than the previous one.''', '["more","much","most","very"]', NULL, 0, 'Con un aggettivo lungo (difficult) il comparativo si forma con ''more'' + aggettivo + ''than''. ''Most'' è il superlativo, mentre ''much'' e ''very'' non formano un comparativo.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q123', 'Translate ''Questo è il posto meno costoso in città.''', '["This is the least expensive place in town.","This is the less expensive place in town.","This is the not expensive place in town.","This is the most cheap place in town."]', 'This is the most less expensive place in town.', 0, 'Il superlativo di minoranza si forma con ''the least'' + aggettivo: ''the least expensive''. ''The less'' è un comparativo, ''the not expensive'' non è una forma grammaticale e ''most cheap'' non è un superlativo corretto (si direbbe ''cheapest'').', 'comparatives-superlatives', 'Traduzione', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q124', 'Complete: ''He is _____ taller than his brother.''', '["slightly","a little of","few","small"]', 'a lot of', 0, 'Per attenuare un comparativo si usano avverbi come ''slightly'' (leggermente), ''much'' o ''a lot'': ''slightly taller''. ''A little of'' non è corretto, ''few'' è per i nomi numerabili e ''small'' è un aggettivo, non un avverbio.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q125', 'Complete: ''If I have time, I _____ you.''', '["will help","helping","would help","helped"]', 'will to help', 0, 'Nel First Conditional (situazione reale) si usa if + presente semplice e ''will'' + verbo base nella principale: ''I will help you''. ''Would help'' e ''helped'' sono per ipotesi irreali, mentre ''helping'' non è una forma coniugata e da solo non può essere il verbo della frase.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q126', 'Translate ''Se lei studierà, passerà il test.''', '["If she studies, she will pass the test.","If she will study, she will pass the test.","If she study, she will pass the test.","If she studied, she will pass the test."]', 'If she studies, she will to pass the test.', 0, 'Nel First Conditional dopo ''if'' si usa il presente semplice (if she studies) e nella principale ''will'': ''she will pass''. ''If she will study'' è un errore tipico, ''she study'' manca della -s e ''studied'' è un passato.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q127', 'Complete: ''We won''t go to the park if it _____.''', '["rains","will rain","rain","raining"]', 'to rain', 0, 'Dopo ''if'' si usa il presente semplice anche per il futuro: ''if it rains'' (terza persona, -s). ''Will rain'' dopo ''if'' è sbagliato, ''rain'' manca della -s e ''raining'' non è una forma verbale completa.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q128', 'Translate ''Cosa dirai se lui ti chiamerà?''', '["What will you say if he calls you?","What do you say if he will call you?","What will you say if he will call you?","What would you say if he calls you?"]', 'What you will say if he calls you?', 0, 'La domanda del First Conditional si forma con ''will'' nella principale e il presente semplice dopo ''if'': ''What will you say if he calls you?''. ''Will call'' dopo ''if'' è sbagliato, e ''would'' con ''calls'' mescola due tipi di condizionale.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q129', 'Complete: ''If they don''t hurry, they _____ the bus.''', '["will miss","will missing","would miss","missed"]', 'would have missed', 0, 'Nella principale del First Conditional si usa ''will'' + verbo base: ''they will miss the bus''. ''Will missing'' è sbagliato perché dopo ''will'' serve il verbo base, mentre ''would miss'' e ''missed'' sono forme dell''ipotesi irreale.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q130', 'Translate ''Se non mi aiuti, non finirò il progetto.''', '["If you don''t help me, I won''t finish the project.","If you won''t help me, I don''t finish the project.","If you not help me, I won''t finish the project.","If you didn''t help me, I won''t finish the project."]', 'If you don''t help me, I didn''t finish the project.', 0, 'Nel First Conditional: ''if'' + presente (don''t help) e ''won''t'' + verbo base nella principale (I won''t finish). ''Won''t'' dopo ''if'' è sbagliato, ''you not help'' manca di ''don''t'', e ''didn''t'' appartiene a un passato o a un''ipotesi irreale.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q131', 'Complete: ''If she _____ the job, she will move to London.''', '["gets","get","will get","got"]', 'getting', 0, 'Con ''she'' il presente semplice prende la -s: ''if she gets''. ''Get'' manca della -s, ''will get'' dopo ''if'' è un errore tipico, e ''got'' è un passato.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q132', 'Translate ''Gli parlerò se lo vedo.''', '["I will talk to him if I see him.","I talk to him if I will see him.","I will talk to him if I will see him.","I would talk to him if I see him."]', NULL, 0, 'Nel First Conditional la principale usa ''will'' (I will talk) e la frase con ''if'' il presente (if I see him). ''If I will see'' è sbagliato, e ''would talk'' appartiene all''ipotesi irreale.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q133', 'Complete: ''Unless you _____, you won''t succeed.''', '["try","will try","don''t try","tried"]', 'trying', 0, '''Unless'' significa ''if ... not'', quindi ha già un significato negativo e il verbo resta affermativo: ''Unless you try''. ''Don''t try'' darebbe un doppio negativo, ''will try'' non si usa dopo ''unless'' e ''tried'' è un passato.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q134', 'Translate ''A meno che non piova, andremo a fare una passeggiata.''', '["Unless it rains, we will go for a walk.","Unless it doesn''t rain, we will go for a walk.","If it unless rains, we will go for a walk.","Unless it will rain, we will go for a walk."]', 'Unless it is not raining, we will go for a walk.', 0, '''Unless'' significa ''se non'' e ha già il senso negativo, quindi il verbo che segue è affermativo al presente: ''Unless it rains''. ''Unless it doesn''t rain'' è un doppio negativo, ''If it unless rains'' è mal costruita e ''unless it will rain'' ha ''will'' dopo la congiunzione.', 'first-conditional', 'Traduzione', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q135', 'Complete: ''I will buy that car if it _____ too expensive.''', '["isn''t","not is","doesn''t be","aren''t"]', 'not be', 0, 'Dopo ''if'' il verbo è al presente e, con ''it'', la negazione di ''to be'' è ''isn''t'': ''if it isn''t too expensive''. ''Not is'' ha l''ordine sbagliato, ''doesn''t be'' non esiste (con ''to be'' non si usa ''do'') e ''aren''t'' non concorda con ''it''.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q136', 'Complete: ''I usually go to bed _____ 11 PM.''', '["at","in","on","to"]', 'during', 0, 'Con gli orari precisi (11 PM) si usa ''at''. ''In'' si usa con mesi, anni e parti del giorno (in the morning), ''on'' con i giorni e le date, e ''to'' non è una preposizione di tempo qui.', 'prepositions-time', 'Grammatica', 'A1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q137', 'Translate ''Non mi piace il caffè.''', '["I don''t like coffee.","I''m not like coffee.","I doesn''t like coffee.","I not like coffee."]', 'I no like coffee.', 0, 'La negazione del presente semplice con ''I'' si forma con ''don''t'' + verbo base: ''I don''t like coffee''. ''I''m not like'' mescola ''to be'' con un verbo, ''I doesn''t'' usa l''ausiliare della terza persona e ''I not like'' manca di ''do''.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q138', 'Complete: ''They _____ to Paris next weekend.''', '["are going","goes","went","have gone"]', 'will going', 0, 'Per un programma già organizzato nel futuro (''next weekend'') si usa il Present Continuous: ''They are going''. ''Goes'' non concorda con ''they'', mentre ''went'' e ''have gone'' sono tempi del passato.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q139', 'Translate ''Posso aiutarti?''', '["Can I help you?","Do I can help you?","Am I help you?","May I helping you?"]', 'Can I to help you?', 0, 'I verbi modali come ''can'' formano la domanda per inversione, senza ''do'': ''Can I help you?'', e il verbo che segue è alla forma base. ''Do I can'' è sbagliato, ''Am I help'' mescola ''to be'' con un verbo e ''May I helping'' vuole la forma base e non -ing.', 'modals-ability-permission', 'Traduzione', 'A1', 'Modals of Ability and Permission', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q140', 'Complete: ''She is interested in _____ Spanish.''', '["learning","to learn","learn","learned"]', 'to learning', 0, 'Dopo una preposizione (''in'') il verbo prende la forma in -ing: ''interested in learning''. L''infinito (''to learn'' o ''learn'') e il passato (''learned'') non si usano dopo una preposizione.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q141', 'Translate ''Dobbiamo andare ora.''', '["We must go now.","We have go now.","We are must go now.","We need going now."]', 'We must to go now.', 0, '''Must'' esprime obbligo ed è seguito dal verbo base senza ''to'': ''We must go''. ''Have go'' ha ''have'' senza ''to'' (servirebbe ''have to go''), ''are must'' non esiste e ''need going'' non è la struttura corretta.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q142', 'Complete: ''I look forward _____ from you soon.''', '["to hearing","to hear","hearing","hear"]', 'for hearing', 0, 'In ''look forward to'' la parola ''to'' è una preposizione, quindi il verbo che segue è in -ing: ''to hearing''. L''infinito ''to hear'' è l''errore tipico, e ''hearing'' e ''hear'' senza ''to'' non completano l''espressione.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q143', 'Translate ''Ero molto stanco ieri sera.''', '["I was very tired last night.","I am very tired last night.","I had very tired last night.","I were very tired last night."]', 'I have been very tired last night.', 0, '"Ero" è un passato di ''to be'': con ''I'' si dice ''was''. ''Am'' è un presente (e non va con ''last night''), ''had'' non si usa con un aggettivo come ''tired'', e ''were'' è per you/we/they.', 'past-simple', 'Traduzione', 'A1', 'Past Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q144', 'Complete: ''This is the book _____ I borrowed from the library.''', '["which","who","where","what"]', 'whose', 0, 'Per riferirsi a una cosa (the book) si usa il pronome relativo ''which'' (o ''that''). ''Who'' è per le persone, ''where'' per i luoghi e ''what'' non si usa come pronome relativo dopo un nome.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q145', 'Translate ''Lei sa nuotare molto bene.''', '["She can swim very well.","She can swims very well.","She knows swim very well.","She knows to swim very well."]', 'She can to swim very well.', 0, 'Per l''abilità si usa ''can'' + verbo base: ''She can swim''. ''Can'' non prende mai la -s, e "sapere" nel senso di essere capace non si traduce con ''know'' (''knows swim'' e ''knows to swim'' sono errori tipici).', 'modals-ability-permission', 'Traduzione', 'A1', 'Modals of Ability and Permission', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q146', 'Complete: ''You _____ smoke in the hospital.''', '["mustn''t","don''t have to","needn''t","aren''t"]', 'don''t must', 0, '''Mustn''t'' esprime un divieto: "non si deve" fumare. ''Don''t have to'' e ''needn''t'' dicono che non c''è bisogno, non che è vietato; ''aren''t'' non è una forma corretta con ''smoke''.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q147', 'Translate ''Non ho abbastanza soldi.''', '["I don''t have enough money.","I not have enough money.","I don''t have enough to money.","I don''t have enough of money."]', NULL, 0, 'Nella frase negativa si dice ''I don''t have enough money'', con ''enough'' direttamente davanti al nome. ''I not have'' è sbagliato (la negazione vuole ''don''t''), ''enough to money'' e ''enough of money'' sono errori: davanti a un nome senza articolo non si mette né ''to'' né ''of''.', 'quantifiers', 'Traduzione', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q148', 'Complete: ''That is _____ jacket.'' (The jacket belongs to Tom)', '["Tom''s","Toms''","Tom","Toms"]', 'of Tom', 0, 'Per il possesso di una persona al singolare si aggiunge ''s al nome: ''Tom''s jacket''. ''Toms'''' e ''Toms'' sono scritti male, e ''Tom'' da solo non esprime il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q149', 'Translate ''La casa dei miei nonni è grande.''', '["My grandparents'' house is big.","My grandparent''s house is big.","The house my grandparents is big.","My grandparents house is big."]', NULL, 0, '''Grandparents'' è un plurale regolare in -s, quindi il possesso si forma con il solo apostrofo finale: ''my grandparents'' house''. ''Grandparent''s'' indicherebbe un solo nonno, ''grandparents house'' manca dell''apostrofo e ''the house my grandparents'' non ha né ''of'' né il possessivo.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q150', 'Complete: ''I love _____ new song.'' (The song of the band)', '["the band''s","the bands''","the band","the bands"]', NULL, 0, '''Band'' è singolare, quindi il possesso si forma con ''s: ''the band''s new song''. ''The bands'''' indicherebbe più gruppi, mentre ''the band'' e ''the bands'' senza apostrofo non esprimono il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q151', 'Translate ''I giocattoli dei bambini sono sparsi ovunque.''', '["The children''s toys are scattered everywhere.","The childrens'' toys are scattered everywhere.","The children toys are scattered everywhere.","The childrens toys are scattered everywhere."]', NULL, 0, '''Children'' è un plurale irregolare che non finisce in -s, quindi il possessivo si forma con ''s: ''the children''s toys''. ''Childrens'''' è sbagliato perché l''apostrofo dopo la -s si usa solo con i plurali regolari, ''childrens toys'' è sbagliato in più perché manca l''apostrofo, e ''the children toys'' manca del possessivo.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q152', 'Complete: ''This is _____ desk.'' (The desk belongs to the boss)', '["the boss''s","the bosses''","the boss","the bosses"]', NULL, 0, 'Il possessivo di un nome singolare si forma con ''s, anche se il nome finisce in -s: ''the boss''s desk''. ''The bosses'''' è il possessivo di più capi, ''the boss'' da solo non indica possesso e ''the bosses'' è un plurale.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q153', 'Translate ''La macchina di James è blu.''', '["James''s car is blue.","James car is blue.","The James''s car is blue.","Jame''s car is blue."]', NULL, 0, 'Per dire ''di qualcuno'' con una persona si usa il possessivo: nome + ''s. I nomi che finiscono in -s, come James, prendono comunque ''s (''James''s car''). ''James car'' non ha il possessivo, ''the James''s'' non vuole l''articolo e ''Jame''s'' cambia il nome.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q154', 'Complete: ''I went to the _____.'' (The shop of the baker)', '["baker''s","bakers''","baker","bakers"]', NULL, 0, 'Per indicare un negozio o un''attività si usa il possessivo da solo, senza ripetere il nome: ''the baker''s'' (il negozio del panettiere, uno solo). ''Bakers'''' sarebbe il possessivo plurale e ''baker'' o ''bakers'' non hanno l''apostrofo.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q155', 'Translate ''È il compleanno di mia madre.''', '["It''s my mother''s birthday.","It''s the birthday my mother.","It''s my mothers birthday.","It''s my mother birthday."]', NULL, 0, 'Per i possessori che sono persone si usa ''s davanti al nome posseduto: ''my mother''s birthday''. Senza apostrofo (''mothers'') si scrive un plurale, ''my mother birthday'' non esprime il possesso e ''the birthday my mother'' non ha né ''of'' né il possessivo.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q156', 'Complete: ''We are meeting at _____.'' (The house of Paul)', '["Paul''s","Pauls''","Paul","Pauls"]', 'of Paul', 0, 'Con i nomi di persona si usa il possessivo da solo per dire ''a casa di'': ''at Paul''s''. ''Pauls'''' e ''Pauls'' sono plurali sbagliati, e ''at Paul'' significherebbe ''da Paul'' senza la casa.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q157', 'Translate ''Le scarpe da donna sono al secondo piano.''', '["Women''s shoes are on the second floor.","Womens'' shoes are on the second floor.","Woman''s shoes are on the second floor.","Women shoes are on the second floor."]', NULL, 0, '''Women'' è un plurale irregolare (non finisce in -s), quindi il possessivo è ''s: ''women''s shoes''. ''Womens'''' è scritto male, ''woman''s'' è singolare (''di una donna'') e ''women shoes'' non ha il possessivo.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q158', 'Complete: ''The _____ room is down the hall.'' (The room for teachers)', '["teachers''","teacher''s","teachers''s","teacher"]', NULL, 0, '''Teachers'' è un plurale regolare in -s, quindi il possessivo si fa solo con l''apostrofo dopo la s: ''the teachers'' room'' (la stanza per gli insegnanti). ''Teacher''s'' sarebbe la stanza di un solo insegnante, ''teachers''s'' è una forma sbagliata e ''teacher'' da solo non indica il possesso.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q159', 'Translate ''Hai visto le chiavi di Anna?''', '["Have you seen Anna''s keys?","Have you seen the Anna''s keys?","Have you seen Annas keys?","Have you seen Anna keys?"]', NULL, 0, 'Con un nome di persona singolare il possessivo è nome + ''s: ''Anna''s keys''. ''Annas keys'' dimentica l''apostrofo, ''Anna keys'' non esprime il possesso e ''the Anna''s keys'' non vuole l''articolo.', 'possessive-s', 'Traduzione', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q160', 'Complete: ''I have known him _____ 2010.''', '["since","for","from","in"]', 'during', 0, '''Since'' si usa con un punto di inizio nel tempo (qui il 2010) insieme al present perfect: ''I have known him since 2010''. ''For'' si usa con una durata (for ten years), mentre ''from'' e ''in'' non esprimono ''da quando''.', 'prepositions-time', 'Grammatica', 'B1', 'Prepositions of Time', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q161', 'Translate ''Lavorano qui da molti anni.''', '["They have worked here for many years.","They work here since many years.","They have worked here since many years.","They work here for many years."]', 'They have worked here from many years.', 0, '''Da molti anni'' con un''azione ancora in corso si traduce con il present perfect e ''for'' (una durata): ''have worked here for many years''. ''Since'' vuole una data o un momento preciso, e il present simple non va con ''da'' in questo senso.', 'prepositions-time', 'Traduzione', 'B1', 'Prepositions of Time', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q162', 'Complete: ''They _____ tennis right now.''', '["are playing","play","playing","is playing"]', 'are play', 0, '''Right now'' indica un''azione che accade in questo momento, quindi serve il present continuous: am/is/are + verbo in -ing. Il soggetto ''they'' vuole ''are''; ''is playing'' è per la terza persona singolare e ''playing'' da solo manca dell''ausiliare.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q163', 'Translate ''Perché stai piangendo?''', '["Why are you crying?","Why do you cry?","Why you are crying?","Why you cry?"]', 'Why are you cry?', 0, 'Nella domanda al present continuous l''ordine è parola interrogativa + are/is + soggetto + verbo in -ing: ''Why are you crying?''. ''Why you are crying?'' non inverte soggetto e ausiliare, e ''do you cry'' parla di un''abitudine.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q164', 'Complete: ''I _____ to the doctor tomorrow afternoon.''', '["am going","goes","went","going"]', NULL, 0, 'Il present continuous si usa anche per un programma già deciso nel futuro vicino, con ''tomorrow afternoon'': ''I am going to the doctor''. ''Goes'' non concorda con ''I'', ''went'' è passato e ''going'' senza ''am'' non è completo.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q165', 'Translate ''Il sole sta splendendo.''', '["The sun is shining.","The sun shines.","The sun shining.","The sun are shining."]', NULL, 0, 'Il sole che splende in questo momento è un''azione in corso: present continuous ''is shining''. ''Shines'' indica un fatto abituale, ''shining'' senza ausiliare è incompleto e ''are'' non concorda con ''the sun''.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q166', 'Complete: ''Look! The bus _____.''', '["is coming","comes","coming","come"]', 'are coming', 0, '''Look!'' introduce qualcosa che sta succedendo ora sotto i nostri occhi, quindi present continuous: ''The bus is coming''. ''Comes'' e ''come'' sono present simple (abitudini) e ''coming'' da solo non ha l''ausiliare.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q167', 'Translate ''Non stiamo usando il computer adesso.''', '["We aren''t using the computer right now.","We don''t use the computer right now.","We not using the computer right now.","We isn''t using the computer right now."]', 'We don''t using the computer right now.', 0, 'La forma negativa del present continuous è soggetto + be + not + verbo in -ing: ''We aren''t using''. ''We don''t use'' è present simple e non va con ''right now'', mentre ''We not using'' manca di ''are'' e ''isn''t'' non concorda con ''we''.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q168', 'Complete: ''_____ he watching TV?''', '["Is","Does","Are","Do"]', 'Has', 0, 'Per fare una domanda al present continuous si mette l''ausiliare ''be'' prima del soggetto, ed è ''is'' con ''he'': ''Is he watching TV?''. ''Does'' e ''Do'' sono per il present simple e ''Are'' è per ''you/we/they''.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q169', 'Translate ''Sto cercando le mie chiavi.''', '["I am looking for my keys.","I am look for my keys.","I am looking my keys.","I looking for my keys."]', 'I am looking for to my keys.', 0, '''Cercare'' si traduce ''look for'', e un''azione che sta avvenendo ora vuole il present continuous: ''I am looking for my keys''. ''Am look'' non è corretto (dopo ''am'' serve -ing), ''looking my keys'' manca della preposizione ''for'' e ''I looking'' manca di ''am''.', 'present-continuous', 'Traduzione', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q170', 'Complete: ''The kids _____ sleeping in their room.''', '["are","is","do","does"]', NULL, 0, '''Kids'' è plurale, quindi l''ausiliare del present continuous è ''are'': ''The kids are sleeping''. ''Is'' è per il singolare, mentre ''do'' e ''does'' non si usano come ausiliari prima di un verbo in -ing.', 'present-continuous', 'Grammatica', 'A2', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q171', 'Complete: ''I have _____ finished my dinner.''', '["already","yet","ever","since"]', 'ago', 0, '''Already'' (già) si mette tra ''have'' e il participio in una frase affermativa: ''I have already finished''. ''Yet'' si usa nelle domande e nelle negative, ''ever'' nelle domande sull''esperienza e ''since'' vuole un punto di inizio nel tempo.', 'present-perfect', 'Grammatica', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q172', 'Translate ''È la prima volta che guido una macchina.''', '["It''s the first time I have driven a car.","It''s the first time I driving a car.","It''s the first time I have drove a car.","It''s the first time I has driven a car."]', 'It''s the first time I am drive a car.', 0, 'Dopo ''It''s the first time'' si usa il present perfect: ''It''s the first time I have driven a car''. ''I driving'' non ha l''ausiliare, ''have drove'' usa il passato semplice al posto del participio (''driven'') e ''I has'' non concorda con ''I''.', 'present-perfect', 'Traduzione', 'B1', 'Present Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q173', 'Complete: ''She _____ coffee every morning.''', '["drinks","drink","is drinking","drank"]', 'drinking', 0, '''Every morning'' indica un''abitudine, quindi present simple, e alla terza persona singolare (she) si aggiunge -s: ''drinks''. ''Drink'' non ha la -s, ''is drinking'' descrive un''azione in corso e ''drank'' è passato.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q174', 'Translate ''Io lavoro in un ospedale.''', '["I work in a hospital.","I working in a hospital.","I works in a hospital.","I work to a hospital."]', NULL, 0, 'Per un lavoro stabile si usa il present simple: ''I work in a hospital''. ''I works'' sbaglia la forma (la -s è solo per he/she/it), ''I working'' non ha l''ausiliare e ''work to'' non è la preposizione giusta, che è ''in''.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q175', 'Complete: ''They _____ play tennis on Sundays.''', '["don''t","doesn''t","aren''t","isn''t"]', NULL, 0, 'Con il soggetto plurale ''they'' la negazione del present simple è ''don''t'' + verbo base: ''They don''t play''. ''Doesn''t'' è per he/she/it, mentre ''aren''t'' e ''isn''t'' sono forme di ''be'' e non si usano prima di ''play''.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q176', 'Translate ''Lui non capisce la domanda.''', '["He doesn''t understand the question.","He don''t understand the question.","He isn''t understand the question.","He not understands the question."]', 'He doesn''t understands the question.', 0, 'Con la terza persona singolare (he) la negazione del present simple è ''doesn''t'' + verbo base: ''He doesn''t understand''. ''Don''t'' non concorda con ''he'', ''isn''t understand'' mescola ''be'' e verbo, e ''not understands'' manca dell''ausiliare.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q177', 'Complete: ''_____ you speak English?''', '["Do","Are","Does","Is"]', NULL, 0, 'Le domande al present simple si fanno con ''do/does'' + soggetto + verbo base, e con ''you'' si usa ''do'': ''Do you speak English?''. ''Are'' e ''Is'' vogliono un aggettivo o un participio, e ''does'' è per he/she/it.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q178', 'Translate ''Cosa significa questa parola?''', '["What does this word mean?","What means this word?","What do this word mean?","What is meaning this word?"]', 'What does mean this word?', 0, 'In una domanda al present simple ''this word'' è terza persona singolare, quindi ''does'' + verbo base: ''What does this word mean?''. ''What means this word?'' non ha l''ausiliare, ''do ... mean'' non concorda e ''is meaning'' non si usa con un verbo di stato come ''mean''.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q179', 'Complete: ''The sun _____ in the east.''', '["rises","rise","is rising","rose"]', NULL, 0, 'Un fatto sempre vero si esprime con il present simple e, con ''the sun'' (terza persona singolare), il verbo prende la -s: ''rises''. ''Rise'' manca della -s, ''is rising'' descrive un''azione in corso e ''rose'' è passato.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q180', 'Translate ''Quante volte vai in palestra?''', '["How often do you go to the gym?","How often you go to the gym?","How much time do you go to the gym?","How many times you go to the gym?"]', 'How often do you to go to the gym?', 0, '''How often'' chiede la frequenza e nella domanda al present simple serve ''do'' + soggetto: ''How often do you go to the gym?''. Senza ''do'' la frase è sbagliata, e ''how much time'' e ''how many times'' non sono le forme corrette qui.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q181', 'Complete: ''My brother never _____ his room.''', '["cleans","clean","is cleaning","cleaned"]', 'cleaning', 0, 'Con gli avverbi di frequenza come ''never'' si usa il present simple, e con ''my brother'' (he) il verbo prende la -s: ''cleans''. ''Clean'' non ha la -s, ''is cleaning'' non va con ''never'' e ''cleaned'' è passato.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q182', 'Translate ''Lei ha due gatti e un cane.''', '["She has two cats and a dog.","She have two cats and a dog.","She is having two cats and a dog.","She got two cats and a dog."]', NULL, 0, 'Alla terza persona singolare il verbo ''have'' diventa ''has'': ''She has two cats''. ''She have'' è sbagliato, ''is having'' non si usa per il possesso e ''got'' da solo è passato, non presente.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q183', 'Complete: ''We _____ like spicy food.''', '["don''t","doesn''t","not","aren''t"]', NULL, 0, 'Con ''we'' la negazione del present simple è ''don''t'' + verbo base: ''We don''t like''. ''Doesn''t'' è per he/she/it, ''not'' da solo non basta senza ausiliare e ''aren''t'' non si usa prima di ''like''.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q184', 'Translate ''Il film inizia alle 20:30.''', '["The movie starts at 8:30 PM.","The movie starting at 8:30 PM.","The movie start at 8:30 PM.","The movie will starting at 8:30 PM."]', NULL, 0, 'Gli orari di film, treni e simili si esprimono con il present simple: ''The movie starts at 8:30 PM''. ''Start'' manca della -s, ''starting'' senza ''is'' non è un verbo completo e ''will starting'' è una forma impossibile.', 'present-simple', 'Traduzione', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q185', 'Complete: ''Does he _____ in London?''', '["live","lives","living","lived"]', NULL, 0, 'Dopo ''does'' il verbo resta alla forma base, perché la -s della terza persona è già sull''ausiliare: ''Does he live''. ''Lives'' ripeterebbe la -s, mentre ''living'' e ''lived'' non sono forme base.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q186', 'Complete: ''I have _____ money in my pocket.''', '["some","any","many","few"]', NULL, 0, '''Money'' è un nome non numerabile e in una frase affermativa si usa ''some'': ''I have some money''. ''Any'' si usa di solito nelle domande e nelle negative, mentre ''many'' e ''few'' vogliono nomi numerabili.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q187', 'Translate ''Non ci sono mele.''', '["There aren''t any apples.","There aren''t some apples.","There aren''t no apples.","There are any apples."]', 'There don''t have any apples.', 0, 'Nelle frasi negative si usa ''any'' con i nomi numerabili plurali: ''There aren''t any apples''. ''Some'' non va nella negativa, e ''aren''t no'' è una doppia negazione, mentre ''are any'' non ha la negazione.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q188', 'Complete: ''Do you have _____ questions?''', '["any","a","much","little"]', NULL, 0, 'Nelle domande si usa normalmente ''any'' con ''questions'': ''Do you have any questions?''. ''A'' non va con un plurale (''questions''), e ''much'' e ''little'' non vanno con un nome numerabile plurale.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q189', 'Translate ''Vorresti del tè?''', '["Would you like some tea?","Would you like to some tea?","Do you would like some tea?","Would you like many tea?"]', NULL, 0, 'Nelle offerte e nelle richieste cortesi si usa ''some'' anche nella domanda: ''Would you like some tea?''. ''Would you like to some'' ha un ''to'' di troppo, ''Do you would like'' mette insieme due ausiliari e ''many'' non va con ''tea'', che è non numerabile.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q190', 'Complete: ''There are only a _____ students in the class.''', '["few","little","much","many"]', NULL, 0, '''Students'' è numerabile plurale, quindi si usa ''a few'' (alcuni): ''a few students''. ''Little'' e ''much'' vogliono nomi non numerabili, mentre ''a many'' non esiste.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q191', 'Translate ''Ho pochissimo tempo.''', '["I have very little time.","I have very few time.","I have much little time.","I have very small time."]', NULL, 0, '''Time'' è non numerabile, quindi ''pochissimo'' si dice ''very little'': ''I have very little time''. ''Few'' si usa con i numerabili plurali, ''much little'' non esiste e ''very small time'' non è un''espressione corretta.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q192', 'Complete: ''She reads a _____ of books.''', '["lot","many","much","some"]', NULL, 0, 'L''espressione è ''a lot of'' davanti a un nome: ''a lot of books''. ''Many of'' e ''much of'' hanno un altro uso e non si usano con ''a'', mentre ''a some of'' non esiste.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q193', 'Translate ''Abbiamo mangiato troppa pizza.''', '["We ate too much pizza.","We ate too many pizza.","We ate very much pizza.","We ate a lot pizza."]', 'We ate too much of pizza.', 0, 'In questa frase ''pizza'' è usata in senso generale come non numerabile, quindi ''too much'': ''too much pizza''. ''Too many'' si usa con i nomi numerabili plurali, ''very much'' non va davanti a un nome e ''a lot pizza'' manca di ''of''.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q194', 'Complete: ''How _____ apples do you want?''', '["many","much","some","any"]', NULL, 0, '''Apples'' è numerabile plurale, quindi si chiede la quantità con ''How many'': ''How many apples''. ''Much'' si usa con i non numerabili, mentre ''some'' e ''any'' non si usano dopo ''how''.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q195', 'Translate ''Non abbiamo comprato niente.''', '["We didn''t buy anything.","We bought anything.","We didn''t buy nothing.","We didn''t buy some."]', NULL, 0, 'Nella negativa con ''didn''t'' si usa ''anything'': ''We didn''t buy anything''. ''Nothing'' dopo ''didn''t'' sarebbe una doppia negazione, ''bought anything'' non ha la negazione e ''some'' da solo manca del nome.', 'quantifiers', 'Traduzione', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q196', 'Complete: ''Is there _____ good on TV?''', '["anything","anythings","everything","somethings"]', NULL, 0, 'Nelle domande si usa di solito ''any-'': ''Is there anything good on TV?''. ''Anything'' e ''something'' non hanno il plurale (''anythings'', ''somethings'' sono sbagliati) e ''everything'' cambia il senso e non funziona con ''Is there...?'' in questa frase.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q197', 'Complete: ''_____ is that man?''', '["Who","What","Which","Where"]', NULL, 0, 'Per chiedere l''identità di una persona si usa ''Who'': ''Who is that man?''. ''What'' si usa per le cose, ''Which'' per scegliere in un gruppo e ''Where'' chiede un luogo.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q198', 'Translate ''Perché sei in ritardo?''', '["Why are you late?","Because are you late?","Why you are late?","Why do you late?"]', NULL, 0, '''Perché'' in una domanda è ''Why'', seguito da verbo + soggetto: ''Why are you late?''. ''Because'' è la risposta e non si usa per chiedere, mentre ''Why you are'' non inverte l''ordine e ''Why do you late'' non è corretto con ''be''.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q199', 'Complete: ''_____ old are you?''', '["How","What","Who","Which"]', NULL, 0, 'L''età si chiede con ''How old'': ''How old are you?''. ''What old'', ''Who old'' e ''Which old'' non esistono in questa domanda.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q200', 'Translate ''Quando è il tuo compleanno?''', '["When is your birthday?","Where is your birthday?","What is your birthday?","How is your birthday?"]', NULL, 0, 'Per chiedere una data o un momento si usa ''When'': ''When is your birthday?''. ''Where'' chiede un luogo, ''What'' chiederebbe qual è il compleanno come oggetto e ''How'' chiede il modo o lo stato.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q201', 'Complete: ''_____ do you live?''', '["Where","What","How","When"]', 'Who', 0, 'Per chiedere un luogo si usa ''Where'': ''Where do you live?''. ''What'' e ''How'' non chiedono dove, e ''When'' chiede il tempo.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q202', 'Translate ''Come vai al lavoro?''', '["How do you go to work?","What do you go to work?","Where do you go to work?","Why do you go to work?"]', 'Who do you go to work?', 0, '''Come'' riferito al modo o al mezzo si dice ''How'': ''How do you go to work?''. ''What'' e ''Where'' chiederebbero cosa e dove, e ''Why'' chiederebbe il motivo.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q203', 'Complete: ''_____ is your favorite color?''', '["What","Whose","Who","How"]', 'When', 0, 'Per chiedere qual è una preferenza si usa ''What'': ''What is your favorite color?''. ''Whose'' chiede di chi è una cosa, ''Who'' chiede una persona e ''How'' chiede il modo.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q204', 'Translate ''Di chi è questa borsa?''', '["Whose bag is this?","Who bag is this?","Which bag is this?","What bag is this?"]', 'Whom bag is this?', 0, '''Di chi è'' si dice ''Whose'' + nome: ''Whose bag is this?''. ''Who bag'' è sbagliato perché ''who'' non si usa con un nome, mentre ''Which'' e ''What'' chiedono quale o cosa, non il proprietario.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q205', 'Complete: ''_____ time does the movie start?''', '["What","Where","Who","How"]', NULL, 0, 'L''ora si chiede con ''What time'': ''What time does the movie start?''. ''Where'' si usa per i luoghi, ''Who'' per le persone e ''How time'' non esiste.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q206', 'Translate ''Quanto costa questo libro?''', '["How much does this book cost?","How many does this book cost?","How price is this book?","What cost this book?"]', 'How much costs this book?', 0, 'Il prezzo si chiede con ''How much'' e l''ausiliare ''does'': ''How much does this book cost?''. ''How many'' si usa con i numerabili, ''How price'' non esiste e ''What cost this book'' non ha l''ausiliare.', 'questions-origins', 'Traduzione', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q207', 'Complete: ''_____ languages do you speak?''', '["How many","How much","How often","How long"]', 'How far', 0, '''Languages'' è numerabile plurale e si chiede il numero con ''How many'': ''How many languages do you speak?''. ''How much'' è per i non numerabili, ''How often'' chiede la frequenza e ''How long'' la durata.', 'questions-origins', 'Grammatica', 'A1', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q208', 'Complete: ''_____ a big tree in the garden.''', '["There is","There are","It is","They are"]', 'There has', 0, '''Tree'' è singolare, quindi per dire ''c''è'' si usa ''There is'': ''There is a big tree''. ''There are'' è per il plurale, mentre ''It is'' e ''They are'' non esprimono l''esistenza di qualcosa.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q209', 'Translate ''Ci sono tre sedie nella stanza.''', '["There are three chairs in the room.","They are three chairs in the room.","There is three chairs in the room.","Have three chairs in the room."]', 'There have three chairs in the room.', 0, '''Chairs'' è plurale, quindi ''ci sono'' si traduce ''There are'': ''There are three chairs''. ''They are'' vuol dire ''sono'' e non ''ci sono'', ''There is'' è singolare e ''Have'' non si usa così.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q210', 'Complete: ''_____ any messages for me?''', '["Are there","Is there","Do there","Have there"]', 'Has there', 0, 'In una domanda sull''esistenza di cose al plurale si usa ''Are there'': ''Are there any messages for me?''. ''Is there'' è singolare, mentre ''Do there'' e ''Have there'' non esistono.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q211', 'Translate ''C''è un buon ristorante qui vicino?''', '["Is there a good restaurant near here?","Are there a good restaurant near here?","There is a good restaurant near here?","Does there a good restaurant near here?"]', 'Has there a good restaurant near here?', 0, 'Con un nome singolare (''a good restaurant'') la domanda è ''Is there...?'': ''Is there a good restaurant near here?''. ''Are there'' è plurale, ''There is'' senza inversione non fa la domanda e ''Does there'' non esiste.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q212', 'Complete: ''There _____ a lot of people at the party.''', '["were","was","are been","is"]', NULL, 0, '''Past'' e ''people'' (plurale) vogliono ''There were'': ''There were a lot of people''. ''Was'' è per il singolare, ''are been'' non esiste e ''is'' è presente singolare.', 'there-is-are', 'Grammatica', 'A2', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q213', 'Translate ''Non c''era nessuno in casa.''', '["There was nobody at home.","There wasn''t nobody at home.","There were nobody at home.","It was nobody at home."]', 'There is nobody at home.', 0, 'Al passato ''There was'' si usa con ''nobody'', che è singolare: ''There was nobody at home''. ''Wasn''t nobody'' è una doppia negazione, ''were'' è plurale e ''It was'' non esprime ''non c''era''.', 'there-is-are', 'Traduzione', 'A2', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q214', 'Complete: ''_____ going to be a storm tomorrow.''', '["There is","There are","They are","There have"]', NULL, 0, 'Per dire che qualcosa ci sarà si usa ''There is going to be'': ''There is going to be a storm tomorrow''. ''There are'' è plurale mentre ''a storm'' è singolare, ''They are'' non esprime l''esistenza e ''There have'' non si usa con ''going to''.', 'there-is-are', 'Grammatica', 'B1', 'There is / There are', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q215', 'Translate ''Ci sono dei biscotti nella scatola?''', '["Are there any biscuits in the box?","Is there a biscuits in the box?","Are there much biscuits in the box?","Do there any biscuits in the box?"]', NULL, 0, 'Nelle domande sull''esistenza con un plurale si usa ''Are there'' + ''any'': ''Are there any biscuits in the box?''. ''Is there a'' non va con un plurale, ''much'' si usa solo con i nomi non numerabili e ''Do there'' non esiste.', 'there-is-are', 'Traduzione', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q216', 'Complete: ''_____ a mistake in this exercise.''', '["There is","There are","It is","This is"]', NULL, 0, '''Mistake'' è singolare, quindi ''c''è'' si dice ''There is'': ''There is a mistake in this exercise''. ''There are'' è plurale, mentre ''It is'' e ''This is'' non esprimono l''esistenza.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q217', 'Complete: ''This is not my pen. It is _____.''', '["yours","your","you","yours''"]', 'yourself', 0, 'Quando il possessivo sostituisce il nome (''your pen'') si usa il pronome possessivo: ''It is yours''. ''Your'' vuole un nome dopo di sé, ''you'' non è possessivo e ''yours'''' ha un apostrofo che non esiste.', 'possessives', 'Grammatica', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q218', 'Complete: ''_____ car is parked outside.''', '["Her","Hers","She","Hers''"]', NULL, 0, 'Davanti a un nome (''car'') serve l''aggettivo possessivo: ''Her car''. ''Hers'' si usa da solo senza nome, ''she'' è un pronome soggetto e ''hers'''' non esiste.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q219', 'Complete: ''That house is _____.'' (of us)', '["ours","our","we","us"]', 'ourselves', 0, '''That house is ___'' non ha un nome dopo lo spazio, quindi serve il pronome possessivo ''ours''. ''Our'' vuole un nome dopo di sé, mentre ''we'' e ''us'' non sono possessivi.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q220', 'Complete: ''Is this book _____?'' (of him)', '["his","him","he","his''"]', NULL, 0, '''His'' è sia aggettivo sia pronome possessivo di ''lui'', e qui senza nome dopo funziona da pronome: ''Is this book his?''. ''Him'' e ''he'' non sono possessivi, e ''his'''' non esiste.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q221', 'Complete: ''These are _____ shoes.''', '["my","mine","me","I"]', NULL, 0, 'Davanti al nome ''shoes'' serve l''aggettivo possessivo ''my''. ''Mine'' si usa da solo senza nome, mentre ''me'' e ''I'' non sono possessivi.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q222', 'Complete: ''The dog is wagging _____ tail.''', '["its","it''s","it","its''"]', 'itself', 0, 'Il possessivo di ''it'' è ''its'' senza apostrofo: ''its tail''. ''It''s'' significa ''it is'' o ''it has'', mentre ''it'' non è possessivo e ''its'''' non esiste.', 'possessives', 'Grammatica', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q223', 'Complete: ''Are those keys _____?'' (of them)', '["theirs","their","them","they"]', NULL, 0, '''Are those keys ___?'' non ha un nome dopo lo spazio, quindi serve il pronome ''theirs'': ''Are those keys theirs?''. ''Their'' vuole un nome dopo di sé, mentre ''them'' e ''they'' non sono possessivi.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q224', 'Complete: ''I lost _____ keys yesterday.''', '["my","mine","me","I"]', 'myself', 0, 'Davanti al nome ''keys'' serve l''aggettivo possessivo ''my'': ''I lost my keys''. ''Mine'' si usa da solo, e ''me'' e ''I'' non indicano possesso.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q225', 'Complete: ''This laptop is _____, not yours.''', '["mine","my","me","I"]', 'mines', 0, 'Dopo ''is'' e senza nome si usa il pronome possessivo ''mine'', che sostituisce ''my laptop'' ed è coordinato a ''yours''. ''My'' vuole un nome, mentre ''me'' e ''I'' non sono possessivi.', 'possessives', 'Grammatica', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q226', 'Translate ''Questo libro è mio.''', '["This book is mine.","This book is my.","This book is me.","This book is I."]', 'This book is mines.', 0, '''Mio'' senza nome dopo è un pronome possessivo, in inglese ''mine'': ''This book is mine''. ''My'' vuole un nome dopo, mentre ''me'' e ''I'' non indicano il possesso.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q227', 'Translate ''La loro casa è molto grande.''', '["Their house is very big.","Theirs house is very big.","They house is very big.","Them house is very big."]', 'There house is very big.', 0, '''Loro'' davanti a un nome è l''aggettivo possessivo ''their'': ''Their house''. ''Theirs'' si usa da solo, mentre ''they'' e ''them'' sono pronomi personali.', 'possessives', 'Traduzione', 'A1', 'Possessives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q228', 'Translate ''Quella è la tua giacca, non la sua (di lei).''', '["That is your jacket, not hers.","That is your jacket, not her.","That is yours jacket, not hers.","That is your jacket, not she."]', 'That is your jacket, not her''s.', 0, '''La sua'' senza il nome è un pronome possessivo, per ''lei'' è ''hers'': ''not hers''. ''Her'' vuole un nome dopo, ''yours jacket'' mette un pronome davanti a un nome e ''she'' non è possessivo.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q229', 'Translate ''I nostri amici stanno arrivando.''', '["Our friends are coming.","Ours friends are coming.","We friends are coming.","Us friends are coming."]', NULL, 0, '''Nostri'' davanti a ''friends'' è l''aggettivo possessivo ''our'': ''Our friends''. ''Ours'' si usa da solo senza nome, mentre ''we'' e ''us'' non esprimono il possesso.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q230', 'Translate ''Questi soldi sono vostri?''', '["Is this money yours?","Is this money your?","Are these money yours?","Is this money you?"]', NULL, 0, '''Money'' è non numerabile e singolare, quindi ''this money'' e ''Is''; senza nome dopo lo spazio si usa il pronome ''yours'': ''Is this money yours?''. ''Your'' vuole un nome, ''Are these money'' è sbagliato perché ''money'' non ha plurale e ''you'' non è possessivo.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q231', 'Translate ''Il suo (di lui) telefono è nuovo.''', '["His phone is new.","Him phone is new.","He phone is new.","His'' phone is new."]', 'He''s phone is new.', 0, '''Suo'' di lui davanti a un nome è ''his'': ''His phone''. ''Him'' e ''he'' non sono possessivi e ''his'''' ha un apostrofo che non esiste.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q232', 'Translate ''La mia macchina è rossa, la sua (di lui) è blu.''', '["My car is red, his is blue.","My car is red, him is blue.","Mine car is red, his is blue.","My car is red, he is blue."]', NULL, 0, '''My car'' ha il nome, quindi si usa l''aggettivo ''my''; ''la sua'' senza nome è il pronome ''his''. ''Mine car'' mette un pronome davanti a un nome, mentre ''him'' e ''he'' non sono possessivi.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q233', 'Translate ''Ho dimenticato il mio ombrello.''', '["I forgot my umbrella.","I forgot mine umbrella.","I forgot me umbrella.","I forgot I umbrella."]', NULL, 0, '''Il mio'' davanti a ''umbrella'' è l''aggettivo possessivo ''my'': ''I forgot my umbrella''. ''Mine'' non si usa davanti a un nome, mentre ''me'' e ''I'' non indicano il possesso.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q234', 'Translate ''Quelle penne sono loro (di loro).''', '["Those pens are theirs.","Those pens are their.","Those pens are them.","Those pens are they."]', NULL, 0, '''Sono loro'' senza il nome dopo vuole il pronome possessivo ''theirs'': ''Those pens are theirs''. ''Their'' vuole un nome, mentre ''them'' e ''they'' sono pronomi personali.', 'possessives', 'Traduzione', 'A1', 'Possessives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q235', 'Complete: ''I call _____ every day.'' (him/he/his/himself)', '["him","he","his","himself"]', NULL, 0, 'Dopo un verbo come ''call'' serve il pronome complemento: ''I call him''. ''He'' è il soggetto, ''his'' è possessivo e ''himself'' è riflessivo, quindi qui non vanno.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q236', 'Complete: ''She loves _____ very much.'' (me/I/my/mine)', '["me","I","my","mine"]', 'myself', 0, 'Dopo il verbo ''love'' serve il pronome complemento: ''She loves me''. ''I'' è il soggetto, mentre ''my'' e ''mine'' sono possessivi.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q237', 'Complete: ''Can you help _____ with this exercise?'' (us/we/our/ours)', '["us","we","our","ours"]', 'ourselves', 0, 'Dopo ''help'' serve il pronome complemento: ''help us''. ''We'' è il soggetto, mentre ''our'' e ''ours'' sono possessivi.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q238', 'Complete: ''I don''t know _____.'' (them/they/their/theirs)', '["them","they","their","theirs"]', NULL, 0, 'Dopo ''know'' serve il pronome complemento ''them'': ''I don''t know them''. ''They'' è il soggetto, mentre ''their'' e ''theirs'' sono possessivi.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q239', 'Complete: ''Look at _____!'' (her/she/hers/herself)', '["her","she","hers","herself"]', NULL, 0, 'Dopo una preposizione (''at'') si usa il pronome complemento ''her'': ''Look at her''. ''She'' è il soggetto, ''hers'' è un pronome possessivo e ''herself'' è riflessivo.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q240', 'Complete: ''He wants to speak to _____.'' (you/your/yours/yourself)', '["you","your","yours","yourself"]', NULL, 0, 'Dopo ''to'' serve il pronome complemento ''you'': ''speak to you''. ''Your'' e ''yours'' sono possessivi, mentre ''yourself'' si usa quando il soggetto è già ''you'', non ''he''.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q241', 'Complete: ''Give _____ to me.'' (it/its/it''s/itself)', '["it","its","it''s","itself"]', NULL, 0, 'Dopo il verbo ''give'' serve un pronome complemento, e per una cosa il pronome è ''it'' ("dallo a me"). ''Its'' è un possessivo ("suo"), "it''s" significa "it is" e ''itself'' è riflessivo ("se stesso"): nessuno dei tre può essere l''oggetto di ''give''.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q242', 'Complete: ''My parents are visiting _____.'' (me/I/my/mine)', '["me","I","my","mine"]', 'myself', 0, 'Il soggetto è ''My parents'', quindi dopo il verbo ''visiting'' serve il pronome complemento ''me'' ("mi vengono a trovare"). ''I'' è un pronome soggetto, mentre ''my'' e ''mine'' sono possessivi e non possono stare da soli come oggetto.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q243', 'Complete: ''Are you listening to _____?'' (him/he/his/himself)', '["him","he","his","himself"]', NULL, 0, 'Dopo una preposizione come ''to'' si usa il pronome complemento: ''listening to him''. ''He'' è un pronome soggetto, ''his'' è possessivo e ''himself'' si usa solo quando il soggetto e l''oggetto sono la stessa persona.', 'object-pronouns', 'Grammatica', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q244', 'Translate ''Non lo capisco.'' (di lui)', '["I don''t understand him.","I don''t understand he.","I don''t understand his.","I don''t understand it."]', 'I don''t understand himself.', 0, '''Lo'' riferito a un uomo (il suggerimento dice "di lui") si traduce con il pronome complemento ''him''. ''He'' e ''his'' sono soggetto e possessivo, mentre ''it'' si usa per le cose, non per una persona.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q245', 'Translate ''Puoi vederci?''', '["Can you see us?","Can you see we?","Can you see our?","Can you see me?"]', 'Can you see ourselves?', 0, '''Ci'' in "vederci" significa "vedere noi", e il pronome complemento di ''we'' è ''us''. ''We'' è un pronome soggetto e ''our'' è un possessivo, mentre ''me'' indicherebbe solo una persona (io).', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q246', 'Translate ''Le ho comprato un regalo.'' (a lei)', '["I bought her a present.","I bought she a present.","I bought hers a present.","I bought for her a present."]', NULL, 0, '''Le'' (a lei) diventa il pronome complemento ''her'', messo subito dopo il verbo: ''bought her a present''. ''She'' è soggetto, ''hers'' è un possessivo e ''for her'' va dopo il regalo (''a present for her''), non prima.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q247', 'Translate ''Li aspetto qui.''', '["I''ll wait for them here.","I''ll wait for they here.","I''ll wait them here.","I''m waiting they here."]', NULL, 0, '''Li'' = ''them'' (pronome complemento), e in inglese ''wait'' vuole ''for'' prima dell''oggetto: ''wait for them''. ''They'' è un pronome soggetto, e ''wait them'' senza ''for'' è sbagliato.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q248', 'Translate ''Dammi quel libro.''', '["Give me that book.","Give I that book.","Give my that book.","Give to me that book."]', 'Give myself that book.', 0, 'Dopo ''give'' serve il pronome complemento ''me'': ''Give me that book''. ''I'' è soggetto e ''my'' è possessivo (andrebbe seguito da un nome), mentre ''Give to me that book'' ha l''ordine delle parole sbagliato (sarebbe ''Give that book to me'').', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q249', 'Translate ''Non ti credo.''', '["I don''t believe you.","I don''t believe your.","I don''t believe to you.","I not believe you."]', 'I don''t believe yourself.', 0, '''Ti'' si traduce con ''you'', che in inglese è uguale come soggetto e come complemento. ''Your'' è un possessivo, ''believe to you'' ha una preposizione di troppo e ''I not believe'' manca dell''ausiliare: la negazione si fa con ''don''t''.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q250', 'Translate ''Lo voglio adesso.'' (un oggetto)', '["I want it now.","I want him now.","I want them now.","I want he now."]', NULL, 0, 'Il suggerimento dice che ''lo'' indica un oggetto singolare, e il pronome complemento per le cose è ''it''. ''Him'' si usa solo per un uomo, ''them'' è plurale e ''he'' è un pronome soggetto, che dopo il verbo non si può usare.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q251', 'Translate ''Vieni con noi al cinema?''', '["Are you coming with us to the cinema?","Are you coming with we to the cinema?","Are you coming with our to the cinema?","Are you coming to us to the cinema?"]', NULL, 0, '''Con noi'' richiede il pronome complemento ''us'' dopo la preposizione ''with''. ''With we'' è sbagliato perché ''we'' è soggetto, ''with our'' è un aggettivo possessivo che vuole un nome, e ''coming to us'' cambia il senso ("vieni da noi").', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q252', 'Translate ''Non li conosco.''', '["I don''t know them.","I don''t know they.","I don''t know their.","I not know them."]', 'I don''t know they''re.', 0, '''Li'' = ''them'', pronome complemento di ''they'', dopo il verbo ''know''. ''They'' è un pronome soggetto, ''their'' è possessivo, e ''I not know'' è sbagliato perché la negazione del presente semplice vuole ''don''t''.', 'object-pronouns', 'Traduzione', 'A1', 'Object Pronouns', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q253', 'Complete: ''_____ is my friend, Paul.'' (near)', '["This","These","Those","That"]', 'Them', 0, '''This'' si usa per una persona o cosa singolare vicina a chi parla, e qui il suggerimento dice ''near''. ''These'' e ''those'' sono plurali (''is'' va con il singolare) e ''that'' indica qualcosa di lontano.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q254', 'Complete: ''Look at _____ birds in the sky.''', '["those","that","this","a"]', NULL, 0, '''Birds'' è plurale, quindi serve un dimostrativo plurale: gli uccelli sono nel cielo, lontani da chi parla, quindi ''those''. ''That'' e ''this'' sono singolari e ''a'' non si usa davanti a un plurale.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q255', 'Complete: ''Are _____ your shoes here?''', '["these","this","that","a"]', NULL, 0, '''Shoes'' è plurale e la frase dice ''here'', quindi le scarpe sono vicine a chi parla: ''these''. ''This'' e ''that'' sono singolari e ''a'' non si usa davanti a un plurale.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q256', 'Complete: ''_____ building over there is a hospital.''', '["That","This","These","Those"]', 'There', 0, '''Building'' è singolare e ''over there'' significa lontano, quindi ''That''. ''This'' indica qualcosa di vicino, mentre ''these'' e ''those'' sono plurali e non vanno con ''building''.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q257', 'Complete: ''_____ days are the best of my life.''', '["These","This","That","Each"]', NULL, 0, '''Days'' è plurale e ''are'' è presente, quindi i giorni sono quelli di adesso e si usa ''These''. ''This'' e ''That'' sono singolari e non si accordano con ''days''; ''Each'' vuole un nome singolare.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q258', 'Complete: ''I don''t like _____ kind of music.'' (near/current)', '["this","these","those","them"]', NULL, 0, '''Kind'' è singolare, quindi serve un dimostrativo singolare, e il suggerimento ''near/current'' dice di usare ''this''. ''These'' e ''those'' sono plurali, mentre ''them'' è un pronome complemento, non un dimostrativo.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q259', 'Complete: ''Did you buy _____ apples from the market?'' (far/past)', '["those","that","this","them"]', NULL, 0, '''Apples'' è plurale e il suggerimento dice ''far/past'', quindi ''those''. ''That'' e ''this'' sono singolari, e ''them'' è un pronome complemento che non si può mettere davanti a un nome.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q260', 'Complete: ''_____ is a very interesting book.'' (holding it)', '["This","These","Those","Them"]', NULL, 0, '''Is'' e ''book'' sono singolari, e se si ha il libro in mano è vicino: ''This''. ''These'' e ''those'' sono plurali, e ''Them'' è un pronome complemento, che non può essere soggetto.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q261', 'Complete: ''Can you pass me _____ pen?'' (far)', '["that","those","these","this"]', 'them', 0, '''Pen'' è singolare e il suggerimento dice ''far'', quindi ''that pen''. ''Those'' e ''these'' sono plurali (servirebbe ''pens''), mentre ''this'' indica qualcosa di vicino.', 'demonstratives', 'Grammatica', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q262', 'Translate ''Questo è il mio gatto.''', '["This is my cat.","That is my cat.","These is my cat.","Those is my cat."]', NULL, 0, '''Questo'' vicino a chi parla, singolare, è ''this''. ''That'' sarebbe "quello" (lontano), e ''these is'' e ''those is'' sono sbagliati perché ''these/those'' sono plurali e non vanno con ''is''.', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q263', 'Translate ''Quelli sono i miei libri.''', '["Those are my books.","That are my books.","These are my books.","This are my books."]', 'Them are my books.', 0, '''Quelli'' sono cose lontane e plurali: ''those'', e il verbo plurale è ''are''. ''That'' e ''this'' sono singolari (non vanno con ''are''), mentre ''these'' significa "questi", cioè vicini.', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q264', 'Translate ''Questa pizza è buonissima.''', '["This pizza is very good.","That pizza is very good.","These pizza is very good.","It pizza is very good."]', NULL, 0, '''Questa pizza'' è singolare e vicina: ''This pizza''. ''That'' vorrebbe dire "quella", ''These pizza'' mischia plurale e singolare, e ''It'' non è un dimostrativo e non può stare davanti a un nome.', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q265', 'Translate ''Queste ragazze sono italiane.''', '["These girls are Italian.","This girls are Italian.","Those girls are Italian.","That girls are Italian."]', 'These girl are Italian.', 0, '''Queste ragazze'' è plurale e vicino: ''These girls''. ''This'' e ''that'' sono singolari e non vanno con ''girls'', mentre ''those'' vorrebbe dire "quelle" (lontane).', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q266', 'Translate ''Quell''uomo è mio padre.''', '["That man is my father.","This man is my father.","Those man is my father.","The man is my father."]', 'That men is my father.', 0, '''Quell''uomo'' è singolare e lontano: ''That man''. ''This man'' vorrebbe dire "quest''uomo", ''Those man'' mischia plurale e singolare, e ''The man'' non traduce l''idea di "quello".', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q267', 'Translate ''Cosa sono quelle cose?''', '["What are those things?","What are these things?","What is that things?","What are that things?"]', 'What is those things?', 0, '''Cose'' è plurale e ''quelle'' indica lontananza: ''those things'', con ''are''. ''These'' vorrebbe dire "queste", mentre ''that'' e ''is that'' non vanno con il plurale ''things''.', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q268', 'Translate ''Preferisco questo vestito.''', '["I prefer this dress.","I prefer that dress.","I prefer these dress.","I prefer those dress."]', 'I prefer them dress.', 0, '''Questo vestito'' è singolare e vicino: ''this dress''. ''These'' e ''those'' sono plurali e non vanno con ''dress'' al singolare, mentre ''that'' vorrebbe dire "quel" (lontano).', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q269', 'Translate ''Conosci quelle persone?''', '["Do you know those people?","Do you know these people?","Do you know that people?","Do you know this people?"]', 'Do you know them people?', 0, '''Quelle persone'' è plurale e lontano: ''those people''. ''That'' e ''this'' sono singolari e non vanno con ''people'' (che è plurale), mentre ''these'' significa "queste".', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q270', 'Translate ''Questi sono i miei appunti.''', '["These are my notes.","This are my notes.","Those are my notes.","That are my notes."]', 'Them are my notes.', 0, '''Questi'' è plurale e vicino: ''These'', seguito da ''are''. ''This'' e ''that'' sono singolari e non vanno con ''are'', mentre ''those'' vorrebbe dire "quelli" (lontani).', 'demonstratives', 'Traduzione', 'A1', 'Demonstratives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q271', 'Complete: ''The cat is hiding _____ the bed.''', '["under","between","on","at"]', NULL, 0, '''Under'' significa "sotto", ed è la posizione di un gatto che si nasconde sotto il letto. ''Between'' richiede due cose in mezzo alle quali stare, e ''on'' (sopra) e ''at'' (in un punto) non descrivono qualcosa di sotto.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q272', 'Complete: ''She is waiting _____ the bus stop.''', '["at","in","on","under"]', NULL, 0, 'Per aspettare a una fermata dell''autobus, cioè in un punto preciso, si usa ''at'': ''at the bus stop''. ''In'' significa dentro uno spazio chiuso, ''on'' vuol dire sopra una superficie e ''under'' sotto.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q273', 'Complete: ''The picture is hanging _____ the wall.''', '["on","in","at","under"]', 'into', 0, 'Un quadro appeso sta su una superficie, quindi ''on the wall''. ''In'' vorrebbe dire dentro il muro, ''at'' non indica una superficie e ''under'' vuol dire sotto.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q274', 'Complete: ''He lives _____ London.''', '["in","at","on","by"]', NULL, 0, 'Per città e paesi si usa ''in'': ''lives in London''. ''At'' è per punti precisi (una fermata, la stazione), ''on'' per le superfici e ''by'' vuol dire "vicino a".', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q275', 'Complete: ''The car is parked _____ the house.''', '["behind","under","in","on"]', NULL, 0, '''Behind'' significa "dietro", ed è la posizione più normale per un''auto parcheggiata rispetto a una casa. ''Under'', ''in'' e ''on'' (sotto, dentro, sopra la casa) non sono posti dove si parcheggia un''auto.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q276', 'Complete: ''She sat _____ her two best friends.''', '["between","among","under","in"]', NULL, 0, 'Con due persone (''her two best friends'') si usa ''between'', che indica la posizione in mezzo a due. ''Among'' si usa con più di due, e ''under'' e ''in'' non descrivono sedersi in mezzo a due persone.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q277', 'Complete: ''The bank is _____ the post office.''', '["next to","in","on","at"]', NULL, 0, '''Next to'' significa "accanto a", e descrive due edifici vicini uno all''altro. ''In'', ''on'' e ''at'' indicherebbero che la banca è dentro o sopra l''ufficio postale, oppure in un punto di esso.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q278', 'Complete: ''There is a bridge _____ the river.''', '["over","under","in","at"]', NULL, 0, 'Un ponte attraversa il fiume stando sopra di esso: ''over the river''. ''Under'' vuol dire sotto, e ''in'' e ''at'' non descrivono la posizione di un ponte rispetto a un fiume.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q279', 'Complete: ''I left my keys _____ the table.''', '["on","in","from","between"]', NULL, 0, 'Le chiavi appoggiate sul tavolo stanno su una superficie: ''on the table''. ''In'' vuol dire dentro, ''from'' indica provenienza e non va con ''left'' in questa frase, ''between'' ha bisogno di due cose.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q280', 'Translate ''Il cane è sotto il tavolo.''', '["The dog is under the table.","The dog is on the table.","The dog is at the table.","The dog is in the table."]', 'The dog is over the table.', 0, '''Sotto'' si traduce con ''under''. ''On'' vuol dire sopra, ''at'' indica un punto e ''in'' vuol dire dentro: sono tutte posizioni diverse.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q281', 'Translate ''Sono al cinema.''', '["I am at the cinema.","I am into the cinema.","I am on the cinema.","I am to the cinema."]', 'I am over the cinema.', 0, '''Al cinema'' è un luogo dove si svolge un''attività, quindi ''at the cinema'' (come ''at school''). ''Into'' indica movimento verso l''interno, ''on'' si usa per le superfici e ''to'' indica direzione, non posizione.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q282', 'Translate ''C''è un ragno sul soffitto.''', '["There is a spider on the ceiling.","There is a spider at the ceiling.","There is a spider in the ceiling.","There is a spider under the ceiling."]', NULL, 0, 'Il soffitto è una superficie, quindi un ragno ci sta ''on the ceiling''. ''In'' e ''at'' non descrivono una superficie, mentre ''under'' vuol dire sotto il soffitto.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q283', 'Translate ''L''ufficio è vicino alla banca.''', '["The office is near the bank.","The office is in the bank.","The office is between the bank.","The office is at the bank."]', 'The office is over the bank.', 0, '''Vicino a'' si traduce con ''near''. ''Between'' ha bisogno di due luoghi, e ''in'' e ''at'' vorrebbero dire che l''ufficio è dentro la banca o in un punto della banca.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q284', 'Translate ''Il bambino è tra i suoi genitori.''', '["The child is between his parents.","The child is among his parents.","The child is next to his parents.","The child is in his parents."]', NULL, 0, 'Un bambino con due genitori sta in mezzo a due persone: ''between''. ''Among'' si usa con più di due, ''next to'' vuol dire "accanto a" e ''in'' vorrebbe dire "dentro" i genitori.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q285', 'Translate ''Nasconditi dietro la porta.''', '["Hide behind the door.","Hide under the door.","Hide next to the door.","Hide in the door."]', 'Hide in front of the door.', 0, '''Dietro'' si traduce con ''behind''. ''Under'' vuol dire sotto, ''next to'' accanto e ''in the door'' dentro la porta, che non ha senso.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q286', 'Translate ''Metti i vestiti nell''armadio.''', '["Put the clothes in the wardrobe.","Put the clothes on the wardrobe.","Put the clothes at the wardrobe.","Put the clothes to the wardrobe."]', 'Put the clothes by the wardrobe.', 0, 'I vestiti si mettono dentro uno spazio chiuso, quindi ''in the wardrobe''. ''On'' è per le superfici, ''at'' per un punto e ''to'' indica direzione verso un posto, non posizione.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q287', 'Translate ''Ho incontrato Marco alla stazione.''', '["I met Marco at the station.","I met Marco into the station.","I met Marco on the station.","I met Marco to the station."]', 'I met Marco over the station.', 0, '''Alla stazione'' è un punto preciso dove ci si incontra, quindi ''at the station''. ''Into'' indica movimento verso l''interno, mentre ''on'' e ''to'' non si usano in questo modo.', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q288', 'Translate ''C''è un giardino dietro la casa.''', '["There is a garden behind the house.","There is a garden under the house.","There is a garden in the house.","There is a garden next to the house."]', 'There is a garden in front of the house.', 0, '''Dietro'' si traduce con ''behind''. ''Under'' vuol dire sotto, ''in'' dentro e ''next to'' accanto: tutte posizioni diverse da "dietro la casa".', 'prepositions-place', 'Traduzione', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q289', 'Complete: ''_____ to me carefully.''', '["Listen","Listening","Listens","To listen"]', NULL, 0, 'L''imperativo si fa con la forma base del verbo, senza soggetto: ''Listen to me''. ''Listening'', ''Listens'' e ''To listen'' non sono forme dell''imperativo.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q290', 'Complete: ''_____ open the window. It''s cold.''', '["Don''t","Not","No","Doesn''t"]', 'Aren''t', 0, 'L''imperativo negativo si forma con ''Don''t'' + forma base: "Don''t open". ''Not'' e ''No'' non si usano da soli all''inizio, e ''Doesn''t'' vale solo per la terza persona singolare, non per un ordine.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q291', 'Complete: ''_____ your vegetables!''', '["Eat","Eating","Eats","To eat"]', 'Ate', 0, 'Un ordine diretto usa la forma base del verbo: ''Eat your vegetables!''. ''Eating'', ''Eats'' e ''To eat'' non sono forme dell''imperativo.', 'imperative', 'Grammatica', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q292', 'Complete: ''_____ be late for the meeting.''', '["Don''t","Not","Doesn''t","No"]', 'Isn''t', 0, 'L''imperativo negativo è ''Don''t'' + forma base (''Don''t be late''), anche con il verbo ''be''. ''Not'', ''No'' e ''Doesn''t'' non possono aprire un ordine.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q293', 'Complete: ''_____ quiet, please.''', '["Be","Are","Is","Am"]', 'Been', 0, 'L''imperativo di ''to be'' è la forma base ''Be'': ''Be quiet, please.''. ''Are'', ''Is'' e ''Am'' sono forme coniugate e hanno bisogno di un soggetto (you, he, I).', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q294', 'Complete: ''_____ touch that plate, it''s hot.''', '["Don''t","No","Not","Doesn''t"]', NULL, 0, 'L''imperativo negativo si forma con ''Don''t'' + forma base: "Don''t touch". ''No'', ''Not'' e ''Doesn''t'' non possono aprire un ordine.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q295', 'Complete: ''_____ your homework before dinner.''', '["Do","Does","Doing","Did"]', 'Make', 0, 'L''imperativo di ''do'' è la forma base ''Do'': ''Do your homework''. ''Does'' vale solo per he/she/it, ''Doing'' è la forma -ing e ''Did'' è passato: nessuno è un imperativo.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q296', 'Complete: ''_____ me the salt, please.''', '["Pass","Passing","Passes","To pass"]', 'Passed', 0, 'L''imperativo è la forma base del verbo e non ha soggetto: ''Pass me the salt''. ''Passing'', ''Passes'' e ''To pass'' non sono forme dell''imperativo.', 'imperative', 'Grammatica', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q297', 'Complete: ''_____ worry about it.''', '["Don''t","Not","No","Doesn''t"]', 'Aren''t', 0, 'L''imperativo negativo si forma con ''Don''t'' + forma base: "Don''t worry". ''Not'' e ''No'' da soli non bastano e ''Doesn''t'' non va con un ordine.', 'imperative', 'Grammatica', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q298', 'Translate ''Non toccare il mio telefono.''', '["Don''t touch my phone.","Not touch my phone.","No touch my phone.","Doesn''t touch my phone."]', 'Don''t to touch my phone.', 0, '"Non toccare" si traduce con ''Don''t touch'', cioè ''Don''t'' + forma base. ''Not touch'' e ''No touch'' non sono frasi inglesi corrette, e ''Doesn''t touch'' è la terza persona singolare, non un ordine.', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q299', 'Translate ''Fai attenzione!''', '["Pay attention!","Do attention!","Make attention!","Attention you!"]', 'Take attention!', 0, '"Fare attenzione" in inglese è ''pay attention'', un''espressione fissa. ''Do attention'' e ''Make attention'' sono traduzioni letterali sbagliate, e ''Attention you!'' non è una frase corretta.', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q300', 'Translate ''Ascoltami quando parlo.''', '["Listen to me when I speak.","Listen me when I speak.","Hear me when I speak.","Hear to me when I speak."]', NULL, 0, 'In inglese ''listen'' vuole ''to'' prima dell''oggetto: ''Listen to me''. ''Listen me'' manca di ''to'', ''Hear'' significa "sentire" (percepire un suono) e non vuole mai ''to'', quindi ''Hear to me'' è sbagliato.', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q301', 'Translate ''Non dimenticare le chiavi.''', '["Don''t forget your keys.","Not forget your keys.","No forget your keys.","Don''t missing your keys."]', 'Don''t to forget your keys.', 0, '"Non dimenticare" si traduce con ''Don''t forget'', cioè ''Don''t'' + forma base. ''Not forget'' e ''No forget'' non sono forme corrette, e ''Don''t missing'' sbaglia perché dopo ''don''t'' non si mette -ing (e ''miss'' non significa "dimenticare").', 'imperative', 'Traduzione', 'A1', 'Imperative', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q302', 'Translate ''Chiudi la porta, per favore.''', '["Close the door, please.","Closing the door, please.","To close the door, please.","Closes the door, please."]', 'Closed the door, please.', 0, 'L''ordine si fa con la forma base del verbo: ''Close the door, please.''. ''Closing'' e ''To close'' non sono imperativi e ''Closes'' è la terza persona singolare del presente.', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q303', 'Translate ''Non parlare durante l''esame.''', '["Don''t speak during the exam.","Not speak during the exam.","Doesn''t speak during the exam.","Don''t speaking during the exam."]', 'Don''t to speak during the exam.', 0, '"Non parlare" è ''Don''t speak'': ''Don''t'' + forma base. ''Not speak'' e ''Doesn''t speak'' non sono forme dell''imperativo, e dopo ''don''t'' non si mette -ing (''speaking'').', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q304', 'Translate ''Aspetta qui un momento.''', '["Wait here a moment.","Waiting here a moment.","Wait here a time.","Waits here a moment."]', 'Waited here a moment.', 0, 'L''imperativo è la forma base: ''Wait here''. ''Waiting'' e ''Waits'' non sono imperativi, e ''un momento'' è ''a moment'', non ''a time'' (che vuol dire "una volta").', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q305', 'Translate ''Scrivete i vostri nomi sul foglio.''', '["Write your names on the paper.","Writing your names on the paper.","You write your names on the paper.","To write your names on the paper."]', 'Wrote your names on the paper.', 0, 'L''imperativo è uguale per ''tu'' e ''voi'': ''Write your names...''. ''Writing'' e ''To write'' non sono imperativi, e ''You write'' è una frase dichiarativa, non un ordine normale.', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q306', 'Translate ''Non fumare in questa stanza.''', '["Don''t smoke in this room.","Smoke not in this room.","Not smoke in this room.","Doesn''t smoke in this room."]', 'Don''t smoked in this room.', 0, '"Non fumare" si traduce con ''Don''t smoke'': ''Don''t'' + forma base. ''Not smoke'' e ''Smoke not'' non sono forme usate oggi, e ''Doesn''t smoke'' è una frase dichiarativa ("lui non fuma").', 'imperative', 'Traduzione', 'A1', 'Imperative', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q307', 'Complete: ''I _____ to visit my grandparents this weekend.''', '["am going","go","going","will going"]', 'am go', 0, 'Per un programma già deciso si usa ''be going to'' + forma base: ''am going to visit''. ''Go'' e ''going'' da soli non esprimono il futuro (manca ''am ... to''), e ''will going'' è una forma inesistente.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q308', 'Complete: ''Look at those dark clouds. It _____ rain.''', '["is going to","will to","going to","rains"]', NULL, 0, '''Going to'' si usa per prevedere il futuro quando ci sono segnali evidenti adesso (nuvole scure): ''It is going to rain''. ''Going to'' senza ''is'' è incompleto, ''will to'' è una forma sbagliata (dopo ''will'' non c''è ''to'') e ''rains'' è un presente semplice che non esprime una previsione.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q309', 'Complete: ''What _____ you going to do tonight?''', '["are","do","is","will"]', 'have', 0, 'Nelle domande con ''going to'' si usa il verbo ''be'' coniugato prima del soggetto: ''What are you going to do?''. ''Do'' e ''will'' non sono parte di questa struttura, e ''is'' non concorda con ''you''.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q310', 'Complete: ''She _____ not going to buy a new car.''', '["is","does","has","will"]', 'do', 0, 'La negazione di ''be going to'' si fa con ''be'' + not: ''is not going to''. ''Does'', ''has'' e ''will'' non fanno parte della struttura e con ''going to'' non si possono usare.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q311', 'Complete: ''We are going to _____ a movie after dinner.''', '["watch","watching","watched","watches"]', NULL, 0, 'Dopo ''going to'' si usa la forma base del verbo: ''going to watch''. ''Watching'', ''watched'' e ''watches'' non vanno dopo ''to'' in questa struttura.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q312', 'Complete: ''_____ he going to invite her to the party?''', '["Is","Does","Will","Has"]', NULL, 0, 'Per fare una domanda con ''going to'' si inverte ''be'' e il soggetto: ''Is he going to...?''. ''Does'' non va con ''going to'', ''Will'' non è parte della struttura e ''Has'' non c''entra.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q313', 'Complete: ''They _____ going to start a new business next year.''', '["are","will","do","have"]', 'is', 0, 'Il soggetto è ''They'' (plurale), quindi ''be going to'' diventa ''are going to''. ''Will'' non può stare prima di ''going to'' e ''do'' e ''have'' non fanno parte di questa struttura.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q314', 'Complete: ''I''m going to _____ English in London.''', '["study","studying","studied","studies"]', 'to study', 0, 'Dopo ''going to'' si usa la forma base: ''going to study''. ''Studying'', ''studied'' e ''studies'' sono forme sbagliate dopo ''to'' in questa struttura.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q315', 'Complete: ''My parents are _____ to travel to Spain.''', '["going","go","will","goes"]', NULL, 0, 'La struttura è ''be going to'', quindi ''are going to travel''. ''Go'' e ''goes'' non sono la forma -ing necessaria, e ''will'' non può sostituire ''going'' in questa struttura.', 'going-to', 'Grammatica', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q316', 'Translate ''Cosa hai intenzione di fare?''', '["What are you going to do?","What will you do?","What do you do?","What you are going to do?"]', 'What are you going to doing?', 0, '"Avere intenzione di" si esprime con ''be going to'': ''What are you going to do?''. Nelle domande ''be'' va prima del soggetto, quindi ''What you are going to do?'' è sbagliato; ''What do you do?'' significa "che lavoro fai?", cioè un''abitudine.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q317', 'Translate ''Non ho intenzione di aspettare tutto il giorno.''', '["I am not going to wait all day.","I don''t go to wait all day.","I won''t to wait all day.","I am not going to waiting all day."]', 'I am not going wait all day.', 0, '"Non ho intenzione di" si traduce con ''am not going to'' + forma base. ''I don''t go to wait'' e ''I won''t to wait'' sono forme sbagliate (dopo ''won''t'' non ci va ''to''), e dopo ''going to'' non ci va la forma -ing.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q318', 'Translate ''Lui studierà medicina all''università.'' (intenzione)', '["He is going to study medicine at university.","He going to study medicine at university.","He is going to studying medicine at university.","He is going study medicine at university."]', NULL, 0, 'Un''intenzione già decisa si esprime con ''be going to'' + forma base: ''is going to study''. Le altre opzioni sbagliano la forma: manca ''is'', oppure il verbo dopo ''to'' è in -ing, oppure manca ''to''.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q319', 'Translate ''Abbiamo intenzione di comprare una nuova casa.''', '["We are going to buy a new house.","We will buy a new house.","We are going buy a new house.","We buy a new house."]', 'We are going to buying a new house.', 0, 'Un''intenzione o una decisione già presa si esprime con ''be going to'' + forma base: ''We are going to buy''. ''Going buy'' senza ''to'' è sbagliato, e ''We buy'' è un presente abituale.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q320', 'Translate ''Pioverà a breve.'' (guardando il cielo scuro)', '["It is going to rain soon.","It going to rain soon.","It is raining soon.","It rains soon."]', NULL, 0, 'Una previsione basata su ciò che si vede ora (cielo scuro) usa ''be going to'': ''It is going to rain soon''. ''It going to'' non ha il verbo ''be'', mentre ''It is raining'' e ''It rains'' non sono previsioni sul futuro.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q321', 'Translate ''Non parteciperanno all''incontro.'' (intenzione)', '["They aren''t going to attend the meeting.","They not going to attend the meeting.","They don''t attend the meeting.","They aren''t going to attending the meeting."]', NULL, 0, 'Una negazione che esprime l''intenzione si fa con ''be not going to'' + forma base: ''They aren''t going to attend''. ''They not going to'' non ha il verbo ''be'', ''don''t attend'' è un presente abituale e dopo ''to'' non va il verbo in -ing.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q322', 'Translate ''Cosa mangerai a cena?'' (che programmi hai)', '["What are you going to eat for dinner?","What are you going eat for dinner?","What do you eat for dinner?","What is you going to eat for dinner?"]', NULL, 0, 'Il suggerimento indica che si parla di programmi già fatti, quindi ''be going to'': ''What are you going to eat?''. Manca ''to'' in ''going eat'', ''is you'' non si accorda (con ''you'' serve ''are'') e ''What do you eat?'' parla di abitudine.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q323', 'Translate ''Venderà la sua macchina?'' (ha intenzione di)', '["Is she going to sell her car?","Does she going to sell her car?","Does she sell her car?","Is she sell her car?"]', NULL, 0, 'Una domanda sull''intenzione si fa con ''be'' + soggetto + ''going to'': ''Is she going to sell her car?''. ''Does'' non si combina con ''going to'', ''Does she sell'' parla di abitudine e dopo ''is'' non si può usare la forma base.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q324', 'Translate ''Cadrà!'' (lo vedi correre sul ghiaccio)', '["He''s going to fall!","He is going fall!","He falls!","He falling!"]', 'He''s go to fall!', 0, 'Una previsione basata su ciò che si vede ora (corre sul ghiaccio) usa ''be going to'': "He''s going to fall!". ''He is going fall'' manca di ''to'', ''He falls'' è un presente abituale e ''He falling'' non ha il verbo ausiliare.', 'going-to', 'Traduzione', 'A2', 'Future: going to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q325', 'Complete: ''I _____ TV when the phone rang.''', '["was watching","watched","am watching","were watching"]', NULL, 0, 'L''azione lunga in corso (guardare la TV) si mette al past continuous, quella breve che la interrompe (squilla il telefono) al past simple: ''was watching''. ''Were'' non va con ''I'', e ''watched'' e ''am watching'' non descrivono un''azione in corso nel passato.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q326', 'Complete: ''While she was reading, her brother _____ video games.''', '["was playing","were playing","playing","is playing"]', NULL, 0, '''While'' introduce due azioni che avvengono nello stesso momento nel passato, quindi anche la seconda va al past continuous: ''was playing'' (soggetto singolare, ''her brother''). ''Were'' non si accorda, ''playing'' senza ausiliare è incompleto e ''is playing'' è presente.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q327', 'Complete: ''What _____ you doing at 8 PM yesterday?''', '["were","was","are","did"]', 'have', 0, 'Il past continuous si forma con ''was/were'' + -ing, e con ''you'' si usa ''were''. ''Was'' va con I/he/she/it, ''are'' è presente e ''did'' richiederebbe la forma base (''did you do'').', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q328', 'Complete: ''They _____ in the park when it started to rain.''', '["were walking","was walking","are walking","walking"]', NULL, 0, 'L''azione lunga che fa da sfondo (''in the park'') si mette al past continuous e il soggetto plurale vuole ''were walking''. ''Was walking'' è singolare, ''are walking'' è presente e ''walking'' da solo manca dell''ausiliare.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q329', 'Complete: ''He _____ (not) listening to the teacher.''', '["wasn''t","weren''t","didn''t","isn''t"]', 'hasn''t', 0, 'Il past continuous negativo si fa con ''was/were not'' + -ing, e con ''He'' si usa ''wasn''t''. ''Weren''t'' va con you/we/they, ''didn''t'' vuole la forma base e ''isn''t'' è presente.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q330', 'Complete: ''While I _____ home, I saw a car accident.''', '["was driving","were driving","am driving","was drive"]', NULL, 0, '''While'' introduce un''azione in corso nel passato (past continuous), interrotta da un''altra breve (''I saw''): ''was driving''. Con ''I'' si usa ''was'', non ''were''; ''am driving'' è presente e ''was drive'' manca di -ing.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q331', 'Complete: ''We were having dinner when the lights _____ out.''', '["went","were going","go","gone"]', NULL, 0, 'L''azione breve che interrompe (le luci che si spengono) va al Past Simple: ''went out''. ''Were going'' non ha senso con ''lights'' qui, e ''go'' o ''gone'' non sono forme di passato semplice.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q332', 'Complete: ''_____ it raining when you left?''', '["Was","Were","Did","Is"]', 'Has', 0, 'Il Past Continuous si forma con was/were + -ing; con ''it'' (singolare) si usa ''was''. ''Were'' va con you/we/they, ''Did'' vuole il verbo base (did it rain) e ''Is'' è presente.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q333', 'Complete: ''I broke my leg while I _____ football.''', '["was playing","played","am playing","play"]', NULL, 0, 'Mentre si svolge un''azione lunga (giocavo a calcio), un''altra la interrompe (mi sono rotto la gamba): l''azione di sfondo va al Past Continuous, ''was playing''. ''Am playing'' e ''play'' sono presente; ''played'' non rende l''azione in corso.', 'past-continuous', 'Grammatica', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q334', 'Translate ''Cosa stavi facendo quando ti ho chiamato?''', '["What were you doing when I called you?","What did you do when I called you?","What was you doing when I called you?","What are you doing when I called you?"]', 'What were you do when I called you?', 0, '''Cosa stavi facendo?'' è un''azione in corso nel passato: Past Continuous, ''were you doing''. ''What was you'' è sbagliato (con ''you'' si usa sempre ''were''), ''did you do'' chiede cosa hai fatto, non cosa stavi facendo, e ''are'' è presente.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q335', 'Translate ''Stavo dormendo quando l''allarme ha suonato.''', '["I was sleeping when the alarm rang.","I am sleeping when the alarm rang.","I was sleep when the alarm rang.","I was sleeping when the alarm ringed."]', NULL, 0, '''Stavo dormendo'' è l''azione lunga (Past Continuous: was sleeping), ''ha suonato'' è l''evento breve che la interrompe (Past Simple: rang). ''Am sleeping'' è presente, ''was sleep'' manca di -ing e ''ringed'' non è il passato di ''ring''.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q336', 'Translate ''Mentre camminavamo, abbiamo trovato dei soldi.''', '["While we were walking, we found some money.","While we walked, we were finding some money.","When we were walking, we were finding some money.","While we walking, we found some money."]', NULL, 0, '''While'' introduce di solito l''azione in corso (Past Continuous: were walking), poi arriva l''evento breve al Past Simple (found). ''We walking'' manca di ''were'', e ''were finding'' non va bene perché trovare dei soldi è un momento, non un''azione che dura.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q337', 'Translate ''Lei non stava guardando la TV, stava leggendo.''', '["She wasn''t watching TV, she was reading.","She didn''t watching TV, she was reading.","She wasn''t watching TV, she reading.","She wasn''t watch TV, she was reading."]', 'She wasn''t watched TV, she was reading.', 0, 'Entrambe le azioni sono in corso nel passato, quindi due Past Continuous: ''wasn''t watching'' e ''was reading''. Le altre opzioni hanno errori di forma: ''didn''t watching'' mescola ausiliare e -ing, ''she reading'' non ha ''was'', ''wasn''t watch'' manca di -ing.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q338', 'Translate ''Mentre cucinavo, lui ascoltava la musica.''', '["While I was cooking, he was listening to music.","While I was cook, he was listening to music.","While I cooking, he was listening to music.","While I was cooking, he were listening to music."]', NULL, 0, 'Due azioni contemporanee e in corso nel passato vanno entrambe al Past Continuous: ''was cooking'' e ''was listening''. Le altre opzioni hanno errori netti: ''was cook'' senza -ing, ''I cooking'' senza ''was'', ''he were'' (con he/she/it si usa ''was'').', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q339', 'Translate ''Pioveva forte ieri mattina?''', '["Was it raining hard yesterday morning?","Did it raining hard yesterday morning?","Were it raining hard yesterday morning?","Is it raining hard yesterday morning?"]', 'Was it rain hard yesterday morning?', 0, '''Pioveva'' è un''azione in corso in un momento del passato, quindi Past Continuous in forma interrogativa: ''Was it raining...?''. ''Did'' non si usa con -ing, ''Were'' non va con ''it'' e ''Is'' è presente.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q340', 'Translate ''Non stavamo andando troppo veloci.''', '["We weren''t going too fast.","We didn''t go too fast.","We wasn''t going too fast.","We aren''t going too fast."]', 'We weren''t go too fast.', 0, 'La negativa del Past Continuous è wasn''t/weren''t + -ing; con ''we'' si usa ''weren''t''. ''We wasn''t'' è sbagliato, ''didn''t go'' è un passato semplice (non ''stavamo andando'') e ''aren''t'' è presente.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q341', 'Translate ''Cosa pensavi in quel momento?''', '["What were you thinking at that moment?","What was you thinking at that moment?","What are you thinking at that moment?","What did you thinking at that moment?"]', 'What were you think at that moment?', 0, '''Cosa pensavi in quel momento'' descrive qualcosa che era in corso: ''What were you thinking''. ''Was you'' è sbagliato (con you sempre ''were''), ''are you thinking'' è presente e ''did you thinking'' mescola ''did'' con la forma in -ing.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q342', 'Translate ''Loro ridevano quando sono entrato.''', '["They were laughing when I entered.","They laughing when I entered.","They was laughing when I entered.","They were laugh when I entered."]', NULL, 0, '''Ridevano'' è lo sfondo (Past Continuous: were laughing), ''sono entrato'' è l''evento breve (Past Simple: entered). Le altre opzioni sbagliano la forma: manca ''were'', ''was'' non si accorda con ''they'', ''laugh'' manca di -ing.', 'past-continuous', 'Traduzione', 'A2', 'Past Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q343', 'Complete: ''You look tired. You _____ go to bed early.''', '["should","have to","mustn''t","don''t have to"]', NULL, 0, 'Per un consiglio (''dovresti andare a letto presto, sei stanco'') si usa ''should''. ''Have to'' esprime un obbligo, ''mustn''t'' un divieto e ''don''t have to'' dice che non è necessario: nessuno ha senso dopo ''You look tired''.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q344', 'Complete: ''In many countries, you _____ wear a seatbelt when driving.''', '["have to","has to","don''t have to","mustn''t"]', NULL, 0, 'Una legge o una regola esterna si esprime con ''have to'' (obbligo). ''Has to'' non si accorda con ''you'', ''don''t have to'' vuol dire non è necessario e ''mustn''t'' è un divieto, cioè il contrario di ciò che dice la legge sulle cinture.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q345', 'Complete: ''Tomorrow is Sunday, so I _____ wake up early.''', '["don''t have to","mustn''t","shouldn''t","haven''t to"]', 'doesn''t have to', 0, 'Domani è domenica, quindi non è necessario svegliarsi presto: ''don''t have to'' indica assenza di obbligo. ''Mustn''t'' è un divieto, ''shouldn''t'' un consiglio negativo e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q346', 'Complete: ''You _____ use your phone during the exam! It''s forbidden.''', '["mustn''t","don''t have to","shouldn''t","haven''t to"]', NULL, 0, 'Se è vietato usare il telefono si usa ''mustn''t'', che indica divieto. ''Don''t have to'' significa solo che non è obbligatorio (non è proibito), ''shouldn''t'' è un consiglio e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q347', 'Complete: ''_____ I wear a suit to the interview?''', '["Should","Does","Have to","Do I must"]', NULL, 0, 'Per chiedere un consiglio si usa ''Should I...?''. ''Does I'' ha il verbo sbagliato, ''Have to'' non fa una domanda senza ''Do I'' davanti e ''Do I must'' è errato perché ''must'' non si usa con ''do''.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q348', 'Complete: ''We have plenty of time. We _____ hurry.''', '["don''t have to","mustn''t","shouldn''t","don''t must"]', NULL, 0, 'C''è molto tempo, quindi non c''è bisogno di fare in fretta: ''don''t have to'' (assenza di obbligo). ''Mustn''t'' sarebbe un divieto, ''shouldn''t'' un consiglio negativo e ''don''t must'' non esiste, perché ''must'' non vuole ''do''.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q349', 'Complete: ''All visitors _____ wear a helmet on the building site. It''s the law.''', '["must","mustn''t","don''t have to","musts"]', 'has to', 0, 'Per una regola o una legge si usa ''must'' + verbo base. ''Mustn''t'' direbbe che indossare il casco è vietato, ''don''t have to'' che non serve, e ''musts'' non esiste: i modali non prendono la -s.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q350', 'Complete: ''He _____ wear glasses to read because his eyesight is bad.''', '["has to","must to","musts","have to"]', NULL, 0, 'Con ''he'' si usa ''has to'' per una necessità (ha la vista debole, quindi gli serve). ''Have to'' è per I/you/we/they, ''must to'' e ''musts'' sono errate perché ''must'' non vuole né ''to'' né la -s.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q351', 'Complete: ''Do I _____ pay for this ticket now?''', '["have to","must","should","had to"]', 'to have', 0, 'Nelle domande con ''do'' il verbo che segue deve essere alla forma base: ''Do I have to pay?''. ''Do I must'', ''Do I should'' e ''Do I had to'' sono errate: ''must'' e ''should'' non si usano con ''do'', e dopo ''do'' non va il passato.', 'modals-obligation-advice', 'Grammatica', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q352', 'Translate ''Dovresti mangiare più verdure.''', '["You should eat more vegetables.","You must eat more vegetables.","You have to eat more vegetables.","You shouldn''t eat more vegetables."]', 'You should to eat more vegetables.', 0, '''Dovresti'' è un consiglio, quindi ''should''. ''Must'' e ''have to'' esprimono obbligo (più forti), mentre ''shouldn''t'' dice l''opposto: non mangiare più verdure.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q353', 'Translate ''Non devi per forza venire se sei stanco.''', '["You don''t have to come if you''re tired.","You mustn''t come if you''re tired.","You shouldn''t come if you''re tired.","You haven''t to come if you''re tired."]', 'You don''t must come if you''re tired.', 0, '''Non devi per forza'' vuol dire che non è necessario: ''don''t have to''. ''Mustn''t'' significa che è vietato, ''shouldn''t'' che è meglio non farlo e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q354', 'Translate ''Non devi assolutamente toccare quel filo!''', '["You mustn''t touch that wire!","You don''t have to touch that wire!","You shouldn''t touch that wire!","You haven''t to touch that wire!"]', 'You not must touch that wire!', 0, '''Non devi assolutamente'' è un divieto forte: ''mustn''t''. ''Don''t have to'' dice soltanto che non è necessario, ''shouldn''t'' è un consiglio più debole e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q355', 'Translate ''Lui deve lavorare fino a tardi oggi.'' (obbligo esterno)', '["He has to work late today.","He should work late today.","He have to work late today.","He musts work late today."]', NULL, 0, '''Deve lavorare'' per un obbligo esterno si traduce con ''has to'' (he/she/it). ''Should'' è un consiglio, ''he have to'' non concorda e ''musts'' non esiste perché i modali non prendono la -s.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q356', 'Translate ''Non dovresti bere così tanto caffè.''', '["You shouldn''t drink so much coffee.","You mustn''t drink so much coffee.","You don''t have to drink so much coffee.","You haven''t to drink so much coffee."]', 'You shouldn''t to drink so much coffee.', 0, '''Non dovresti'' è un consiglio negativo: ''shouldn''t'' + verbo base. ''Mustn''t'' sarebbe un divieto, ''don''t have to'' dice che non è necessario e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q357', 'Translate ''Devo togliermi le scarpe?''', '["Do I have to take off my shoes?","Must I to take off my shoes?","Do I must take off my shoes?","Have I to take off my shoes?"]', 'Do I have take off my shoes?', 0, 'La domanda su un obbligo si fa con ''Do I have to'' + verbo base. ''Must I to'' è errata perché ''must'' non vuole ''to'', ''Do I must'' perché ''must'' non si usa con ''do'', e ''Have I to'' non è inglese corretto moderno.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q358', 'Translate ''Non hai bisogno di pagare, è gratis.''', '["You don''t have to pay, it''s free.","You mustn''t pay, it''s free.","You shouldn''t pay, it''s free.","You haven''t to pay, it''s free."]', 'You not have to pay, it''s free.', 0, '''Non hai bisogno di pagare'' vuol dire che non è necessario: ''don''t have to''. ''Mustn''t'' direbbe che pagare è vietato, ''shouldn''t'' che è meglio non pagare, e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q359', 'Translate ''Cosa dovrei fare?''', '["What should I do?","What must I do?","What have I to do?","What do I do?"]', NULL, 0, '''Cosa dovrei fare?'' chiede un consiglio, quindi ''What should I do?''. ''Must'' esprime obbligo, ''What have I to do'' non è corretto e ''What do I do?'' è un presente generico, non ''dovrei''.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q360', 'Translate ''Non devi dire niente a nessuno, è un segreto!''', '["You mustn''t tell anyone, it''s a secret!","You don''t have to tell anyone, it''s a secret!","You shouldn''t tell anyone, it''s a secret!","You haven''t to tell anyone, it''s a secret!"]', NULL, 0, 'Dire qualcosa a qualcuno è proibito perché è un segreto: ''mustn''t'' (divieto). ''Don''t have to'' direbbe che non è obbligatorio, ''shouldn''t'' è solo un consiglio e ''haven''t to'' non esiste.', 'modals-obligation-advice', 'Traduzione', 'A2', 'Modals of Obligation and Advice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q361', 'Complete: ''She speaks English very _____.'' (good/well)', '["well","good","goodly","welling"]', 'bad', 0, 'Per descrivere come parla (un verbo) serve un avverbio; l''avverbio di ''good'' è ''well''. ''Good'' è un aggettivo, mentre ''goodly'' e ''welling'' non esistono.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q362', 'Complete: ''He drives very _____. It''s dangerous!''', '["fast","fastly","quick","speedy"]', NULL, 0, '''Fast'' è sia aggettivo sia avverbio e ha la stessa forma: ''drives fast''. ''Fastly'' non esiste, e ''quick'' è un aggettivo (l''avverbio sarebbe ''quickly'').', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q363', 'Complete: ''Please do your work _____. Take your time.''', '["carefully","careful","careless","carelessly"]', 'care', 0, 'Serve un avverbio che dica come lavorare: ''carefully'' (con attenzione). ''Careful'' è un aggettivo, e ''careless/carelessly'' significano senza attenzione, in contrasto con ''Take your time''.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q364', 'Complete: ''They won the game _____. They were much better.''', '["easily","easy","easier","easying"]', 'easiest', 0, 'Serve un avverbio per descrivere ''won'': dall''aggettivo ''easy'' si forma ''easily'' (y diventa i + -ly). ''Easy'' è aggettivo, ''easier'' è un comparativo e ''easying'' non esiste.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q365', 'Complete: ''The old man walked _____ down the street.''', '["slowly","slowlier","slowingly","slowness"]', 'slowy', 0, '''Walked'' è un verbo, quindi serve un avverbio: ''slowly'' (aggettivo slow + -ly). ''Slowlier'' e ''slowingly'' non esistono e ''slowness'' è un nome.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q366', 'Complete: ''She looked at him _____ when he broke the glass.''', '["angrily","angry","angrier","angrying"]', 'with angry', 0, 'Per dire come lo guardò serve un avverbio: da ''angry'' si forma ''angrily'' (y diventa i + -ly). ''Angry'' è aggettivo, ''angrier'' un comparativo e ''angrying'' non esiste.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q367', 'Complete: ''He worked _____ to pass the exam.''', '["hard","hardly","hardy","hards"]', NULL, 0, '''Hard'' è un avverbio irregolare con la stessa forma dell''aggettivo e vuol dire ''con impegno''. ''Hardly'' significa ''quasi per niente'' (cambia il senso), ''hardy'' è un aggettivo (robusto) e ''hards'' non esiste.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q368', 'Complete: ''The children were playing _____ in the garden.''', '["happily","happy","happier","happiness"]', 'happiest', 0, 'Per descrivere come giocavano serve un avverbio: da ''happy'' si ottiene ''happily''. ''Happy'' è aggettivo, ''happier'' comparativo e ''happiness'' un nome.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q369', 'Complete: ''I can run very _____.''', '["fast","fastly","quick","faster"]', NULL, 0, '''Fast'' ha la stessa forma come aggettivo e avverbio: ''run very fast''. ''Fastly'' non esiste, ''quick'' è un aggettivo e ''faster'' è un comparativo, che non si usa con ''very''.', 'adverbs-manner', 'Grammatica', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q370', 'Translate ''Ha risposto alla domanda velocemente.''', '["He answered the question quickly.","He answered the question quickily.","He answered the question fastly.","He answered the question quickness."]', 'He answered the question with quick.', 0, '''Velocemente'' modifica il verbo, quindi serve l''avverbio ''quickly'' (aggettivo quick + -ly). ''Quickily'' ha l''ortografia sbagliata, ''fastly'' non esiste (''fast'' ha già la forma di avverbio) e ''quickness'' è un nome.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q371', 'Translate ''Canta davvero bene.''', '["She sings really well.","She sings really goodly.","She sing really well.","She is sings really well."]', NULL, 0, 'Con il verbo ''sings'' si usa l''avverbio ''well'' (bene). ''Goodly'' non esiste, ''She sing'' non concorda (serve ''sings'' con ''she'') e ''is sings'' mescola due forme verbali.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q372', 'Translate ''Hanno lavorato duramente tutto il giorno.''', '["They worked hard all day.","They worked hardly all day.","They worked difficultly all day.","They worked heavy all day."]', NULL, 0, '''Duramente'' nel senso di ''con fatica'' è ''hard'', avverbio con la stessa forma dell''aggettivo. ''Hardly'' vuol dire ''quasi per niente'' (senso opposto), ''difficultly'' non esiste e ''heavy'' è un aggettivo.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q373', 'Translate ''Per favore, parla lentamente.''', '["Please speak slowly.","Please speak slowness.","Please speak slowlier.","Please speak slowingly."]', NULL, 0, 'Dopo ''speak'' serve un avverbio: ''slowly'' (aggettivo slow + -ly). ''Slowness'' è un nome, ''slowlier'' e ''slowingly'' non esistono.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q374', 'Translate ''Ha chiuso la porta silenziosamente.''', '["He closed the door quietly.","He closed the door quietness.","He closed the door quietlyly.","He closed the door quietily."]', NULL, 0, '''Closed'' è un verbo, quindi serve un avverbio: ''quietly''. ''Quietness'' è un nome, ''quietlyly'' ha il suffisso -ly doppio e ''quietily'' ha l''ortografia sbagliata.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q375', 'Translate ''Hanno risolto il problema facilmente.''', '["They solved the problem easily.","They solved the problem easy.","They solved the problem with easy.","They solved the problem easier."]', NULL, 0, 'Serve un avverbio per ''solved'': da ''easy'' si forma ''easily''. ''Easy'' è aggettivo, ''with easy'' non è corretto e ''easier'' è un comparativo.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q376', 'Translate ''Guida sempre con molta attenzione (attentamente).''', '["He always drives carefully.","He always drives careful.","He always drives care.","He always drives with careful."]', NULL, 0, 'Dopo ''drives'' serve un avverbio, ''carefully'' (careful + -ly). ''Careful'' è aggettivo, ''care'' è un nome e ''with careful'' non è una costruzione corretta.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q377', 'Translate ''L''insegnante ha spiegato la regola chiaramente.''', '["The teacher explained the rule clearly.","The teacher explained the rule clear.","The teacher explained the rule cleary.","The teacher explained the rule clearing."]', NULL, 0, 'Per dire come ha spiegato serve un avverbio: ''clearly'' (clear + -ly). ''Clear'' è aggettivo, ''cleary'' è scritto male e ''clearing'' è un gerundio, non un avverbio.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q378', 'Translate ''Ho capito perfettamente.''', '["I understood perfectly.","I understood perfect.","I understood perfection.","I understood perfectlyly."]', 'I understood perfectest.', 0, '''Understood'' è un verbo, quindi serve un avverbio: ''perfectly''. ''Perfect'' è aggettivo, ''perfection'' è un nome e ''perfectlyly'' ha il suffisso doppio.', 'adverbs-manner', 'Traduzione', 'A2', 'Adverbs of Manner', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q379', 'Complete the sentence: ''If I _____ the lottery, I would buy a big house.''', '["win","won","will win","had won"]', 'would win', 1, 'Il Second Conditional per situazioni irreali o improbabili nel presente/futuro si forma ''If + Past Simple, would + verbo base''. Perciò ''won''; ''win'' e ''will win'' appartengono ad altri periodi ipotetici, ''had won'' al terzo (passato).', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q380', 'Translate ''Se fossi in te, studierei di più.''', '["If I am you, I will study more.","If I were you, I would study more.","If I was you, I study more.","If I would be you, I studied more."]', 'If I were you, I would studying more.', 1, 'Nel Second Conditional si dice ''If I were you, I would + verbo base'' (''Se fossi in te''). Le altre opzioni mescolano i tempi o mettono ''would'' nella frase con ''if'', che non è corretto.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q381', 'Complete the sentence: ''If I had studied, I _____ the exam.''', '["would pass","passed","would have passed","will pass"]', 'would had passed', 2, 'Con ''If + Past Perfect'' (had studied) la frase principale è ''would have + participio passato'': ''would have passed''. È il Third Conditional, per una situazione passata che non è più modificabile. ''Would pass'' e ''will pass'' sono tempi presenti/futuri.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q382', 'Translate ''Se fossimo partiti prima, non avremmo perso il treno.''', '["If we left earlier, we wouldn''t miss the train.","If we had left earlier, we wouldn''t have missed the train.","If we would leave earlier, we hadn''t missed the train.","If we have left earlier, we didn''t miss the train."]', 'If we had left earlier, we wouldn''t missed the train.', 1, '''Se fossimo partiti prima, non avremmo perso'' è un Third Conditional: ''If + had + participio, would(n''t) have + participio''. Le altre opzioni usano tempi sbagliati (left, would leave, have left) o incrociano le due parti.', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q383', 'Complete the sentence: ''The letter _____ by John yesterday.''', '["wrote","was written","is written","writes"]', 'has written', 1, '''The letter'' non scrive, viene scritta: passivo, e con ''yesterday'' il Past Simple Passive è ''was written''. ''Wrote'' e ''writes'' sono attivi, ''is written'' è presente.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q384', 'Translate ''La casa viene costruita proprio ora.''', '["The house is built right now.","The house builds right now.","The house is being built right now.","The house has been built right now."]', 'is been built', 2, '''Viene costruita proprio ora'' è un''azione in corso nel presente: Present Continuous passivo, ''is being built''. ''Is built'' indica un fatto abituale, ''builds'' è attivo e ''has been built'' dice che è già finita.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q385', 'Change to reported speech: He said, ''I am tired.''', '["He said that he were tired.","He said that I was tired.","He said that he was tired.","He said that he is being tired."]', NULL, 2, 'Nel discorso indiretto, dopo ''said'' il verbo fa un passo indietro: ''am'' diventa ''was'', e il pronome segue chi parla: ''he was tired''. ''I was tired'' ha il pronome sbagliato, ''he were'' non concorda e ''is being tired'' non è un tempo adatto.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q386', 'Change to reported speech: ''I will call you,'' she told me.', '["She told me she would calling me.","She told me she would call me.","She told me I would call her.","She told me she called me."]', NULL, 1, 'Nel discorso indiretto ''will'' diventa ''would'' (seguito dalla forma base) e il pronome ''I'' diventa ''she'', mentre ''you'' diventa ''me'': ''she would call me''. ''Would calling'' è sbagliato, ''I would call her'' scambia le persone e ''called'' trasforma il futuro in passato.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q387', 'Complete the sentence: ''When I arrived at the station, the train _____.''', '["will already leave","has already left","had already left","already leaves"]', NULL, 2, 'Di due azioni passate, quella avvenuta prima va al Past Perfect: il treno era già partito (''had already left'') quando sono arrivato. ''Will leave'' è futuro, ''has already left'' è un Present Perfect e ''leaves'' è presente.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q388', 'Translate ''Avevo già mangiato quando mi hai chiamato.''', '["I had already eat when you called me.","I had already eaten when you called me.","I have already eaten when you called me.","I was eating when you called me."]', NULL, 1, 'L''azione avvenuta prima (''avevo già mangiato'') va al Past Perfect: ''had already eaten''. ''Had eat'' usa il participio sbagliato, ''have eaten'' è Present Perfect e ''was eating'' vorrebbe dire ''stavo mangiando''.', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q389', 'Complete the sentence: ''I _____ tennis when I was young.''', '["used to play","was playing","am used to play","use to play"]', NULL, 0, 'Un''abitudine passata che ora non c''è più si dice con ''used to'' + verbo base: ''used to play''. ''Was playing'' descrive un''azione in corso, ''am used to play'' è errato e ''use to'' non va senza ''did'' nelle frasi affermative.', 'used-to', 'Grammatica', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q390', 'Choose the correct negative form:', '["She didn''t used to like vegetables.","She hasn''t used to like vegetables.","She didn''t use to like vegetables.","She don''t use to like vegetables."]', NULL, 2, 'Nella forma negativa con ''didn''t'' il verbo torna alla forma base: ''didn''t use to'', senza la -d. ''Didn''t used to'' raddoppia il passato, ''hasn''t used to'' e ''don''t use to'' sono tempi sbagliati (e ''she don''t'' non concorda).', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q391', 'Complete the sentence: ''The man _____ lives next door is a doctor.''', '["which","who","whose","where"]', 'whom', 1, 'Per le persone nelle frasi relative si usa ''who'': ''The man who lives next door''. ''Which'' è per le cose, ''whose'' indica possesso e ''where'' i luoghi.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q392', 'Complete the sentence: ''That''s the house _____ I grew up.''', '["which","who","whose","where"]', 'what', 3, 'Per un luogo si usa ''where'' (nella casa dove sono cresciuto). ''Which'' vorrebbe ''in which'' o ''which I grew up in'', ''who'' è per le persone e ''whose'' indica possesso.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q393', 'Complete the sentence: ''The girl _____ car was stolen is at the police station.''', '["who","which","whose","that"]', 'who''s', 2, '''Whose'' esprime il possesso (la ragazza la cui auto): ''whose car''. ''Who'', ''which'' e ''that'' non si possono usare davanti a un nome posseduto come ''car''.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q394', 'Complete the sentence: ''You are Italian, _____?''', '["are you","aren''t you","don''t you","isn''t it"]', 'won''t you', 1, 'Dopo una frase affermativa la question tag è negativa e ripete il verbo: ''You are Italian, aren''t you?''. ''Are you'' è affermativa, ''don''t you'' ha l''ausiliare sbagliato e ''isn''t it'' non concorda con ''you''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q395', 'Complete the sentence: ''She didn''t go to the party, _____?''', '["did she","didn''t she","does she","was she"]', 'has she', 0, 'Dopo una frase negativa la tag è affermativa e riprende l''ausiliare ''did'' di ''didn''t go'': ''did she?''. ''Didn''t she'' è negativa, ''does'' e ''was'' sono ausiliari sbagliati per il passato di ''go''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q396', 'Complete the sentence: ''He has a Ferrari and a mansion. I am sure he _____ be very rich.''', '["can''t","must","mustn''t","might"]', NULL, 1, 'Quando le prove sono forti (Ferrari e villa) e si è sicuri, si usa ''must'' per una deduzione quasi certa: ''He must be very rich''. ''Can''t'' e ''mustn''t'' dicono il contrario, e ''might'' indica solo una possibilità debole, che non va con ''I am sure''.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q397', 'Complete the sentence: ''That _____ be Sarah. Sarah is currently in London.''', '["mustn''t","will","can''t","must"]', NULL, 2, 'Se Sarah è a Londra, sei sicuro che non può essere lei: ''can''t'' esprime la deduzione negativa forte. ''Mustn''t'' è un divieto, ''will'' è futuro e ''must'' direbbe l''opposto (sei sicuro che è lei).', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q398', 'Complete the sentence: ''I really enjoy _____ books in my free time.''', '["to read","read","reading","to reading"]', 'for reading', 2, '''Enjoy'' è seguito dal gerundio (-ing): ''enjoy reading''. L''infinito (to read, read) non si usa dopo ''enjoy'', e ''to reading'' non ha senso qui.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q399', 'Complete the sentence: ''She decided _____ a new car.''', '["buying","to buy","buy","bought"]', 'for buying', 1, '''Decide'' regge l''infinito con ''to'': ''decided to buy''. Il gerundio (buying), il verbo base (buy) e il passato (bought) non si usano dopo ''decide''.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q400', 'Complete the sentence: ''Do you mind _____ the window?''', '["open","to open","opening","opened"]', 'for opening', 2, '''Mind'' regge il gerundio: ''Do you mind opening...?''. Dopo ''do you mind'' non si usa né il verbo base, né ''to open'', né il passato.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q401', 'The restaurant _____ we had dinner is very expensive.', '["where","which","that","who"]', NULL, 0, 'Il ristorante è un luogo e la frase continua con un soggetto (''we had dinner''), quindi serve ''where'' (= in cui). ''Which'' e ''that'' richiederebbero una preposizione (''at which'', ''which we had dinner at''), ''who'' è per le persone.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q402', 'This is the man _____ dog bit me.', '["whose","who","which","that"]', NULL, 0, 'Il cane è dell''uomo: possesso, quindi ''whose''. Dopo ''who'', ''which'' e ''that'' il nome ''dog'' non può seguire direttamente per indicare il possessore.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q403', 'My sister, _____ lives in London, is coming to visit.', '["who","that","which","where"]', NULL, 0, 'Nella frase relativa non limitativa (tra virgole) riferita a una persona si usa ''who'' e non si può usare ''that''. ''Which'' è per le cose e ''where'' per i luoghi.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q404', 'Translate: ''Il film che abbiamo visto ieri era noioso.''', '["The movie which we watched yesterday was boring.","The movie who we watched yesterday was boring.","The movie where we watched yesterday was boring.","The movie whose we watched yesterday was boring."]', NULL, 0, 'Il film è una cosa, quindi serve ''which''. ''Who'' è per le persone, ''where'' per i luoghi e ''whose'' indica possesso.', 'relative-clauses', 'Traduzione', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q405', 'Translate: ''La donna la cui auto è stata rubata è la mia vicina.''', '["The woman whose car was stolen is my neighbor.","The woman who car was stolen is my neighbor.","The woman which car was stolen is my neighbor.","The woman that car was stolen is my neighbor."]', NULL, 0, '''La cui auto'' esprime possesso e si traduce con ''whose'': ''The woman whose car was stolen''. ''Who'', ''which'' e ''that'' non si possono mettere davanti a ''car'' con questo significato.', 'relative-clauses', 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q406', 'The days _____ I was young were the best.', '["when","where","which","who"]', NULL, 0, 'Per un periodo di tempo (''i giorni in cui ero giovane'') si usa ''when''. ''Where'' è per i luoghi, ''who'' per le persone e ''which'' sostituisce una cosa, non un tempo.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q407', 'I know a place _____ you can hide.', '["where","which","that","when"]', NULL, 0, 'Per un luogo in cui si può fare qualcosa si usa ''where'': ''a place where you can hide''. ''Which'' e ''that'' richiederebbero ''in'' alla fine (''which you can hide in''), mentre ''when'' è per il tempo.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q408', 'The student _____ got the highest grade is from Spain.', '["who","which","where","whose"]', NULL, 0, 'Lo studente è una persona e fa da soggetto: ''who''. ''Which'' è per le cose, ''where'' per i luoghi, ''whose'' indica possesso e non ha senso con ''got the highest grade''.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q409', 'Translate: ''Questo è il libro di cui ti parlavo.''', '["This is the book which I was telling you about.","This is the book who I was telling you about.","This is the book where I was telling you about.","This is the book whose I was telling you about."]', NULL, 0, '''Il libro di cui ti parlavo'' è una cosa: ''which'', con la preposizione ''about'' in fondo (I was telling you about). ''Who'' è per le persone, ''where'' per i luoghi e ''whose'' indica possesso.', 'relative-clauses', 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q410', 'Translate: ''Parigi, che è la capitale della Francia, è bellissima.''', '["Paris, which is the capital of France, is beautiful.","Paris, who is the capital of France, is beautiful.","Paris, where is the capital of France, is beautiful.","Paris, that is the capital of France, is beautiful."]', NULL, 0, 'Nella frase non limitativa (tra virgole) riferita a una cosa si usa ''which''. ''Who'' è per le persone, ''where'' non è corretto e ''that'' non si usa dopo una virgola.', 'relative-clauses', 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q411', 'Someone _____ travels a lot is lucky.', '["who","which","whose","where"]', NULL, 0, '''Someone'' è una persona e fa da soggetto: ''who travels''. ''Which'' è per le cose, ''whose'' indica possesso e ''where'' i luoghi.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q412', 'The cake _____ she made was delicious.', '["which","who","whose","where"]', NULL, 0, '''The cake'' è una cosa: ''which'' (la torta che lei ha fatto). ''Who'' è per le persone, ''whose'' indica possesso e ''where'' i luoghi.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q413', 'A library is a place _____ you can borrow books.', '["where","which","who","when"]', NULL, 0, 'Una biblioteca è un luogo in cui si fa qualcosa: ''where''. ''Which'' richiederebbe ''in which'', ''who'' è per le persone e ''when'' per il tempo.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q414', 'The boy _____ sister is in my class is very tall.', '["whose","who","which","that"]', NULL, 0, '''Whose'' indica possesso: la sorella del ragazzo. ''Who'', ''which'' e ''that'' non si usano davanti a un nome posseduto come ''sister''.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q415', 'Winter is the season _____ it snows.', '["when","which","where","who"]', NULL, 0, 'L''inverno è un periodo di tempo, quindi ''when it snows''. ''Which'' e ''who'' non hanno senso qui e ''where'' è per i luoghi.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q416', 'I always try to avoid _____ in traffic during rush hour.', '["driving","to drive","drive","drove"]', NULL, 0, '''Avoid'' è seguito dal gerundio: ''avoid driving''. L''infinito ''to drive'', il verbo base e il passato non si usano dopo ''avoid''.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q417', 'We hope _____ you again soon.', '["to see","seeing","see","saw"]', NULL, 0, '''Hope'' regge l''infinito con ''to'': ''hope to see''. Il gerundio (seeing), il verbo base (see) e il passato (saw) non si usano dopo ''hope''.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q418', 'Avoid _____ mistakes by checking your work.', '["making","to make","make","made"]', NULL, 0, '''Avoid'' è seguito dal gerundio: ''avoid making mistakes''. ''To make'', ''make'' e ''made'' non sono possibili dopo ''avoid''.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q419', 'She promised _____ me with my homework.', '["to help","helping","help","helped"]', NULL, 0, '''Promise'' regge l''infinito con ''to'': ''promised to help''. Dopo ''promise'' non si usa il gerundio (helping), il verbo base o il passato.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q420', 'Translate: ''Ho finito di leggere il libro.''', '["I finished reading the book.","I finished to read the book.","I finished read the book.","I finish reading the book."]', NULL, 0, '''Finish'' regge il gerundio: ''finished reading''. ''Finished to read'' e ''finished read'' sono errati, e ''I finish'' è presente mentre ''ho finito'' è passato.', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q421', 'Translate: ''Lui ha deciso di studiare all''estero.''', '["He decided to study abroad.","He decided studying abroad.","He decided study abroad.","He decides to study abroad."]', NULL, 0, 'Il verbo decide vuole l''infinito con to (decided to study). L''italiano "ha deciso" è passato, quindi decides (presente) non va bene, e dopo decide non si usa né la forma in -ing né l''infinito senza to.', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q422', 'Are you planning _____ to the party?', '["to go","going","go","went"]', NULL, 0, 'Plan è seguito dall''infinito con to: plan to go. La forma in -ing (going) dopo plan è sbagliata, e went è un passato che non può stare dopo are you planning.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q423', 'I miss _____ near the sea.', '["living","to live","live","lived"]', NULL, 0, 'Dopo miss (sentire la mancanza di, rimpiangere) si usa la forma in -ing: miss living. To live, live e lived non sono costruzioni possibili dopo questo verbo.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q424', 'Translate: ''Non mi dispiace alzarmi presto.''', '["I don''t mind getting up early.","I don''t mind to get up early.","I don''t mind get up early.","I not mind getting up early."]', NULL, 0, 'Dopo mind si usa la forma in -ing: don''t mind getting up. Nella frase negativa serve don''t (non "I not mind"), e dopo mind non si mette to + infinito.', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q425', 'Translate: ''Loro vogliono comprare una casa nuova.''', '["They want to buy a new house.","They want buying a new house.","They want buy a new house.","They want to buying a new house."]', NULL, 0, 'Want è seguito dall''infinito con to: want to buy. Forme come "want buying" o "want to buying" mescolano due costruzioni e non esistono.', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q426', 'He offered _____ for dinner.', '["to pay","paying","pay","paid"]', NULL, 0, 'Offer vuole l''infinito con to: offered to pay ("si è offerto di pagare"). Paying e paid non sono possibili dopo offer.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q427', 'Keep _____ until you reach the station.', '["walking","to walk","walk","walked"]', NULL, 0, 'Keep + -ing significa "continuare a": keep walking. Dopo keep non si usa l''infinito (to walk) né il verbo base.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q428', 'I would like _____ a pizza.', '["to order","ordering","order","ordered"]', NULL, 0, 'Would like ("vorrei") si costruisce con l''infinito con to: I would like to order. La forma in -ing non va bene dopo would like.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q429', 'Please stop _____ noise, the baby is sleeping.', '["making","to making","make","made"]', NULL, 0, 'Dopo stop si usa -ing per dire "smettere di fare": stop making noise. To making, make e made sono forme impossibili: dopo stop si può avere solo -ing oppure to + verbo base (con un altro significato).', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q430', 'I remembered _____ the door before leaving.', '["to lock","to locking","lock","locked"]', NULL, 0, 'Remember + to + infinito vuol dire "ricordarsi di fare" (non dimenticare). Dopo to si usa sempre il verbo base: to lock, mai "to locking"; locked e lock da soli non completano la frase.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q431', 'If I _____ more time, I would learn a new language.', '["had","have","would have","will have"]', NULL, 0, 'Nel secondo condizionale (situazione irreale o improbabile) la frase con if usa il past simple: if I had. Would have e will have non si mettono mai dopo if in questo tipo di frase.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q432', 'What would you do if you _____ a ghost?', '["saw","see","would see","will see"]', NULL, 0, 'Se la frase principale ha would (what would you do), nella parte con if serve il past simple: if you saw. Would see e will see dopo if sono sbagliati.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q433', 'If she _____ closer, we would see her more often.', '["lived","lives","would live","will live"]', NULL, 0, 'Secondo condizionale: if + past simple (lived), poi would + verbo base nella frase principale. Dopo if non si mette would e nemmeno will.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q434', 'Translate: ''Se fossi ricco, viaggerei per il mondo.''', '["If I were rich, I would travel the world.","If I am rich, I will travel the world.","If I was rich, I travel the world.","If I would be rich, I traveled the world."]', NULL, 0, 'Il secondo condizionale è if + past simple (con be si usa were), poi would + verbo base. Le altre opzioni mischiano i tempi: if I am + will è primo condizionale, e would dopo if è sbagliato.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q435', 'Translate: ''Se lei sapesse la verità, si arrabbierebbe.''', '["If she knew the truth, she would be angry.","If she knows the truth, she will be angry.","If she would know the truth, she was angry.","If she knew the truth, she will be angry."]', NULL, 0, '"Se sapesse" si traduce con if she knew (past simple) e "si arrabbierebbe" con she would be angry. Nelle altre opzioni compaiono knows, would know o will be, che non rispettano lo schema if + past simple, would + verbo.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q436', 'If they _____ so much pizza, they wouldn''t feel sick.', '["didn''t eat","don''t eat","wouldn''t eat","won''t eat"]', NULL, 0, 'Nella frase con if negativa del secondo condizionale si usa didn''t + verbo base: if they didn''t eat. Wouldn''t e won''t non si usano dopo if, e don''t eat è presente.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q437', 'I would buy that car if it _____ cheaper.', '["were","is","would be","will be"]', NULL, 0, 'Nel secondo condizionale il verbo be nella frase con if diventa were per tutte le persone: if it were cheaper. Is, would be e will be non vanno dopo if in questo schema.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q438', 'If you _____ more, you would pass the exam.', '["studied","study","would study","will study"]', NULL, 0, 'Secondo condizionale: if + past simple (studied), poi would + verbo base (would pass). Study è presente e would study / will study non si usano dopo if.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q439', 'Translate: ''Non andrei lì se fossi in te.''', '["I wouldn''t go there if I were you.","I won''t go there if I am you.","I didn''t go there if I were you.","I don''t go there if I was you."]', NULL, 0, 'If I were you è la formula standard per dare un consiglio, con la frase principale in would + verbo base (wouldn''t go). Le altre opzioni usano won''t, didn''t o don''t, che non sono tempi da secondo condizionale.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q440', 'Translate: ''Se avessimo una macchina, potremmo andare in montagna.''', '["If we had a car, we could go to the mountains.","If we have a car, we can go to the mountains.","If we had a car, we will go to the mountains.","If we would have a car, we went to the mountains."]', NULL, 0, 'Secondo condizionale: if we had a car (past simple) e nella principale un modale al condizionale come could (il condizionale di can). Can e will appartengono al primo condizionale, e would have dopo if è sbagliato.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q441', 'If he _____ his job, he would travel more.', '["quit","quits","will quit","would quit"]', NULL, 0, 'Nella frase con if serve il past simple, e quit ha lo stesso aspetto al presente e al passato: if he quit. Would quit non si mette dopo if, e quits o will quit non sono passati.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q442', 'She would be happier if she _____ a better job.', '["found","finds","will find","would find"]', NULL, 0, 'Nel secondo condizionale la frase con if va al past simple: if she found. Finds e will find sono tempi presente e futuro, would find non va dopo if.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q443', 'If it _____ snowing, we could go for a walk.', '["stopped","stops","will stop","would stop"]', NULL, 0, 'Past simple dopo if: if it stopped snowing, we could go. Stops e will stop sono presente e futuro, would stop non si usa dopo if.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q444', 'I _____ you if I knew the answer.', '["would tell","tell","told","will tell"]', NULL, 0, 'Nella frase principale del secondo condizionale serve would + verbo base: I would tell you. Tell, told e will tell non danno il condizionale richiesto dalla frase con if knew.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q445', 'If we _____ in a big city, we would use public transport.', '["lived","live","will live","would live"]', NULL, 0, 'Secondo condizionale: dopo if si usa il past simple (lived), nella principale would use. Live, will live e would live non vanno dopo if.', 'second-conditional', 'Grammatica', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q446', 'Translate: ''Se parlassi francese, mi trasferirei a Parigi.''', '["If I spoke French, I would move to Paris.","If I speak French, I will move to Paris.","If I would speak French, I moved to Paris.","If I spoke French, I will move to Paris."]', NULL, 0, '"Se parlassi" è if I spoke (past simple) e "mi trasferirei" è I would move. Le altre opzioni mescolano i tempi: speak + will è primo condizionale, would speak dopo if è sbagliato.', 'second-conditional', 'Traduzione', 'B1', 'Second Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q447', 'If I _____ earlier, I would have caught the train.', '["had woken up","woke up","would wake up","have woken up"]', NULL, 0, 'Terzo condizionale (passato irreale): if + past perfect (had woken up), poi would have + participio passato. Woke up e would wake up non esprimono ciò che non è successo nel passato.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q448', 'She would have passed if she _____ harder.', '["had studied","studied","would study","has studied"]', NULL, 0, 'Nel terzo condizionale la frase con if usa il past perfect: if she had studied. Studied da solo è un past simple, would study e has studied non completano la struttura.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q449', 'If we had known, we _____ you.', '["would have helped","would help","helped","had helped"]', NULL, 0, 'Nella frase principale del terzo condizionale serve would have + participio passato: we would have helped you. Would help è secondo condizionale e had helped è un past perfect, che non va nella principale.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q450', 'Translate: ''Se fossi andato a letto presto, non sarei stato stanco.''', '["If I had gone to bed early, I wouldn''t have been tired.","If I went to bed early, I wouldn''t be tired.","If I had gone to bed early, I wasn''t tired.","If I would go to bed early, I wouldn''t have been tired."]', NULL, 0, '"Se fossi andato" è if I had gone (past perfect) e "non sarei stato" è I wouldn''t have been (would have + participio). Le altre opzioni usano tempi che parlano del presente o non rispettano lo schema del terzo condizionale.', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q451', 'Translate: ''Se avesse piovuto, saremmo rimasti a casa.''', '["If it had rained, we would have stayed at home.","If it rained, we would stay at home.","If it had rained, we stayed at home.","If it rains, we will stay at home."]', NULL, 0, '"Se avesse piovuto, saremmo rimasti" è if it had rained, we would have stayed. Se si usano rained o rains si parla di presente o futuro, e we stayed non è un condizionale.', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q452', 'If he had driven carefully, he _____ the accident.', '["wouldn''t have had","wouldn''t have","didn''t have","hadn''t had"]', NULL, 0, 'Nella principale negativa del terzo condizionale si usa wouldn''t have + participio passato: wouldn''t have had the accident. Wouldn''t have da solo non ha il participio, e didn''t have e hadn''t had non sono condizionali.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q453', 'They would have won if they _____ better.', '["had played","played","would play","have played"]', NULL, 0, 'Nella frase con if del terzo condizionale serve il past perfect: if they had played. Played è un semplice passato, would play e have played non vanno dopo if in questo schema.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q454', 'If I _____ the umbrella, I would have gotten wet.', '["hadn''t taken","didn''t take","wouldn''t take","haven''t taken"]', NULL, 0, 'La frase con if negativa del terzo condizionale usa hadn''t + participio passato: if I hadn''t taken. Didn''t take, wouldn''t take e haven''t taken non sono past perfect.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q455', 'Translate: ''Cosa avresti fatto se lo avessi saputo?''', '["What would you have done if you had known?","What would you do if you knew?","What did you do if you had known?","What have you done if you knew?"]', NULL, 0, 'Domanda al terzo condizionale: What would you have done if you had known? Le altre opzioni cambiano i tempi (would you do + knew è secondo condizionale) e non esprimono il passato irreale dell''italiano.', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q456', 'Translate: ''Se avessi visto il messaggio, ti avrei risposto.''', '["If I had seen the message, I would have replied.","If I saw the message, I would reply.","If I would have seen the message, I replied.","If I had seen the message, I had replied."]', NULL, 0, '"Se avessi visto, ti avrei risposto" è if I had seen (past perfect), I would have replied. Would have dopo if (would have seen) e had replied nella principale sono sbagliati.', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q457', 'If she _____ the directions, she wouldn''t have gotten lost.', '["had followed","followed","would follow","has followed"]', NULL, 0, 'Terzo condizionale: if + past perfect (had followed), poi would have + participio (wouldn''t have gotten lost). Followed da solo, would follow e has followed non rispettano la struttura.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q458', 'I _____ to the party if they had invited me.', '["would have gone","would go","went","had gone"]', NULL, 0, 'La principale del terzo condizionale usa would have + participio passato: I would have gone. Would go è secondo condizionale, went è un passato semplice e had gone è un past perfect, che qui non va.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q459', 'If it _____ so cold, we would have gone swimming.', '["hadn''t been","wasn''t","wouldn''t be","hasn''t been"]', NULL, 0, 'Nella frase con if negativa del terzo condizionale serve hadn''t + participio: if it hadn''t been so cold. Wasn''t, wouldn''t be e hasn''t been non sono past perfect.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q460', 'We would have bought the house if it _____ cheaper.', '["had been","was","would be","has been"]', NULL, 0, 'Past perfect di be: had been (if it had been cheaper), perché si parla di un''occasione passata mancata. Was, would be e has been non vanno nel terzo condizionale dopo if.', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q461', 'If you had asked me, I _____ yes.', '["would have said","would say","said","had said"]', NULL, 0, 'Nella principale del terzo condizionale serve would have + participio passato: I would have said yes. Would say, said e had said non danno il senso di "avrei detto".', 'third-conditional', 'Grammatica', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q462', 'Translate: ''Sarebbe venuta se avesse avuto tempo.''', '["She would have come if she had had time.","She would come if she had time.","She came if she had had time.","She would have came if she had time."]', NULL, 0, '"Sarebbe venuta se avesse avuto" è she would have come if she had had time: had had è il past perfect di have (had + participio had). Would have came è sbagliato perché dopo would have serve il participio (come, non came).', 'third-conditional', 'Traduzione', 'B1', 'Third Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q463', 'The Mona Lisa _____ by Leonardo da Vinci.', '["was painted","painted","is painted","paints"]', NULL, 0, 'Un dipinto fatto da Leonardo in passato richiede il passivo al past simple: was + participio passato (was painted). Painted da solo è attivo, is painted è presente e paints è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q464', 'English _____ in many countries around the world.', '["is spoken","speaks","was spoken","has spoken"]', NULL, 0, 'Per un fatto generale si usa il passivo al present simple: is + participio passato (is spoken). Speaks è attivo, was spoken è passato e has spoken è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q465', 'My car _____ at the moment.', '["is being repaired","is repairing","repairs","has repaired"]', NULL, 0, 'At the moment indica un''azione in corso, quindi passivo al present continuous: is being repaired. Is repairing è attivo (l''auto non ripara), repairs e has repaired sono tempi diversi.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q466', 'Translate: ''Il libro è stato scritto nel 1990.''', '["The book was written in 1990.","The book is written in 1990.","The book wrote in 1990.","The book has been written in 1990."]', NULL, 0, '"È stato scritto nel 1990" ha una data precisa nel passato, quindi passivo al past simple: was written. Is written è presente, wrote è attivo e has been written non si usa con una data definita come 1990.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q467', 'Translate: ''La stanza viene pulita ogni giorno.''', '["The room is cleaned every day.","The room was cleaned every day.","The room is being cleaned every day.","The room cleans every day."]', NULL, 0, '"Viene pulita ogni giorno" è un''abitudine: passivo al present simple, is cleaned. Was cleaned è passato, is being cleaned indica un''azione in corso e non una routine, cleans è attivo.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q468', 'A new supermarket _____ in our town next year.', '["will be built","will build","is built","was built"]', NULL, 0, 'Con next year serve il futuro passivo: will be + participio passato (will be built). Will build è attivo (il supermercato non costruisce), is built e was built sono presente e passato.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q469', 'The thieves _____ by the police yesterday.', '["were caught","caught","are caught","have caught"]', NULL, 0, 'Yesterday richiede il passato e i ladri subiscono l''azione, quindi passivo al past simple plurale: were caught. Caught è attivo, are caught è presente, have caught è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q470', 'This picture _____ by my grandfather.', '["was taken","took","is taken","takes"]', NULL, 0, 'Il quadro è stato fatto da qualcuno, in passato: passivo al past simple, was taken. Took è attivo, is taken è presente e takes è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q471', 'Translate: ''I biglietti sono già stati venduti.''', '["The tickets have already been sold.","The tickets has already been sold.","The tickets have already being sold.","The tickets have already be sold."]', NULL, 0, '"Sono già stati venduti" è un passivo al present perfect: have + been + participio (have already been sold). Has non concorda con tickets (plurale), being è il gerundio e be è la forma base: nessuna delle due completa il passivo del present perfect.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q472', 'Translate: ''Il problema deve essere risolto subito.''', '["The problem must be solved immediately.","The problem must solve immediately.","The problem has to solve immediately.","The problem must been solved immediately."]', NULL, 0, 'Con un verbo modale il passivo è modale + be + participio: must be solved. Must solve è attivo, has to solve è attivo e must been solved sbaglia perché dopo must serve be, non been.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q473', 'The emails _____ every morning at 8 am.', '["are sent","send","were sent","have sent"]', NULL, 0, 'Every morning indica un''abitudine, quindi passivo al present simple: are sent (le email sono inviate). Send è attivo, were sent è passato e have sent è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q474', 'The dinner _____ when the guests arrived.', '["was being cooked","was cooking","is cooked","has been cooked"]', NULL, 0, 'When the guests arrived indica un''azione in corso nel passato: passivo al past continuous, was being cooked. Was cooking è attivo, is cooked è presente e has been cooked è un present perfect.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q475', 'The bridge _____ in 2005.', '["was built","built","is built","has built"]', NULL, 0, 'In 2005 è una data passata e il ponte è stato costruito (non costruisce), quindi passivo al past simple: was built. Built è attivo, is built è presente e has built è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q476', 'All the cake _____ by the children before I came.', '["had been eaten","had eaten","was eating","is eaten"]', NULL, 0, 'Before I came indica un''azione conclusa prima di un altro momento passato, quindi past perfect passivo: had been eaten. Had eaten è attivo (il dolce non mangia), was eating e is eaten non mostrano il prima.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q477', 'The keys _____ on the table yesterday.', '["were left","left","are left","have left"]', NULL, 0, 'Yesterday richiede il passato e le chiavi subiscono l''azione: passivo al past simple, were left. Left è attivo, are left è presente e have left è attivo.', 'passive-voice', 'Grammatica', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q478', 'Translate: ''La mia bicicletta è stata rubata ieri.''', '["My bicycle was stolen yesterday.","My bicycle is stolen yesterday.","My bicycle has been stolen yesterday.","My bicycle stole yesterday."]', NULL, 0, '"È stata rubata ieri" ha un tempo passato preciso, quindi passivo al past simple: was stolen. Has been stolen non si usa con yesterday, is stolen è presente e stole è attivo.', 'passive-voice', 'Traduzione', 'B1', 'Passive Voice', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q479', 'He said, ''I like apples.'' -> He said that he _____ apples.', '["liked","was liking","like","liking"]', NULL, 0, 'Nel discorso indiretto con said (passato) il present simple slitta al past simple: he liked apples. Like senza -s è sbagliato con he, e was liking e liking non vanno con un verbo di gusto come like.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q480', 'She said, ''I am watching TV.'' -> She said that she _____ TV.', '["was watching","were watching","watching","had watched"]', NULL, 0, 'Nel discorso indiretto il present continuous diventa past continuous: she was watching TV. Were non concorda con she, watching da solo non ha l''ausiliare, e had watched è un past perfect che indicherebbe un''azione finita prima, non in corso.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q481', '''I will go,'' he said. -> He said that he _____ go.', '["would","going to","can","could"]', NULL, 0, 'Nel discorso indiretto will diventa would: he said that he would go. Going to manca dell''ausiliare (was going to go), mentre can e could esprimono capacità o possibilità e non il futuro di "I will go".', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q482', 'Translate: ''Mi ha detto che era stanco.''', '["He told me that he was tired.","He said me that he was tired.","He told to me that he was tired.","He said that he is tired."]', NULL, 0, 'Tell vuole sempre un complemento di persona (told me), mentre say no: he told me that... Said me e told to me sono costruzioni sbagliate, e he is tired non rispetta lo slittamento al passato.', 'reported-speech', 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q483', 'Translate: ''Lei disse che non sapeva la risposta.''', '["She said that she didn''t know the answer.","She told that she didn''t know the answer.","She said that she didn''t knew the answer.","She told me that she hasn''t known the answer."]', NULL, 0, 'Said non vuole il pronome (she said that...), told sì. Dopo said il verbo slitta al passato: didn''t know. She told that è sbagliato senza complemento, didn''t knew ha il passato dopo didn''t e hasn''t known è un present perfect che non rende "non sapeva".', 'reported-speech', 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q484', '''I have finished,'' she said. -> She said that she _____ finished.', '["had","have","been","having"]', NULL, 0, 'Nel discorso indiretto il present perfect diventa past perfect: she had finished. Con she il verbo have non concorda (servirebbe has) e non è al passato; been e having non formano il perfetto con finished.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q485', 'He asked me where I _____.', '["lived","living","did I live","do I live"]', NULL, 0, 'Nelle domande indirette l''ordine è soggetto + verbo, senza do/did, e il tempo slitta al passato: where I lived. Did I live e do I live tengono l''ordine della domanda diretta, e living senza ausiliare non è un verbo coniugato.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q486', 'She asked if I _____ coffee.', '["liked","liking","did I like","do I like"]', NULL, 0, 'Nelle domande sì/no indirette si usa if + soggetto + verbo al passato: if I liked coffee. Did I like e do I like mantengono l''ordine della domanda diretta, e liking senza ausiliare non è un verbo coniugato.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q487', 'Translate: ''Mi ha chiesto se volessi venire.''', '["He asked me if I wanted to come.","He asked me do I want to come.","He said me if I wanted to come.","He told me if I wanted to come."]', NULL, 0, 'Per le domande indirette si usa asked + if + soggetto + verbo, senza do e al passato: asked me if I wanted. Dopo ask non si usa la domanda diretta (do I want), e said / told me if non reggono if.', 'reported-speech', 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q488', 'Translate: ''Ha detto che avrebbe chiamato più tardi.''', '["He said that he would call later.","He said that he would to call later.","He told that he would call later.","He said that he would called later."]', NULL, 0, 'Nel discorso indiretto will diventa would: he said that he would call later. Dopo would il verbo resta alla forma base, quindi would to call e would called sono sbagliati; told that senza me è sbagliato.', 'reported-speech', 'Traduzione', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q489', '''Don''t touch that!'' he said. -> He told me _____ that.', '["not to touch","don''t touch","didn''t touch","not touch"]', NULL, 0, 'Un ordine negativo riportato si costruisce con told + persona + not to + verbo base: not to touch. Don''t touch e didn''t touch non si usano nel discorso indiretto, e not touch senza to è sbagliato.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q490', '''Open the door,'' she said. -> She told me _____ the door.', '["to open","open","opened","opening"]', NULL, 0, 'Un ordine riportato si costruisce con told + persona + to + verbo base: told me to open. Open, opened e opening non si usano dopo told me.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q491', 'He said, ''I can swim.'' -> He said that he _____ swim.', '["could","can to","would","might"]', NULL, 0, 'Nel discorso indiretto can diventa could: he said that he could swim. Can to è sbagliato (i modali non vogliono to), mentre would e might cambiano il significato e non rendono la capacità di nuotare.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q492', 'She asked, ''Are you okay?'' -> She asked me _____ okay.', '["if I was","if was I","are you","if am I"]', NULL, 0, 'Nelle domande indirette il tempo slitta e l''ordine è soggetto + verbo: she asked me if I was okay. If was I e if am I mantengono l''ordine della domanda, e are you non ha if e non ha il verbo al passato.', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q493', '''I must go,'' he said. -> He said that he _____ go.', '["had to","musts","must to","have to"]', NULL, 0, 'Nel discorso indiretto must di solito diventa had to: he said that he had to go. Musts e must to non esistono, e have to non concorda con he (dovrebbe essere has to).', 'reported-speech', 'Grammatica', 'B1', 'Reported Speech', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q494', 'Translate: ''Mi ha consigliato di studiare.''', '["He advised me to study.","He advised to study.","He said me to study.","He told to me to study."]', NULL, 0, 'Advise vuole persona + to + verbo base: he advised me to study. Advised to study manca del complemento di persona, said me e told to me to sono costruzioni sbagliate.', 'reported-speech', 'Traduzione', 'B1', 'Reported Speech', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q495', 'By the time we arrived, the movie _____.', '["had started","started","has started","starts"]', NULL, 0, 'By the time + un momento passato richiede il past perfect per ciò che era già successo prima: the movie had started. Started, has started e starts non indicano un''azione anteriore a quella dell''arrivo.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q496', 'I realized I _____ my keys at home.', '["had left","has left","had leave","leaving"]', NULL, 0, 'Prima hai lasciato le chiavi, poi te ne sei accorto (realized, passato): per l''azione più lontana serve il past perfect, had left. Has left non concorda con I, had leave non ha il participio e leaving non è un verbo coniugato.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q497', 'She was tired because she _____ all day.', '["had worked","had work","has worked","works"]', NULL, 0, 'Era stanca (passato) perché aveva lavorato prima: past perfect, had worked. Had work non ha il participio, has worked e works non sono tempi del passato.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q498', 'Translate: ''Avevo appena finito di mangiare quando ha bussato.''', '["I had just finished eating when he knocked.","I had just finish eating when he knocked.","I have just finished eating when he knocked.","I had just finished to eat when he knocked."]', NULL, 0, '"Avevo appena finito" è un past perfect con just: had just finished. Had just finish non ha il participio, il present perfect (have just finished) lega l''azione a oggi, e dopo finished si usa -ing (finished eating), non to eat.', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q499', 'Translate: ''Non avevo mai visto quel film prima di ieri.''', '["I had never seen that movie before yesterday.","I had never saw that movie before yesterday.","I have never seen that movie before yesterday.","I hadn''t never seen that movie before yesterday."]', NULL, 0, '"Non avevo mai visto" prima di ieri è un past perfect con never: had never seen. Had never saw usa il past simple al posto del participio, have never seen lega al presente e hadn''t never ha una doppia negazione.', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q501', 'By the time the manager called, they _____ the project.', '["had finished","finished","have finished","finish"]', NULL, 0, 'By the time + passato richiede il past perfect per l''azione conclusa prima: they had finished. Finished, have finished e finish non mostrano che il progetto era già finito quando il manager ha chiamato.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q502', 'He didn''t want to eat because he _____ lunch.', '["had already had","had already have","has already had","already has"]', NULL, 0, 'Non voleva mangiare perché aveva già pranzato prima: past perfect, had already had (had + participio had). Had already have non ha il participio, has already had e already has sono present perfect o presente.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q503', 'Translate: ''Ero arrabbiato perché avevo perso il portafoglio.''', '["I was angry because I had lost my wallet.","I was angry because I was lost my wallet.","I was angry because I have lost my wallet.","I was angry because I had lose my wallet."]', NULL, 0, '"Avevo perso" il portafoglio prima di arrabbiarsi: past perfect, had lost. Was lost my wallet non ha senso (was lost vuole un soggetto che si perde), have lost lega a oggi e had lose non ha il participio (lost).', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q504', 'Translate: ''Avevano vissuto lì per dieci anni prima di trasferirsi.''', '["They had lived there for ten years before moving.","They had live there for ten years before moving.","They have lived there for ten years before moving.","They had lived there since ten years before moving."]', NULL, 0, '"Avevano vissuto per dieci anni prima di trasferirsi" è un past perfect: had lived there for ten years. Had live non ha il participio, have lived collega al presente e since ten years è sbagliato (con una durata si usa for).', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q505', 'I _____ him before that day.', '["had never met","had never meet","have never met","never meet"]', NULL, 0, 'Prima di quel giorno è un momento passato, quindi past perfect: had never met. Had never meet non ha il participio, have never met lega al presente e never meet è presente.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q506', 'The grass was yellow because it _____ all summer.', '["hadn''t rained","hadn''t rain","hasn''t rained","doesn''t rain"]', NULL, 0, 'L''erba era gialla perché non aveva piovuto per tutta l''estate prima di allora: past perfect negativo, hadn''t rained. Hadn''t rain non ha il participio, hasn''t rained lega al presente e doesn''t rain è presente.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q507', 'She passed the test because she _____ hard.', '["had studied","had study","has studied","studies"]', NULL, 0, 'Aveva studiato prima di superare il test: past perfect, had studied (had + participio). Had study non ha il participio passato, has studied e studies non vanno in un racconto al passato.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q508', 'I couldn''t open the door because I _____ the key.', '["had lost","had lose","have lost","lose"]', NULL, 0, 'Non riusciva ad aprire la porta perché aveva perso la chiave prima: past perfect, had lost. Had lose non ha il participio, have lost lega al presente e lose è presente.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q509', 'By the time I woke up, everyone _____.', '["had gone","went","has gone","goes"]', NULL, 0, 'By the time + passato richiede il past perfect: everyone had gone, cioè erano già andati prima che mi svegliassi. Went, has gone e goes non esprimono ciò che era già successo.', 'past-perfect', 'Grammatica', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q510', 'Translate: ''La festa era già finita quando siamo arrivati.''', '["The party had already ended when we arrived.","The party had already end when we arrived.","The party has already ended when we arrived.","The party had already ending when we arrived."]', NULL, 0, '"Era già finita quando siamo arrivati" è un past perfect con already: had already ended. Had already end e had already ending non hanno il participio passato, e has already ended lega la festa al presente.', 'past-perfect', 'Traduzione', 'B1', 'Past Perfect', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q511', 'I _____ eat a lot of chocolate, but now I don''t.', '["used to","use to","was used to","am used to"]', NULL, 0, 'Per un''abitudine passata che ora non c''è più si usa ''used to'' + verbo base. ''Use to'' senza -d non funziona nelle frasi affermative, e ''was/am used to'' vuol dire ''essere abituato'', che richiede un nome o un verbo in -ing.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q512', '_____ you use to play video games when you were a kid?', '["Did","Do","Were","Are"]', NULL, 0, 'Nelle domande sul passato si mette ''Did'' all''inizio e ''use to'' senza -d, perché ''did'' porta già il passato. ''Do'' e ''Are'' sono al presente e ''Were'' non si combina con ''use to''.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q513', 'She _____ like coffee, but now she loves it.', '["didn''t use to","didn''t using to","doesn''t use to","wasn''t used to"]', NULL, 0, 'Nella forma negativa si dice ''didn''t use to'' (senza -d), perché ''did'' porta già il passato. ''Didn''t using to'' è impossibile, ''doesn''t'' è al presente e ''wasn''t used to'' significa ''non era abituata'', non ''prima non le piaceva''.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q514', 'Translate: ''Abitavamo a Londra quando ero piccolo.''', '["We used to live in London when I was a kid.","We used to lived in London when I was a kid.","We are used to live in London when I was a kid.","We use to live in London when I was a kid."]', NULL, 0, 'Per le abitudini e le situazioni passate si usa ''used to'' + verbo base: ''We used to live''. ''Used to lived'' ha due passati, ''are used to'' è un presente e vuol dire ''siamo abituati'', e ''use to'' senza -d è sbagliato nelle frasi affermative.', 'used-to', 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q515', 'Translate: ''Non fumava, ma ora fuma un pacchetto al giorno.''', '["He didn''t use to smoke, but now he smokes a pack a day.","He didn''t used to smoke, but now he smokes a pack a day.","He wasn''t used to smoke, but now he smokes a pack a day.","He hasn''t used to smoke, but now he smokes a pack a day."]', NULL, 0, 'Il negativo di ''used to'' è ''didn''t use to'' + verbo base: dopo ''didn''t'' non va la -d. ''Wasn''t used to'' significa ''non era abituato'' e ''hasn''t used to'' non esiste.', 'used-to', 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q516', 'There _____ be a park here, but now there is a supermarket.', '["used to","use to","was","is"]', NULL, 0, '''There used to be'' indica una situazione che esisteva nel passato e ora non c''è più (il parco). ''Was'' e ''is'' non si possono mettere prima di ''be'', e ''use to'' senza -d è sbagliato.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q517', 'I _____ have a dog, but he died last year.', '["used to","use to","was used to","am used to"]', NULL, 0, '''Used to'' + verbo base descrive qualcosa che era vero nel passato e ora non lo è più (avevo un cane, ora no). ''Was/am used to'' significa ''ero/sono abituato'' e vuole un nome o un verbo in -ing, non ''have''.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q518', 'What did you _____ do on Sundays?', '["use to","used to","use","used"]', NULL, 0, 'Dopo ''did'' il verbo resta alla forma base, quindi ''use to'' senza -d: ''What did you use to do?''. ''Used to'' ripeterebbe il passato, che ''did'' ha già espresso.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q519', 'Translate: ''Andavamo al mare ogni estate.''', '["We used to go to the sea every summer.","We use to go to the sea every summer.","We were used to go to the sea every summer.","We had gone to the sea every summer."]', NULL, 0, 'Per un''azione ripetuta nel passato e ora finita si usa ''used to'' + verbo base: ''We used to go''. ''Use to'' senza -d è sbagliato, ''were used to go'' non esiste e ''had gone'' è un trapassato che non rende ''andavamo''.', 'used-to', 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q520', 'Translate: ''Aveva i capelli lunghi, vero?''', '["She used to have long hair, didn''t she?","She used to have long hair, doesn''t she?","She used to had long hair, didn''t she?","She use to have long hair, didn''t she?"]', NULL, 0, '''Used to'' funziona come un verbo al passato semplice, quindi il tag è ''didn''t she?''. ''Doesn''t'' è al presente, e ''used to had'' o ''use to have'' sono forme sbagliate.', 'used-to', 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q521', 'He _____ be so grumpy when he was younger.', '["didn''t use to","didn''t using to","wasn''t use to","not used to"]', NULL, 0, 'Una caratteristica del passato che è cambiata si nega con ''didn''t use to'' + verbo base. Dopo ''didn''t'' non va -ing né -d, e ''wasn''t use to'' e ''not used to'' non sono forme corrette qui.', 'used-to', 'Grammatica', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q522', 'We _____ walk to school every day.', '["used to","use to","were used to","are used to"]', NULL, 0, '''Used to'' + verbo base indica un''abitudine passata (andavamo a scuola a piedi). ''Be used to'' vuol dire ''essere abituato'' e vuole il verbo in -ing, quindi ''were used to walk'' è sbagliato.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q523', 'Did she _____ work in a bank?', '["use to","used to","use","used"]', NULL, 0, 'Nella domanda al passato ''did'' porta il tempo, quindi ''use to'' perde la -d: ''Did she use to...?''. ''Used to'' dopo ''did'' ripeterebbe il passato.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q524', 'I _____ think that spiders were insects.', '["used to","use to","was used to","am used to"]', NULL, 0, 'Una convinzione che avevo nel passato e ora non ho più si esprime con ''used to'' + verbo base. ''Use to'' senza -d è sbagliato nelle frasi affermative e ''was/am used to'' significa ''ero/sono abituato''.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q525', 'They _____ travel a lot before they had children.', '["used to","use to","were used to","are used to"]', NULL, 0, '''Used to'' + verbo base indica un''abitudine passata che è finita (viaggiavano molto prima di avere figli). ''Were used to'' significa ''erano abituati'' e vuole un nome o un verbo in -ing.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q526', 'Translate: ''Prima non mi piaceva la verdura.''', '["I didn''t use to like vegetables.","I didn''t used to like vegetables.","I wasn''t used to like vegetables.","I hadn''t used to like vegetables."]', NULL, 0, 'Il negativo di ''used to'' è ''didn''t use to'' + verbo base, senza -d. ''Wasn''t used to'' significa ''non ero abituato'' e ''hadn''t used to'' non è una forma corretta.', 'used-to', 'Traduzione', 'B1', 'Used to', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q527', 'It''s a beautiful day, _____?', '["isn''t it","is it","does it","doesn''t it"]', NULL, 0, 'Se la frase è affermativa, il tag è negativo e ripete il verbo ''to be'': ''It''s ... isn''t it?''. ''Does/doesn''t it'' userebbe un ausiliare che nella frase non c''è.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q528', 'You don''t like coffee, _____?', '["do you","don''t you","are you","aren''t you"]', NULL, 0, 'Se la frase è negativa, il tag è affermativo e usa lo stesso ausiliare (''don''t'' -> ''do you''). ''Don''t you'' sarebbe un tag negativo dopo una frase già negativa.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q529', 'She went to Paris, _____?', '["didn''t she","did she","doesn''t she","wasn''t she"]', NULL, 0, 'Il tag riprende l''ausiliare del passato semplice, cioè ''did'', e si inverte la polarità: frase affermativa, tag negativo ''didn''t she?''. ''Doesn''t'' è al presente e ''wasn''t'' non c''entra con ''went''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q530', 'Translate: ''Siete italiani, vero?''', '["You are Italian, aren''t you?","You are Italian, isn''t it?","You are Italian, don''t you?","You are Italian, are you?"]', NULL, 0, 'Il tag ripete il soggetto (you) e il verbo ''to be'' (are) in forma negativa, perché la frase è affermativa: ''aren''t you?''. ''Isn''t it'' non concorda con ''you'' e ''don''t you'' usa un ausiliare sbagliato.', 'question-tags', 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q531', 'Translate: ''Non hai visto il film, vero?''', '["You haven''t seen the movie, have you?","You haven''t seen the movie, haven''t you?","You didn''t see the movie, have you?","You haven''t seen the movie, did you?"]', NULL, 0, 'Nel present perfect negativo il tag è affermativo e usa ''have'': ''haven''t seen... have you?''. ''Haven''t you'' è negativo dopo una frase negativa e ''did you'' non è l''ausiliare del present perfect.', 'question-tags', 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q532', 'They have finished the project, _____?', '["haven''t they","have they","didn''t they","don''t they"]', NULL, 0, 'Nel present perfect il tag riprende ''have'' e, con una frase affermativa, è negativo: ''haven''t they?''. ''Didn''t'' e ''don''t'' sono ausiliari del passato e del presente semplice.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q533', 'He can speak Spanish, _____?', '["can''t he","can he","doesn''t he","isn''t he"]', NULL, 0, 'Con un verbo modale il tag riprende lo stesso modale con polarità opposta: ''can'' -> ''can''t he?''. ''Doesn''t he'' e ''isn''t he'' non c''entrano con ''can''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q534', 'You will come to the party, _____?', '["won''t you","will you","don''t you","aren''t you"]', NULL, 0, 'Il tag riprende l''ausiliare ''will'' e, con la frase affermativa, è negativo: ''won''t you?''. ''Don''t'' e ''aren''t'' sono ausiliari di altri tempi.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q535', 'Translate: ''Fa freddo oggi, no?''', '["It''s cold today, isn''t it?","It''s cold today, is it?","It''s cold today, doesn''t it?","It''s cold today, wasn''t it?"]', NULL, 0, 'Quando la frase usa ''to be'' al presente, il tag riprende ''is'' in negativo: ''It''s cold today, isn''t it?''. ''Is it'' ripeterebbe la polarità affermativa e ''doesn''t/wasn''t'' non sono corretti.', 'question-tags', 'Traduzione', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q536', 'Translate: ''Lui non sa nuotare, vero?''', '["He can''t swim, can he?","He can''t swim, can''t he?","He doesn''t know to swim, doesn''t he?","He can''t swim, does he?"]', NULL, 0, 'La frase è negativa (''can''t swim''), quindi il tag è affermativo e riprende il modale: ''can he?''. ''Can''t he'' sarebbe negativo dopo una frase negativa, e ''does he'' non riprende ''can''.', 'question-tags', 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q537', 'We should leave now, _____?', '["shouldn''t we","should we","don''t we","aren''t we"]', NULL, 0, 'Con ''should'' il tag usa lo stesso modale in negativo: ''shouldn''t we?''. ''Don''t we'' e ''aren''t we'' usano ausiliari diversi da quello della frase.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q538', 'She was at home, _____?', '["wasn''t she","was she","didn''t she","isn''t she"]', NULL, 0, 'Con ''was'' il tag riprende ''was'' in negativo perché la frase è affermativa: ''wasn''t she?''. ''Didn''t'' e ''isn''t'' non corrispondono al verbo della frase.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q539', 'I am right, _____?', '["aren''t I","am not I","don''t I","isn''t I"]', NULL, 0, 'Dopo ''I am'' il tag è la forma irregolare ''aren''t I?''. ''Am not I'' e ''isn''t I'' non esistono, e ''don''t I'' userebbe l''ausiliare sbagliato.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q540', 'Let''s go for a walk, _____?', '["shall we","will we","do we","are we"]', NULL, 0, 'Dopo ''Let''s'' (proposta) il tag fisso è ''shall we?''. ''Will we'', ''do we'' e ''are we'' non si usano con questo tipo di frase.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q541', 'You wouldn''t do that, _____?', '["would you","wouldn''t you","do you","did you"]', NULL, 0, '''Wouldn''t'' è negativo, quindi il tag è affermativo e riprende lo stesso modale: ''would you?''. ''Wouldn''t you'' sarebbe negativo dopo una frase negativa.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q542', 'Translate: ''Tua sorella vive qui, vero?''', '["Your sister lives here, doesn''t she?","Your sister lives here, isn''t she?","Your sister lives here, doesn''t it?","Your sister lives here, don''t she?"]', NULL, 0, 'Il verbo ''lives'' è al presente semplice con ''she'', quindi il tag usa ''does'' in negativo: ''doesn''t she?''. ''Isn''t she'' non riprende il verbo, ''doesn''t it'' ha il soggetto sbagliato e ''don''t she'' non concorda.', 'question-tags', 'Traduzione', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q543', 'They have been traveling all day. They _____ be tired.', '["must","can''t","must to","ought"]', NULL, 0, 'Hanno viaggiato tutto il giorno, quindi siamo quasi certi: per una deduzione forte si usa ''must''. ''Can''t'' direbbe che è impossibile, ''must to'' è sbagliato (i modali non vogliono ''to'') e ''ought'' vuole ''to''.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q544', 'He just ate a huge meal. He _____ be hungry.', '["can''t","must","don''t","must to"]', NULL, 0, 'Ha appena mangiato tantissimo, quindi è quasi impossibile che abbia fame: per l''impossibilità si usa ''can''t''. ''Must'' direbbe l''opposto, ''don''t'' non regge con be e ''must to'' è sbagliato.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q545', 'I can''t find my phone. It _____ be in the car, but I''m not sure.', '["might","must","can''t","should"]', NULL, 0, 'Dice ''non sono sicuro'', quindi è solo una possibilità e serve ''might''. ''Must'' esprimerebbe certezza e ''can''t'' impossibilità.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q546', 'Translate: ''Deve essere tardi, è già buio.''', '["It must be late, it''s already dark.","It can be late, it''s already dark.","It may to be late, it''s already dark.","It should be late, it''s already dark."]', NULL, 0, 'Il buio è un indizio, quindi per una deduzione forte si usa ''must'' + verbo base: ''It must be late''. ''May to be'' è sbagliato perché dopo i modali non va ''to'', e ''can'' non esprime una deduzione positiva.', 'modals-deduction', 'Traduzione', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q547', 'Translate: ''Non può essere vero!''', '["It can''t be true!","It mustn''t be true!","It shouldn''t be true!","It might not be true!"]', NULL, 0, '''Non può essere vero'' esprime impossibilità, e il contrario di ''must'' nelle deduzioni è ''can''t''. ''Mustn''t'' indica un divieto e non una deduzione.', 'modals-deduction', 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q548', 'That _____ be John''s car. His car is blue, not red.', '["can''t","must","might","could"]', NULL, 0, 'L''auto di John è blu, non rossa: quella rossa non può essere la sua. Per escludere qualcosa con certezza si usa ''can''t'', non ''must''.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q549', 'You''ve been working since 6 AM. You _____ be exhausted!', '["must","can''t","ought","must to"]', NULL, 0, 'Lavori dalle 6 del mattino, quindi la conclusione è quasi certa: ''must'' + verbo base. ''Can''t'' direbbe che è impossibile, ''ought'' vuole ''to'' e ''must to'' è sbagliato (i modali non vogliono ''to'').', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q550', 'Take an umbrella. It _____ rain later.', '["might","must","can''t","ought"]', NULL, 0, 'Prendere l''ombrello ''per sicurezza'' significa che la pioggia è possibile ma non certa: serve ''might''. ''Must'' esprimerebbe certezza, ''can''t'' escluderebbe la pioggia e ''ought'' vuole ''to''.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q551', 'Translate: ''Potrebbe piovere più tardi.''', '["It might rain later.","It must rain later.","It can rain later.","It will rain later."]', NULL, 0, '''Potrebbe piovere'' è una possibilità, e in inglese si rende con ''might'' (o ''could''). ''Must'' esprime certezza e ''will'' è una previsione sicura.', 'modals-deduction', 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q552', 'Translate: ''Quello dev''essere il tuo nuovo capo.''', '["That must be your new boss.","That can''t be your new boss.","That must to be your new boss.","That musts be your new boss."]', NULL, 0, '''Dev''essere'' è una deduzione quasi certa: ''must'' + verbo base. ''That can''t be'' direbbe che è impossibile, ''must to be'' è sbagliato perché i modali non vogliono ''to'', e ''musts'' non esiste (i modali non prendono la -s).', 'modals-deduction', 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q553', 'She speaks perfect French, has a French passport and her parents live in Paris. She _____ be from France.', '["must","can''t","ought","must to"]', NULL, 0, 'Lingua perfetta, passaporto e genitori a Parigi sono prove molto forti, quindi usiamo ''must'' per una quasi certezza. ''Can''t'' direbbe il contrario, ''ought'' vuole ''to'' e ''must to'' è sbagliato.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q554', 'He is holding a cinema ticket for tonight''s film. He _____ be going to the cinema.', '["must","can''t","ought","must to"]', NULL, 0, 'Ha in mano il biglietto per stasera, quindi sono prove forti e usiamo ''must be going'' per una deduzione. ''Can''t'' sarebbe l''opposto, ''ought'' vuole ''to'' e ''must to'' è sbagliato.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q555', 'It''s 3 a.m., the lights are out and the house is silent. They _____ be asleep.', '["must","can''t","ought","must to"]', NULL, 0, 'Sono le 3, luci spente e casa silenziosa: tutto fa pensare che dormano, quindi ''must''. ''Can''t'' direbbe che è impossibile, ''ought'' vuole ''to'' e ''must to'' è sbagliato.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q556', 'She _____ be at home, but I haven''t checked.', '["could","must","can''t","won''t"]', NULL, 0, 'Chi parla non ha controllato, quindi esprime una semplice possibilità e ''could'' va bene (come ''might''). ''Must'' direbbe certezza e ''can''t'' impossibilità.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q557', 'Tom is in Tokyo until Friday, so that _____ be him at the door.', '["can''t","must","ought","must to"]', NULL, 0, 'Tom è a Tokyo fino a venerdì, quindi è impossibile che sia lui alla porta: per l''impossibilità si usa ''can''t''. ''Must'' direbbe che siamo certi che sia lui, ''ought'' vuole ''to'' e ''must to'' è sbagliato.', 'modals-deduction', 'Grammatica', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q558', 'Translate: ''Questa non può essere la casa giusta.''', '["This can''t be the right house.","This mustn''t be the right house.","This shouldn''t be the right house.","This wouldn''t be the right house."]', NULL, 0, 'Per dire che qualcosa è impossibile in base a ciò che si sa, si usa ''can''t be'' (''non può essere''). ''Mustn''t'' esprime un divieto e non una deduzione.', 'modals-deduction', 'Traduzione', 'B1', 'Modals of Deduction', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q559', 'Complete the sentence: ''Don''t forget _____ the front door before you go to bed.''', '["to lock","locking","lock","locked"]', NULL, 0, 'Dopo ''forget'' si usa ''to'' + verbo base quando si parla di un''azione da fare (non dimenticare di chiudere la porta). Con ''locking'' avrebbe il senso di ''ricordare di aver chiuso''.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q560', 'Complete the sentence: ''I will never forget _____ the Colosseum for the very first time.''', '["seeing","to see","see","saw"]', NULL, 0, 'Con ''forget'' + -ing si parla di un ricordo di un''azione già avvenuta: non dimenticherò mai di aver visto il Colosseo. ''To see'' indicherebbe un''azione ancora da compiere.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q561', 'Complete the sentence: ''On the road trip, we stopped _____ a coffee and stretch our legs.''', '["to have","having","have","had"]', NULL, 0, 'Dopo ''stop'' + ''to'' + verbo base si indica lo scopo per cui ci si ferma (ci siamo fermati per prendere un caffè). Con ''having'' sembrerebbe che avessero smesso di prendere il caffè.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q562', 'Complete the sentence: ''The doctor told him that he must stop _____ immediately for his health.''', '["smoking","to smoke","smoke","smoked"]', NULL, 0, '''Stop'' + -ing significa smettere di fare un''azione, quindi ''stop smoking'' vuol dire smettere di fumare. ''Stop to smoke'' vorrebbe dire fermarsi per fumare.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q563', 'Complete the sentence: ''If the app keeps crashing, try _____ your smartphone.''', '["restarting","to restarting","restart","restarted"]', NULL, 0, '''Try'' + -ing significa provare qualcosa come esperimento per risolvere un problema: prova a riavviare il telefono. ''To restarting'' mescola le due costruzioni, ''restart'' e ''restarted'' non sono forme possibili dopo try in questa frase.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q564', 'Complete the sentence: ''I tried _____ the heavy wardrobe, but it was impossible alone.''', '["to lift","to lifting","lift","lifted"]', NULL, 0, '''Try'' + ''to'' + verbo base indica lo sforzo di fare qualcosa di difficile (provai a sollevare l''armadio, ma era impossibile). ''To lifting'' mescola le due costruzioni, ''lift'' e ''lifted'' non sono forme possibili dopo tried in questa frase.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q565', 'Complete the sentence: ''Look at the kitchen floor! It really needs _____.''', '["cleaning","to clean","clean","cleaned"]', NULL, 0, '''Need'' + -ing ha un significato passivo: il pavimento ha bisogno di essere pulito (needs cleaning). ''To clean'' vorrebbe dire che è il pavimento a dover pulire qualcosa.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q566', 'Complete the sentence: ''I am really looking forward to _____ you at the conference next week.''', '["meeting","meet","to meet","met"]', NULL, 0, 'In ''look forward to'' la parola ''to'' è una preposizione, e dopo una preposizione si usa la forma in -ing: ''looking forward to meeting''. ''Meet'' o ''to meet'' sono sbagliati.', 'gerunds-infinitives', 'Grammatica', 'B1', 'Gerunds vs Infinitives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q567', 'Translate: ''Non riesco a fare a meno di ridere quando sento quella barzelletta.''', '["I can''t help laughing when I hear that joke.","I can''t help to laugh when I hear that joke.","I can''t stop to laugh when I hear that joke.","I can''t avoid to laugh when I hear that joke."]', NULL, 0, '''Can''t help'' + -ing è un''espressione fissa che vuol dire ''non riuscire a fare a meno di''. ''Help to laugh'', ''stop to laugh'' e ''avoid to laugh'' non esistono o hanno un altro significato.', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q568', 'Translate: ''È inutile piangere sul latte versato.''', '["It''s no use crying over spilled milk.","It''s no use cry over spilled milk.","It''s not useful crying on spilled milk.","It has no use to cry on spilled milk."]', NULL, 0, '''It''s no use'' è seguito dal gerundio: ''It''s no use crying''. ''No use cry'' non ha il gerundio, e le altre opzioni inventano costruzioni sbagliate (''not useful crying'', ''has no use to cry on'').', 'gerunds-infinitives', 'Traduzione', 'B1', 'Gerunds vs Infinitives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q569', 'Complete the sentence: ''Could you please give me _____ about the flight schedule?''', '["some information","an information","some informations","many informations"]', NULL, 0, '''Information'' è non numerabile: non prende l''articolo ''an'' né la -s del plurale. Si dice ''some information'', mai ''informations''.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q570', 'Complete the sentence: ''My grandfather gave me a very useful _____ before my interview.''', '["piece of advice","advice","advices","piece of advices"]', NULL, 0, '''Advice'' è non numerabile e non ha plurale, per questo per un singolo consiglio si dice ''a piece of advice''. Dopo ''a very useful'' serve un nome singolare numerabile, quindi ''advice'' da solo non va.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q571', 'Complete the sentence: ''The news _____ so surprising that nobody believed it at first.''', '["was","were","are","have been"]', NULL, 0, '''News'' finisce in -s ma è singolare e non numerabile, quindi vuole il verbo al singolare. Si usa ''was'', perché il contesto è al passato.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q572', 'Complete the sentence: ''All the furniture in their new apartment _____ made of solid oak.''', '["is","are","were","have been"]', NULL, 0, '''Furniture'' è non numerabile e vuole il verbo al singolare, quindi ''is''. ''Are'', ''were'' e ''have been'' sono forme plurali.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q573', 'Complete the sentence: ''How _____ luggage are you planning to take on the flight?''', '["much","many","few","a few"]', NULL, 0, '''Luggage'' è non numerabile, e con i non numerabili in una domanda di quantità si usa ''how much''. ''Many'', ''few'' e ''a few'' vogliono i nomi numerabili al plurale.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q574', 'Complete the sentence: ''The police _____ investigating the cause of the fire.''', '["are","is","was","has been"]', NULL, 0, '''Police'' è un nome collettivo plurale: vuole sempre il verbo al plurale (''are''). ''Is'', ''was'' e ''has been'' sono singolari.', 'quantifiers', 'Grammatica', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q575', 'Translate: ''Non ho molti compiti per domani.''', '["I don''t have much homework for tomorrow.","I don''t have many homeworks for tomorrow.","I don''t have many homework for tomorrow.","I haven''t much homeworks for tomorrow."]', NULL, 0, '''Homework'' è non numerabile: non ha plurale (''homeworks'' è sbagliato) e con una frase negativa si usa ''much'', non ''many''.', 'quantifiers', 'Traduzione', 'B1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q577', 'Complete the sentence: ''Let''s take a short break, _____?''', '["shall we","will we","don''t we","aren''t we"]', NULL, 0, 'Dopo una proposta introdotta da ''Let''s'' il tag fisso è ''shall we?''. ''Will we'', ''don''t we'' e ''aren''t we'' non si usano con ''Let''s''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q578', 'Complete the sentence: ''Close the window, _____?''', '["will you","do you","don''t you","shall you"]', NULL, 0, 'Dopo un imperativo (un ordine o una richiesta) il tag è ''will you?''. ''Do you'', ''don''t you'' e ''shall you'' non si usano con gli imperativi.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q579', 'Complete the sentence: ''She never drinks alcohol, _____?''', '["does she","doesn''t she","is she","isn''t she"]', NULL, 0, '''Never'' ha un significato negativo, quindi la frase conta come negativa e il tag è affermativo: ''does she?''. ''Doesn''t she'' sarebbe negativo dopo una frase già negativa.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q580', 'Complete the sentence: ''Nobody phoned while I was away, _____?''', '["did they","didn''t they","did he","didn''t he"]', NULL, 0, '''Nobody'' è negativo, quindi il tag è affermativo, e si riprende con ''they'': ''did they?''. ''Didn''t they'' sarebbe negativo, e ''he'' è meno corretto con ''nobody''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q581', 'Complete the sentence: ''Nothing went wrong during the test, _____?''', '["did it","didn''t it","did they","was it"]', NULL, 0, '''Nothing'' è negativo, quindi il tag è affermativo, e si riprende con ''it'' perché si tratta di una cosa: ''did it?''. ''Didn''t it'' sarebbe negativo e ''was it'' non riprende ''went''.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q582', 'Complete the sentence: ''Everybody is ready for the presentation, _____?''', '["aren''t they","isn''t he","isn''t it","are they"]', NULL, 0, '''Everybody is ready'' è una frase affermativa, quindi il tag è negativo; per ''everybody'' si usa ''they'' e il verbo ''be'' si ripete: ''aren''t they?''. ''Are they'' sarebbe affermativo dopo una frase affermativa.', 'question-tags', 'Grammatica', 'B1', 'Question Tags', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q583', 'Complete the sentence: ''I will call you as soon as I _____ at the airport.''', '["arrive","will arrive","am arriving","arrived"]', NULL, 0, 'Dopo ''as soon as'' si usa il present simple anche se parliamo del futuro: ''as soon as I arrive''. ''Will arrive'' è sbagliato nelle frasi temporali.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q584', 'Complete the sentence: ''We will stay inside until the heavy rain _____.''', '["stops","will stop","stopped","is stopping"]', NULL, 0, 'Dopo ''until'' per il futuro si usa il present simple, mai ''will'': ''until the rain stops''. ''Will stop'' non si usa in questa posizione.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q585', 'Complete the sentence: ''You won''t pass your driving test unless you _____ every day.''', '["practice","don''t practice","will practice","won''t practice"]', NULL, 0, '''Unless'' significa già ''se non'', quindi il verbo che segue è affermativo e al present simple: ''unless you practice''. ''Don''t practice'' crea una doppia negazione e ''will'' non si usa dopo ''unless''.', 'first-conditional', 'Grammatica', 'B1', 'First Conditional', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q586', 'Complete the sentence: ''Take an umbrella with you in case it _____ later.''', '["rains","will rain","rained","is raining"]', NULL, 0, 'Dopo ''in case'' per il futuro si usa il present simple: ''in case it rains''. ''Will rain'' non si usa dopo ''in case''.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q587', 'Translate: ''Te lo dirò non appena lo saprò.''', '["I will tell you as soon as I know.","I will tell you as soon as I will know.","I tell you as soon as I will know.","I will tell to you as soon as I know."]', NULL, 0, 'Dopo ''as soon as'' si usa il present simple, quindi ''as soon as I know''. ''Will know'' è sbagliato nelle frasi temporali, e ''tell to you'' è un errore: dopo ''tell'' non va ''to''.', 'present-simple', 'Traduzione', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q588', 'Complete the sentence: ''I _____ what you mean, but I still disagree with your conclusion.''', '["understand","am understanding","have understand","understanding"]', NULL, 0, '''Understand'' è un verbo di stato (descrive una condizione mentale) e non si usa nella forma continua: ''I understand''. ''Am understanding'' e ''have understand'' sono sbagliati.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q589', 'Complete the sentence: ''Please don''t disturb Marco right now; he _____ lunch with a client.''', '["is having","has","have","had"]', NULL, 0, '''Have'' nel senso di ''mangiare'' è un''azione e può stare nel present continuous. ''Right now'' indica che succede in questo momento, quindi ''is having''. ''Has'' darebbe l''idea di un''abitudine.', 'present-continuous', 'Grammatica', 'B1', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q590', 'Complete the sentence: ''Be quiet for a minute! I _____ about how to solve this math problem.''', '["am thinking","think","thinks","thought"]', NULL, 0, '''Think'' nel senso di ''riflettere'' è un''azione in corso e vuole il present continuous. ''Be quiet for a minute'' mostra che sta succedendo ora: ''I am thinking''.', 'present-continuous', 'Grammatica', 'B1', 'Present Continuous', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q591', 'Complete the sentence: ''I _____ that learning English is essential for your career.''', '["think","am thinking","thinking","thought"]', NULL, 0, 'Quando ''think'' esprime un''opinione è un verbo di stato e non si usa al continuous: ''I think that...''. ''Am thinking'' indicherebbe l''azione di riflettere in questo momento.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q592', 'Complete the sentence: ''This delicious pasta dish _____ of fresh tomatoes and basil.''', '["tastes","is tasting","taste","was tasting"]', NULL, 0, '''Taste'' nel senso di ''avere sapore'' è un verbo di stato e va al present simple. Con il soggetto ''dish'' (terza persona singolare) serve la -s: ''tastes''.', 'present-simple', 'Grammatica', 'B1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q593', 'Complete the sentence: ''For _____ details regarding the hotel booking, contact customer support.''', '["further","farther","farthest","more far"]', NULL, 0, 'Nel senso figurato di ''ulteriore'' si usa ''further details''. ''Farther'' si usa per la distanza fisica, e ''farthest'' è un superlativo e ''more far'' non esiste.', 'comparatives-superlatives', 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q594', 'Complete the sentence: ''Today the traffic is _____ than it was yesterday morning.''', '["heavier","more heavy","more heavier","heaviest"]', NULL, 0, 'Gli aggettivi di due sillabe che finiscono in -y fanno il comparativo con -ier: ''heavy'' -> ''heavier''. ''More heavy'' e ''more heavier'' sono sbagliati.', 'comparatives-superlatives', 'Grammatica', 'B1', 'Comparatives and Superlatives', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q595', 'Complete the sentence: ''The new laptop is great, but it is not _____ fast as I expected.''', '["as","so much","more","like"]', NULL, 0, 'Il comparativo di uguaglianza si forma con ''as ... as'', anche in forma negativa: ''not as fast as''. ''So much'', ''more'' e ''like'' non si usano così.', 'comparatives-superlatives', 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q596', 'Complete the sentence: ''The _____ you practice speaking, the _____ confident you will feel.''', '["more / more","most / most","better / better","much / much"]', NULL, 0, 'La struttura ''the + comparativo, the + comparativo'' esprime due cose che crescono insieme: ''the more you practice, the more confident you feel''. ''Most'' è un superlativo e ''much'' non è un comparativo.', 'comparatives-superlatives', 'Grammatica', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q597', 'Translate: ''Mio fratello maggiore vive a Londra.''', '["My elder brother lives in London.","My elder brother living in London.","My more old brother lives in London.","My eldest brother live in London."]', NULL, 0, '''Elder'' (come ''older'') si usa solo davanti a un nome per dire ''maggiore'' tra fratelli: ''my elder brother''. Le altre opzioni sbagliano il verbo (''living'' senza ausiliare, ''live'' senza -s) o inventano ''more old''.', 'comparatives-superlatives', 'Traduzione', 'B1', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q598', 'Complete the sentence: ''When I moved to the UK, it took me a long time to get used to _____ on the left.''', '["driving","drive","drove","driven"]', NULL, 0, 'In ''get used to'' la parola ''to'' è una preposizione, quindi segue la forma in -ing: ''get used to driving'' (abituarsi a guidare). ''Drive'' o ''drove'' non vanno dopo una preposizione.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q599', 'Complete the sentence: ''I am a nurse, so I am used to _____ night shifts.''', '["working","work","worked","to work"]', NULL, 0, 'In ''be used to'' (essere abituato) la parola ''to'' è una preposizione, quindi segue il verbo in -ing: ''used to working''. ''Work'' e ''to work'' sono sbagliati.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q600', 'Complete the sentence: ''I _____ drink coffee when I was younger, but now I drink three cups a day.''', '["didn''t use to","don''t use to","not used to","wasn''t used to"]', NULL, 0, 'Il negativo di ''used to'' è ''didn''t use to'', perché ''did'' porta già il passato. ''Don''t use to'' è al presente, ''wasn''t used to'' significa ''non ero abituato'' e vuole un nome o -ing, mentre ''not used to'' manca dell''ausiliare.', 'used-to', 'Grammatica', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q601', 'Translate: ''Ti sei abituato al clima freddo?''', '["Have you got used to the cold weather?","Did you use to the cold weather?","Have you used to the cold weather?","Did you get use to cold weather?"]', NULL, 0, '''Get used to'' + nome significa ''abituarsi a''; al present perfect (''Have you got used to...?'') chiede se l''abitudine si è già formata. ''Use to'' da solo non regge un nome e ''get use'' è sbagliato: manca il participio ''used''.', 'used-to', 'Traduzione', 'B1', 'Used to', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q602', 'Complete the sentence: ''Venice, _____ is famous for its canals, attracts millions of tourists every year.''', '["which","that","where","what"]', NULL, 0, 'Nelle relative non restrittive (tra virgole) per le cose si usa ''which'', mai ''that''. ''Where'' non va bene perché Venice è il soggetto di ''is famous'', e ''what'' non è un pronome relativo.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q603', 'Complete the sentence: ''Mr. Davis, _____ you met yesterday at the reception, is our new director.''', '["whom","which","that","whose"]', NULL, 0, 'Per una persona complemento oggetto in una relativa tra virgole si usa ''whom'' (''you met'' ha già il suo soggetto). ''That'' non si usa tra virgole, ''which'' è per le cose e ''whose'' esprime possesso.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q604', 'Complete the sentence: ''That is the student _____ backpack was accidentally left in the classroom.''', '["whose","who''s","which","that''s"]', NULL, 0, '''Whose'' esprime possesso: ''the student whose backpack'' significa ''lo studente il cui zaino''. ''Who''s'' e ''that''s'' sono contrazioni di ''who is'' e ''that is'', e ''which'' è per le cose.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q605', 'Complete the sentence: ''The hotel _____ we stayed at during our holiday was right on the beach.''', '["that","where","what","whose"]', NULL, 0, '''Stayed at'' ha già la preposizione in fondo, quindi il pronome fa da oggetto e serve ''that'' (o ''which''). ''Where'' ripeterebbe il luogo (''where we stayed at''), ''whose'' indica possesso e ''what'' non è un pronome relativo.', 'relative-clauses', 'Grammatica', 'B1', 'Relative Clauses', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q606', 'Translate: ''Londra, che è la capitale del Regno Unito, ha molti musei gratuiti.''', '["London, which is the capital of the UK, has many free museums.","London, that is the capital of the UK, has many free museums.","London, where is the capital of the UK, has many free museums.","London, what is the capital of the UK, has many free museums."]', NULL, 0, 'Nelle relative non restrittive (tra virgole) per le cose si usa ''which'', non ''that''. ''Where'' si usa per un luogo e ''what'' non è un pronome relativo: davanti a ''is the capital'' serve ''which''.', 'relative-clauses', 'Traduzione', 'B1', 'Relative Clauses', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q612', 'Complete the sentence: ''Marco is a vegetarian, so he _____ meat.''', '["eats not","don''t eat","doesn''t eat","not eats"]', NULL, 2, 'Con he/she/it il present simple negativo si forma con ''doesn''t'' + verbo base senza -s: ''he doesn''t eat''. ''Don''t'' va con I/you/we/they, mentre ''eats not'' e ''not eats'' non sono forme corrette.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q615', 'Complete the sentence: ''Of all the subjects I studied this year, physics was the _____.''', '["hardly","hardest","most hard","more hard"]', NULL, 1, 'Il superlativo degli aggettivi brevi si forma con ''the'' + aggettivo + ''-est'': ''the hardest''. ''Most hard'' e ''more hard'' non si usano con un aggettivo di una sillaba, e ''hardly'' è un avverbio che significa ''a malapena''.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q616', 'Complete the sentence: ''We can''t make pancakes because there isn''t _____ flour left.''', '["some","a","many","any"]', NULL, 3, 'Con i nomi non numerabili come ''flour'' nelle frasi negative si usa ''any'', non ''some''. ''A'' e ''many'' richiedono nomi numerabili.', 'quantifiers', 'Grammatica', 'A2', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q617', 'Complete the sentence: ''Every morning Anna _____ to the university by bus.''', '["goes","go","going","is go"]', NULL, 0, 'Con he/she/it il verbo al present simple prende -s/-es: ''Anna goes''. ''Go'' va con I/you/we/they, ''going'' avrebbe bisogno di ''is'' e ''is go'' non esiste.', 'present-simple', 'Grammatica', 'A1', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q619', 'Complete the sentence: ''How often _____ your sister visit your grandparents?''', '["do","is","has","does"]', NULL, 3, 'Alla terza persona singolare la domanda al present simple si fa con ''does'' + soggetto + verbo base: ''How often does your sister visit...?''. ''Do'' va con I/you/we/they, mentre ''is'' e ''has'' non reggono il verbo base.', 'present-simple', 'Grammatica', 'A2', 'Present Simple', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q620', 'Choose the correct sentence.', '["Look! The children playing in the garden.","Look! The children is playing in the garden.","Look! The children are playing in the garden.","Look! The children plays in the garden."]', NULL, 2, 'Per un''azione in corso adesso (Look!) si usa il present continuous: ''be'' + -ing. Con ''the children'' (plurale) l''ausiliare è ''are''; ''is'' non concorda, e senza ausiliare o con ''plays'' la forma è sbagliata.', 'present-continuous', 'Grammatica', 'A1', 'Present Continuous', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q621', 'Complete the sentence: ''_____ a supermarket near the university?''', '["Do there","Is there","Are there","Has there"]', NULL, 1, '''A supermarket'' è singolare, quindi la domanda è ''Is there...?''. ''Are there'' si usa con i plurali, mentre ''Do there'' e ''Has there'' non esistono.', 'there-is-are', 'Grammatica', 'A1', 'There is / There are', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q628', 'Complete the sentence: ''My grandparents live _____ a small village near Bergamo.''', '["in","at","to","on"]', NULL, 0, 'Per dire dove si vive con città, paesi e villaggi si usa ''in'': ''live in a small village''. ''At'' è per punti precisi, ''on'' per superfici e strade, ''to'' indica movimento e non posizione.', 'prepositions-place', 'Grammatica', 'A1', 'Prepositions of Place', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q629', 'Complete the sentence: ''We went to my _____ house for dinner on Sunday.''', '["grandmother","grandmothers","grandmothers''s","grandmother''s"]', NULL, 3, 'Il possesso di una persona si esprime con nome + ''s: ''my grandmother''s house''. ''Grandmother'' senza ''s non esprime possesso, ''grandmothers'' è un plurale e ''grandmothers''s'' non esiste.', 'possessive-s', 'Grammatica', 'A1', 'Possessive S', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q630', 'Complete the sentence: ''_____ does the library close on Fridays?'' ''At six o''clock.''', '["Who","What time","How much","Where"]', NULL, 1, 'Per chiedere a che ora accade qualcosa si usa ''What time''. ''Who'' chiede una persona, ''how much'' una quantità o un prezzo e ''where'' un luogo: nessuno dei tre può avere per risposta ''At six o''clock''.', 'questions-origins', 'Grammatica', 'A2', 'Questions and Origins', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q631', 'Complete the sentence: ''How _____ money do you spend on books every semester?''', '["many","few","any","much"]', NULL, 3, '''Money'' è non numerabile, quindi si dice ''How much money''. ''Many'' e ''few'' si usano con i nomi numerabili plurali, e ''any'' non si mette dopo ''how'' in questa domanda.', 'quantifiers', 'Grammatica', 'A1', 'Quantifiers', 0);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q632', 'Complete the sentence: ''Sorry, I _____ come to the party on Saturday because I have to work.''', '["not can","don''t can","can''t","can''t to"]', NULL, 2, 'I verbi modali non usano ''do'' nella negazione e vogliono il verbo base senza ''to'': ''I can''t come''. ''Not can'' e ''don''t can'' sono sbagliate, e ''can''t to'' ha un ''to'' di troppo.', 'modals-ability-permission', 'Grammatica', 'A1', 'Modals of Ability and Permission', 1);
INSERT OR REPLACE INTO questions (id, prompt, options, extra_option, correct_index, explanation_it, theory_id, category, level, grammar_topic, core) VALUES ('q635', 'Complete the sentence: ''I think this book is _____ than the film.''', '["more interesting","interestinger","most interesting","very interesting"]', NULL, 0, 'Gli aggettivi lunghi come ''interesting'' formano il comparativo con ''more'': ''more interesting than''. ''-er'' si usa solo con aggettivi brevi, ''most interesting'' è un superlativo e ''very interesting'' non regge ''than''.', 'comparatives-superlatives', 'Grammatica', 'A2', 'Comparatives and Superlatives', 0);
